def lazy_analysis_includes_mask_total(mode: object) -> bool:
    return str(mode or "") in {LAZY_COMBINED_ANALYSIS_MODE, "mask_total"}


def lazy_analysis_includes_ownership(mode: object) -> bool:
    return str(mode or "") in {LAZY_COMBINED_ANALYSIS_MODE, "ownership"}


def lazy_analysis_mode_label(mode: object) -> str:
    normalized = str(mode or "")
    if normalized == LAZY_COMBINED_ANALYSIS_MODE:
        return "plate total + confidence-gated per-seedling ownership"
    if normalized == "ownership":
        return "per-seedling ownership"
    if normalized == POTATO_ENDPOINT_ANALYSIS_MODE:
        return "potato endpoint"
    return "plate total"


