def _normalize_lazy_source_rgb(image: np.ndarray | None, shape_hw: tuple[int, int]) -> np.ndarray:
    h, w = int(shape_hw[0]), int(shape_hw[1])
    if h <= 0 or w <= 0:
        return np.zeros((max(0, h), max(0, w), 3), dtype=np.uint8)
    if image is None:
        return np.zeros((h, w, 3), dtype=np.uint8)
    arr = np.asarray(image)
    if arr.ndim == 2:
        arr = cv2.cvtColor(arr.astype(np.uint8, copy=False), cv2.COLOR_GRAY2RGB)
    elif arr.ndim == 3 and arr.shape[2] == 1:
        arr = np.repeat(arr, 3, axis=2)
    elif arr.ndim == 3 and arr.shape[2] >= 3:
        arr = arr[:, :, :3]
    else:
        return np.zeros((h, w, 3), dtype=np.uint8)
    if arr.dtype != np.uint8:
        arr = np.clip(arr, 0, 255).astype(np.uint8)
    if arr.shape[:2] != (h, w):
        arr = cv2.resize(arr, (w, h), interpolation=cv2.INTER_LINEAR)
    return np.ascontiguousarray(arr, dtype=np.uint8)


def _optional_env_path(name: str) -> Path | None:
    raw = str(os.environ.get(name, "") or "").strip()
    return Path(raw).expanduser() if raw else None


