    def _build_ui(self) -> None:
        self._build_menu()
        self._build_toolbar()
        self._build_statusbar()

        self.main_splitter = QSplitter(Qt.Horizontal, self)
        self.main_splitter.setChildrenCollapsible(False)
        self.main_splitter.setHandleWidth(8)
        self.main_splitter.addWidget(self._build_dataset_panel())
        self.main_splitter.addWidget(self._build_tabs_panel())
        self.main_splitter.setStretchFactor(0, 0)
        self.main_splitter.setStretchFactor(1, 1)
        self.main_splitter.setSizes([304, 1296])
        self.setCentralWidget(self.main_splitter)
        self.main_splitter.splitterMoved.connect(self._on_main_splitter_moved)

        self._build_layers_dock()
        self._refresh_dataset_logo()
        self._apply_compact_ui_mode()

    def _on_main_splitter_moved(self, *_args) -> None:
        self._refresh_dataset_logo()
        if not hasattr(self, "main_splitter"):
            return
        sizes = self.main_splitter.sizes()
        if len(sizes) < 2:
            return
        left_width = int(sizes[0])
        if left_width > 0:
            self._dataset_panel_user_width = left_width
            self._reflow_dataset_controls(left_width)

    def _set_dirty(self, dirty: bool = True) -> None:
        if self._ignore_dirty_tracking:
            return
        dirty = bool(dirty)
        if self.is_dirty == dirty:
            return
        self.is_dirty = dirty
        self._update_window_title()

    def _update_window_title(self) -> None:
        project_name = self.project_path.name if self.project_path is not None else "Untitled Project"
        dirty_mark = " *" if self.is_dirty else ""
        self.setWindowTitle(f"{APP_TITLE} - {project_name}{dirty_mark}")

    def _update_undo_redo_actions(self) -> None:
        if self.undo_action is not None:
            self.undo_action.setEnabled(len(self.undo_history) > 0)
        if self.redo_action is not None:
            self.redo_action.setEnabled(len(self.redo_history) > 0)

    def _clear_stroke_history(self) -> None:
        self.undo_history.clear()
        self.redo_history.clear()
        self._pending_stroke_history.clear()
        self._update_undo_redo_actions()

    def _dataset_item_by_uid(self, uid: str) -> DatasetImageItem | None:
        lookup = str(uid)
        for item in self.dataset_items:
            if item.uid == lookup:
                return item
        return None

    def _history_target_layers(
        self,
        target: str,
        uid: str,
        create: bool = False,
    ) -> tuple[DatasetImageItem | None, dict[int, np.ndarray] | None, list[int], tuple[int, int]]:
        item = self._dataset_item_by_uid(uid)
        if item is None:
            return (None, None, [], (0, 0))
        shape = item.image.shape[:2]
        key = str(target).strip().lower()
        if key == "annotations":
            layers = ensure_layer_map(self.annotations, item.uid, self.classes, shape)
            return (item, layers, [int(cls.class_id) for cls in self.classes], shape)
        if key == "rf_seed":
            layers = self._rf_seed_layers_for_item(item, create=create)
            return (item, layers, [int(cls.class_id) for cls in self.classes], shape)
        if key == "foundation_prompt":
            layers = self._foundation_prompt_layers_for_item(item, create=create)
            return (item, layers, [FOUNDATION_POSITIVE_ID, FOUNDATION_NEGATIVE_ID], shape)
        return (item, None, [], shape)

    def _history_index_from_layers(
        self,
        layers: dict[int, np.ndarray],
        class_ids: list[int],
        shape_hw: tuple[int, int],
    ) -> np.ndarray:
        h, w = shape_hw
        index = np.zeros((h, w), dtype=np.uint8)
        for class_id in class_ids:
            layer = layers.get(int(class_id))
            if layer is None:
                continue
            if layer.shape[:2] != (h, w):
                arr = self._ensure_index_mask_shape(np.asarray(layer, dtype=np.uint8), (h, w))
                index[arr > 0] = np.uint8(max(0, min(255, int(class_id))))
                continue
            index[np.asarray(layer, dtype=np.uint8) > 0] = np.uint8(max(0, min(255, int(class_id))))
        return index

    def _history_apply_index_to_layers(
        self,
        layers: dict[int, np.ndarray],
        class_ids: list[int],
        shape_hw: tuple[int, int],
        state_index: np.ndarray,
    ) -> None:
        restored = self._ensure_index_mask_shape(np.asarray(state_index, dtype=np.uint8), shape_hw)
        for class_id in list(layers.keys()):
            layer = layers.get(class_id)
            if layer is None:
                continue
            if layer.shape[:2] != shape_hw:
                layers[class_id] = np.zeros(shape_hw, dtype=np.uint8)
                layer = layers[class_id]
            layer[:] = 0
        for class_id in class_ids:
            layer = layers.get(int(class_id))
            if layer is None:
                continue
            layer[:] = (restored == int(class_id)).astype(np.uint8)

    def _begin_stroke_history(self, context_key: str, target: str, uid: str, description: str) -> None:
        key = str(context_key)
        if key in self._pending_stroke_history:
            return
        _item, layers, class_ids, shape = self._history_target_layers(target, uid, create=True)
        if layers is None or not class_ids or shape[0] <= 0 or shape[1] <= 0:
            return
        before = self._history_index_from_layers(layers, class_ids, shape)
        self._pending_stroke_history[key] = {
            "target": str(target),
            "uid": str(uid),
            "class_ids": [int(cid) for cid in class_ids],
            "before": np.asarray(before, dtype=np.uint8),
            "description": str(description),
        }

    def _finalize_stroke_history(self, context_key: str) -> bool:
        key = str(context_key)
        pending = self._pending_stroke_history.pop(key, None)
        if not isinstance(pending, dict):
            return False
        target = str(pending.get("target", ""))
        uid = str(pending.get("uid", ""))
        before = np.asarray(pending.get("before"), dtype=np.uint8)
        class_ids = [int(v) for v in pending.get("class_ids", [])]
        if before.size <= 0 or not class_ids:
            return False
        _item, layers, resolved_ids, shape = self._history_target_layers(target, uid, create=True)
        if layers is None or shape[0] <= 0 or shape[1] <= 0:
            return False
        after = self._history_index_from_layers(layers, resolved_ids if resolved_ids else class_ids, shape)
        before_aligned = self._ensure_index_mask_shape(before, shape)
        if np.array_equal(before_aligned, after):
            return False
        self.undo_history.append(
            {
                "target": target,
                "uid": uid,
                "class_ids": [int(v) for v in (resolved_ids if resolved_ids else class_ids)],
                "state": before_aligned.copy(),
                "description": str(pending.get("description", "Stroke")),
            }
        )
        if len(self.undo_history) > int(self._history_limit):
            self.undo_history = self.undo_history[-int(self._history_limit) :]
        self.redo_history.clear()
        self._update_undo_redo_actions()
        return True

    def _cancel_live_stroke_refresh(self) -> None:
        if self._live_label_refresh_timer.isActive():
            self._live_label_refresh_timer.stop()
        if self._live_patch_refresh_timer.isActive():
            self._live_patch_refresh_timer.stop()
        if self._live_rf_refresh_timer.isActive():
            self._live_rf_refresh_timer.stop()
        if self._live_foundation_refresh_timer.isActive():
            self._live_foundation_refresh_timer.stop()
        if self._rf_info_refresh_timer.isActive():
            self._rf_info_refresh_timer.stop()
        if self._foundation_info_refresh_timer.isActive():
            self._foundation_info_refresh_timer.stop()
        self._live_label_dirty_bbox = None
        self._live_patch_dirty_bbox = None
        self._live_rf_dirty_bbox = None
        self._live_rf_refine_dirty_bbox = None
        self._live_foundation_dirty_bbox = None
        self._live_foundation_dirty = False
        self._pending_stroke_history.clear()

    def _apply_history_record(self, record: dict[str, object]) -> bool:
        if not isinstance(record, dict):
            return False
        target = str(record.get("target", ""))
        uid = str(record.get("uid", ""))
        class_ids = [int(v) for v in record.get("class_ids", [])] if isinstance(record.get("class_ids"), list) else []
        state = record.get("state")
        if not target or not uid or state is None:
            return False
        _item, layers, resolved_ids, shape = self._history_target_layers(target, uid, create=True)
        if layers is None or shape[0] <= 0 or shape[1] <= 0:
            return False
        apply_ids = resolved_ids if resolved_ids else class_ids
        if not apply_ids:
            return False
        self._history_apply_index_to_layers(layers, apply_ids, shape, np.asarray(state, dtype=np.uint8))
        if target == "annotations":
            self._mark_annotations_changed()
            self._set_dirty(True)
        elif target == "foundation_prompt":
            self._set_dirty(True)
        self._refresh_all_views()
        return True

    def _undo_stroke(self, _checked: bool = False) -> None:
        if not self.undo_history:
            self.statusBar().showMessage("Nothing to undo.", 2000)
            return
        self._cancel_live_stroke_refresh()
        record = self.undo_history.pop()
        target = str(record.get("target", ""))
        uid = str(record.get("uid", ""))
        class_ids = [int(v) for v in record.get("class_ids", [])] if isinstance(record.get("class_ids"), list) else []
        _item, layers, resolved_ids, shape = self._history_target_layers(target, uid, create=True)
        if layers is None or shape[0] <= 0 or shape[1] <= 0:
            self._update_undo_redo_actions()
            return
        current = self._history_index_from_layers(layers, resolved_ids if resolved_ids else class_ids, shape)
        self.redo_history.append(
            {
                "target": target,
                "uid": uid,
                "class_ids": [int(v) for v in (resolved_ids if resolved_ids else class_ids)],
                "state": current.copy(),
                "description": str(record.get("description", "Stroke")),
            }
        )
        if len(self.redo_history) > int(self._history_limit):
            self.redo_history = self.redo_history[-int(self._history_limit) :]
        self._history_applying = True
        try:
            self._apply_history_record(record)
        finally:
            self._history_applying = False
        self._update_undo_redo_actions()
        self.statusBar().showMessage("Undo stroke", 1500)

    def _redo_stroke(self, _checked: bool = False) -> None:
        if not self.redo_history:
            self.statusBar().showMessage("Nothing to redo.", 2000)
            return
        self._cancel_live_stroke_refresh()
        record = self.redo_history.pop()
        target = str(record.get("target", ""))
        uid = str(record.get("uid", ""))
        class_ids = [int(v) for v in record.get("class_ids", [])] if isinstance(record.get("class_ids"), list) else []
        _item, layers, resolved_ids, shape = self._history_target_layers(target, uid, create=True)
        if layers is None or shape[0] <= 0 or shape[1] <= 0:
            self._update_undo_redo_actions()
            return
        current = self._history_index_from_layers(layers, resolved_ids if resolved_ids else class_ids, shape)
        self.undo_history.append(
            {
                "target": target,
                "uid": uid,
                "class_ids": [int(v) for v in (resolved_ids if resolved_ids else class_ids)],
                "state": current.copy(),
                "description": str(record.get("description", "Stroke")),
            }
        )
        if len(self.undo_history) > int(self._history_limit):
            self.undo_history = self.undo_history[-int(self._history_limit) :]
        self._history_applying = True
        try:
            self._apply_history_record(record)
        finally:
            self._history_applying = False
        self._update_undo_redo_actions()
        self.statusBar().showMessage("Redo stroke", 1500)

