    def _toolbar_row_mode_for_width(self, width: int) -> int:
        width = max(0, int(width))
        if width < 1980:
            return 3
        if width < 2920:
            return 2
        return 1

    def _recommended_toolbar_row_mode(self, width: int) -> int:
        toolbars = getattr(self, "main_toolbars", None)
        if not toolbars:
            return self._toolbar_row_mode_for_width(width)

        available = max(520, int(width) - 36)
        rows = 1
        row_width = 0
        for toolbar in toolbars:
            hint = int(toolbar.sizeHint().width())
            if hint <= 0:
                hint = int(toolbar.minimumSizeHint().width())
            item_width = max(120, hint + 10)
            if row_width > 0 and (row_width + item_width) > available:
                rows += 1
                row_width = item_width
            else:
                row_width += item_width
        return max(1, min(len(toolbars), rows))

    def _set_toolbar_control_widths(self, compact: bool, row_mode: int, width: int, height: int) -> None:
        short_side = min(int(width), int(height))
        extra_tight = short_side < 800 or width < 1180
        if compact:
            brush_w = 84 if row_mode >= 3 else 92
            alpha_w = 84 if row_mode >= 3 else 92
            contrast_w = 92 if row_mode >= 3 else 100
            edge_w = 78 if row_mode >= 3 else 86
        else:
            brush_w = 116 if row_mode >= 2 else 130
            alpha_w = 116 if row_mode >= 2 else 130
            contrast_w = 108 if row_mode >= 2 else 120
            edge_w = 90 if row_mode >= 2 else 95

        if extra_tight:
            brush_w = max(72, brush_w - 8)
            alpha_w = max(72, alpha_w - 8)
            contrast_w = max(82, contrast_w - 8)
            edge_w = max(70, edge_w - 8)

        if hasattr(self, "brush_slider"):
            self.brush_slider.setFixedWidth(brush_w)
        if hasattr(self, "alpha_slider"):
            self.alpha_slider.setFixedWidth(alpha_w)
        if hasattr(self, "contrast_slider"):
            self.contrast_slider.setFixedWidth(contrast_w)
        if hasattr(self, "mask_edge_slider"):
            self.mask_edge_slider.setFixedWidth(edge_w)
        if hasattr(self, "mask_edge_alpha_slider"):
            self.mask_edge_alpha_slider.setFixedWidth(edge_w)

    def _set_toolbar_row_mode(self, mode: int) -> None:
        mode = max(1, min(3, int(mode)))
        if getattr(self, "_toolbar_row_mode", 0) == mode:
            return
        if not hasattr(self, "view_toolbar") or not hasattr(self, "mask_toolbar"):
            self._toolbar_row_mode = mode
            return

        for toolbar in (self.view_toolbar, self.mask_toolbar):
            try:
                self.removeToolBarBreak(toolbar)
            except Exception:
                pass

        if mode >= 2:
            self.insertToolBarBreak(self.view_toolbar)
        if mode >= 3:
            self.insertToolBarBreak(self.mask_toolbar)
        self._toolbar_row_mode = mode

    def _set_tab_titles_for_density(self, compact: bool, ultra_compact: bool) -> None:
        if not hasattr(self, "tabs"):
            return
        if ultra_compact:
            titles = TAB_TITLES_ULTRA
        elif compact:
            titles = TAB_TITLES_COMPACT
        else:
            titles = TAB_TITLES_FULL
        for idx, title in enumerate(titles):
            if idx < self.tabs.count():
                self.tabs.setTabText(idx, title)
                self.tabs.setTabToolTip(idx, TAB_TITLES_FULL[idx])
        if hasattr(self, "workflow_tabs"):
            workflow_labels = (
                ("Annotate", "Segment", "Train", "Measure")
                if ultra_compact
                else ("Annotate and Review", "Segmentation", "Training and HITL", "Measurements")
            )
            for idx, label in enumerate(workflow_labels):
                self.workflow_tabs.setTabText(idx, label)
                self.workflow_tabs.setTabToolTip(idx, TAB_SECTION_GROUPS[idx][1])
        self._refresh_tab_navigation_controls()

    def _tab_module_label(self, tab_index: int) -> str:
        idx = int(tab_index)
        if 0 <= idx < len(TAB_TITLES_FULL):
            raw = TAB_TITLES_FULL[idx]
        elif hasattr(self, "tabs"):
            raw = str(self.tabs.tabText(idx))
        else:
            raw = str(idx)
        return re.sub(r"^\d+\)\s*", "", raw).strip()

    def _tab_section_index_for_tab(self, tab_index: int) -> int:
        current = int(tab_index)
        for idx, (_key, _label, members) in enumerate(TAB_SECTION_GROUPS):
            if current in members:
                return idx
        return 0

    def _refresh_tab_navigation_controls(self) -> None:
        if not hasattr(self, "tabs") or not hasattr(self, "tab_section_combo") or not hasattr(self, "tab_module_combo"):
            return
        self._tab_nav_sync = True
        try:
            if self.tab_section_combo.count() != len(TAB_SECTION_GROUPS):
                self.tab_section_combo.clear()
                for key, label, _members in TAB_SECTION_GROUPS:
                    self.tab_section_combo.addItem(label, key)

            section_idx = self._tab_section_index_for_tab(self.tabs.currentIndex())
            self.tab_section_combo.setCurrentIndex(section_idx)
            if hasattr(self, "workflow_tabs"):
                self.workflow_tabs.setCurrentIndex(section_idx)

            _key, section_label, members = TAB_SECTION_GROUPS[section_idx]
            current_tab = int(self.tabs.currentIndex())
            self.tab_module_combo.clear()
            selected_idx = 0
            for idx, tab_idx in enumerate(members):
                self.tab_module_combo.addItem(self._tab_module_label(tab_idx), tab_idx)
                if int(tab_idx) == current_tab:
                    selected_idx = idx
            self.tab_module_combo.setCurrentIndex(selected_idx)

            if hasattr(self, "tab_nav_label"):
                self.tab_nav_label.setText(f"{section_label}  /  {self._tab_module_label(current_tab)}")
                if 0 <= current_tab < len(TAB_TITLES_FULL):
                    self.tab_nav_label.setToolTip(TAB_TITLES_FULL[current_tab])
        finally:
            self._tab_nav_sync = False

    def _on_tab_section_changed(self, section_index: int) -> None:
        if self._tab_nav_sync or not hasattr(self, "tabs"):
            return
        idx = max(0, min(len(TAB_SECTION_GROUPS) - 1, int(section_index)))
        _key, _label, members = TAB_SECTION_GROUPS[idx]
        current = int(self.tabs.currentIndex())
        target = current if current in members else int(members[0])
        self.tabs.setCurrentIndex(target)
        self._refresh_tab_navigation_controls()

    def _on_tab_module_changed(self, module_index: int) -> None:
        if self._tab_nav_sync or not hasattr(self, "tabs") or not hasattr(self, "tab_module_combo"):
            return
        target = self.tab_module_combo.itemData(int(module_index))
        if target is None:
            return
        self.tabs.setCurrentIndex(int(target))
        self._refresh_tab_navigation_controls()

