    def _reflow_dataset_controls(self, panel_width: int | None = None) -> None:
        if self._dataset_controls_grid is None:
            return
        if panel_width is None:
            panel_width = self._dataset_panel_widget.width() if self._dataset_panel_widget is not None else 260
        width = max(1, int(panel_width))

        while self._dataset_controls_grid.count():
            item = self._dataset_controls_grid.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.setParent(self._dataset_controls_widget)

        for col in range(3):
            self._dataset_controls_grid.setColumnStretch(col, 0)

        controls = (
            self.load_folder_btn,
            self.load_hades_data_btn,
            self.load_images_masks_btn,
            self.load_files_btn,
            self.rotate_left_btn,
            self.rotate_right_btn,
            self.remove_dataset_btn,
            self.clear_dataset_btn,
            self.save_project_btn,
            self.load_project_btn,
            self.load_template_btn,
            self.load_timeseries_btn,
        )
        if width < 276:
            for row, button in enumerate(controls):
                self._dataset_controls_grid.addWidget(button, row, 0)
            self._dataset_controls_grid.setColumnStretch(0, 1)
            return

        self._dataset_controls_grid.addWidget(self.load_folder_btn, 0, 0)
        self._dataset_controls_grid.addWidget(self.load_files_btn, 0, 1)
        self._dataset_controls_grid.addWidget(self.load_hades_data_btn, 1, 0, 1, 2)
        self._dataset_controls_grid.addWidget(self.load_images_masks_btn, 2, 0, 1, 2)
        self._dataset_controls_grid.addWidget(self.rotate_left_btn, 3, 0)
        self._dataset_controls_grid.addWidget(self.rotate_right_btn, 3, 1)
        self._dataset_controls_grid.addWidget(self.remove_dataset_btn, 4, 0)
        self._dataset_controls_grid.addWidget(self.clear_dataset_btn, 4, 1)
        self._dataset_controls_grid.addWidget(self.save_project_btn, 5, 0)
        self._dataset_controls_grid.addWidget(self.load_project_btn, 5, 1)
        self._dataset_controls_grid.addWidget(self.load_template_btn, 6, 0)
        self._dataset_controls_grid.addWidget(self.load_timeseries_btn, 6, 1)
        self._dataset_controls_grid.setColumnStretch(0, 1)
        self._dataset_controls_grid.setColumnStretch(1, 1)

    def _refresh_dataset_logo(self) -> None:
        if self._dataset_logo_label is None or self._dataset_logo_pixmap is None:
            return
        panel_width = self._dataset_panel_widget.width() if self._dataset_panel_widget is not None else 260
        target_width = max(80, min(260, panel_width - 28))
        scaled = self._dataset_logo_pixmap.scaled(target_width, target_width, Qt.KeepAspectRatio, Qt.SmoothTransformation)
        self._dataset_logo_label.setPixmap(scaled)
        self._dataset_logo_label.setFixedHeight(max(80, scaled.height() + 6))

    def _update_ui_density_style(self, compact: bool, ultra_compact: bool) -> None:
        compact = bool(compact)
        ultra_compact = bool(ultra_compact)
        compact_prop = bool(self.property("uiCompact"))
        ultra_prop = bool(self.property("uiUltraCompact"))
        if compact_prop == compact and ultra_prop == ultra_compact:
            return
        self.setProperty("uiCompact", compact)
        self.setProperty("uiUltraCompact", ultra_compact)
        style = self.style()
        if style is not None:
            style.unpolish(self)
            style.polish(self)
        self.update()

    def _apply_compact_ui_mode(self) -> None:
        width = max(1, int(self.width()))
        height = max(1, int(self.height()))
        compact = width < 1560 or height < 900
        ultra_compact = width < 1240 or height < 760
        compact_changed = compact != self._compact_ui_mode
        ultra_changed = ultra_compact != self._ultra_compact_ui_mode
        self._compact_ui_mode = compact
        self._ultra_compact_ui_mode = ultra_compact
        self._update_ui_density_style(compact=compact, ultra_compact=ultra_compact)
        self._set_dataset_labels_for_density(compact=compact, ultra_compact=ultra_compact)
        self._set_tab_titles_for_density(compact=compact, ultra_compact=ultra_compact)
        self._set_foundation_labels_for_density(compact=compact, ultra_compact=ultra_compact)
        self._set_random_forest_labels_for_density(compact=compact, ultra_compact=ultra_compact)
        self._set_toolbar_labels_for_density(compact=compact, ultra_compact=ultra_compact)
        self._set_tab_control_labels_for_density(compact=compact, ultra_compact=ultra_compact)
        if hasattr(self, "tabs_nav_widget"):
            self.tabs_nav_widget.setVisible(True)
        if hasattr(self, "tabs"):
            self.tabs.tabBar().setVisible(False)
        if hasattr(self, "tab_nav_label"):
            self.tab_nav_label.setVisible(not compact)
        self._refresh_tab_navigation_controls()

        row_mode = self._toolbar_row_mode_for_width(width)
        self._set_toolbar_control_widths(compact, row_mode, width, height)
        row_mode = self._recommended_toolbar_row_mode(width)
        self._set_toolbar_control_widths(compact, row_mode, width, height)
        row_mode = self._recommended_toolbar_row_mode(width)
        self._set_toolbar_row_mode(row_mode)

        if ultra_compact:
            icon_size = QSize(13, 13)
        else:
            icon_size = QSize(14, 14) if compact else QSize(16, 16)
        if hasattr(self, "main_toolbars"):
            for toolbar in self.main_toolbars:
                toolbar.setIconSize(icon_size)
        elif hasattr(self, "main_toolbar"):
            self.main_toolbar.setIconSize(icon_size)
        if hasattr(self, "label_stats"):
            self.label_stats.setMaximumHeight(82 if ultra_compact else (108 if compact else 130))

        if ultra_compact:
            timeline_icon_size = QSize(76, 48)
            dataset_min, dataset_max = 288, 360
            dock_min, dock_max = 196, 248
            min_center = 480
        elif width < 1460 or height < 860:
            timeline_icon_size = QSize(90, 58)
            dataset_min, dataset_max = 292, 380
            dock_min, dock_max = 204, 260
            min_center = 520
        elif width < 1760 or height < 980:
            timeline_icon_size = QSize(100, 66)
            dataset_min, dataset_max = 296, 400
            dock_min, dock_max = 210, 280
            min_center = 620
        else:
            timeline_icon_size = QSize(110, 72)
            dataset_min, dataset_max = 304, 420
            dock_min, dock_max = 220, 300
            min_center = 760

        if hasattr(self, "timeline_list"):
            if compact_changed or self.timeline_list.iconSize() != timeline_icon_size:
                self.timeline_list.setIconSize(timeline_icon_size)
                self._refresh_dataset_widgets()
        if self._dataset_panel_widget is not None:
            self._dataset_panel_widget.setMinimumWidth(dataset_min)
            self._dataset_panel_widget.setMaximumWidth(dataset_max)
            self._reflow_dataset_controls(self._dataset_panel_widget.width())

        if hasattr(self, "main_splitter"):
            sizes = self.main_splitter.sizes()
            if len(sizes) >= 2:
                total = max(1, int(sum(sizes)))
                current_left = max(0, int(sizes[0]))
                min_left_allowed = max(80, min(dataset_min, total - 120))
                min_center_effective = max(320, min(min_center, total - min_left_allowed))
                max_left_allowed = min(dataset_max, max(min_left_allowed, total - min_center_effective))
                if self._dataset_panel_user_width is not None and self._dataset_panel_user_width > 0:
                    preferred_left = int(self._dataset_panel_user_width)
                else:
                    preferred_left = 296 if ultra_compact else (304 if compact else 320)
                target_left = max(min_left_allowed, min(max_left_allowed, preferred_left))
                center = total - current_left
                needs_reflow = current_left < min_left_allowed or current_left > max_left_allowed or center < min_center_effective
                if compact_changed and self._dataset_panel_user_width is None:
                    needs_reflow = True
                if needs_reflow:
                    if center < min_center_effective:
                        new_left = min(current_left, max_left_allowed)
                    else:
                        new_left = current_left
                    if (compact_changed and self._dataset_panel_user_width is None) or new_left < min_left_allowed or new_left > max_left_allowed:
                        new_left = target_left
                    new_left = max(min_left_allowed, min(max_left_allowed, int(new_left)))
                    blocked = self.main_splitter.blockSignals(True)
                    self.main_splitter.setSizes([new_left, max(120, total - new_left)])
                    self.main_splitter.blockSignals(blocked)

        if hasattr(self, "layers_dock"):
            self.layers_dock.setMinimumWidth(dock_min)
            self.layers_dock.setMaximumWidth(dock_max)
            current_dock_width = max(0, int(self.layers_dock.width()))
            target_dock_width = max(dock_min, min(dock_max, 214 if ultra_compact else (224 if compact else 236)))
            if self.layers_dock.isFloating():
                if current_dock_width < dock_min or current_dock_width > dock_max:
                    self.layers_dock.resize(target_dock_width, self.layers_dock.height())
            else:
                dock_needs_reflow = (
                    not self._layers_dock_initialized
                    or compact_changed
                    or ultra_changed
                    or current_dock_width < dock_min
                    or current_dock_width > dock_max
                )
                if dock_needs_reflow:
                    try:
                        self.resizeDocks([self.layers_dock], [target_dock_width], Qt.Horizontal)
                        self._layers_dock_initialized = True
                    except Exception:
                        pass
        self._refresh_dataset_logo()
        self._refresh_right_sidebar_logo()

