    def _guided_root_rescue_current(self, _checked: bool = False) -> None:
        item = self._current_item()
        layers = self._current_layers()
        if item is None or layers is None:
            QMessageBox.information(self, "No image", "Load an image before using Guided Root Rescue.")
            return
        root_like_ids = {
            int(label_class.class_id)
            for label_class in self.classes
            if any(
                token in str(label_class.name or "").lower()
                for token in ("root", "lateral", "primary", "adventitious", "radicle")
            )
        }
        if not root_like_ids:
            QMessageBox.information(
                self,
                "Root classes unavailable",
                "Add or rename a root class before using Guided Root Rescue.",
            )
            return
        initial_class_id = int(self.active_class_id) if int(self.active_class_id) in root_like_ids else min(root_like_ids)
        dialog = GuidedRootRescueDialog(
            item.image,
            layers,
            self.classes,
            initial_class_id=initial_class_id,
            parent=self,
        )
        if dialog.exec() != QDialog.Accepted:
            return
        additions = dialog.addition_masks()
        if not additions:
            return

        self._begin_stroke_history("guided_root_rescue", "annotations", item.uid, "Guided root rescue")
        changed = 0
        class_order = dialog.route_class_order()
        ordered_ids: list[int] = []
        for class_id in class_order + list(additions):
            class_id = int(class_id)
            if class_id in additions and class_id not in ordered_ids:
                ordered_ids.append(class_id)
        for class_id in ordered_ids:
            layer = layers.get(class_id)
            if layer is None:
                continue
            selected = np.asarray(additions[class_id], dtype=np.uint8) > 0
            if not np.any(selected):
                continue
            for other_class_id, other_layer in layers.items():
                if int(other_class_id) != class_id:
                    other_layer[selected] = 0
            before = int(np.count_nonzero(layer[selected]))
            layer[selected] = 1
            changed += int(np.count_nonzero(selected)) - before
        if changed <= 0:
            self._pending_stroke_history.pop("guided_root_rescue", None)
            return

        metadata = self.prediction_metadata_by_uid.setdefault(item.uid, {})
        history = metadata.get("guided_root_rescue_history")
        history_rows = list(history) if isinstance(history, list) else []
        history_rows.append(dialog.rescue_metadata())
        metadata["guided_root_rescue_history"] = history_rows[-20:]
        self._finalize_stroke_history("guided_root_rescue")
        self._mark_annotations_changed()
        self._set_dirty(True)
        self._refresh_all_views()
        QMessageBox.information(self, "Guided rescue applied", f"Added {changed} root-label pixel(s).")

