        self.rf_apply_to_labels_btn.clicked.connect(self._apply_rf_result_to_labels)
        self.rf_apply_batch_to_labels_btn.clicked.connect(self._apply_rf_results_to_labels_batch)
        self.rf_export_refined_btn.clicked.connect(self._export_dataset_zip_dialog)
        self.rf_train_unet_btn.clicked.connect(self._rf_start_unet_training_from_refined)
        self.rf_export_omezarr_btn.clicked.connect(self._export_rf_tda_omezarr_dialog)
        self.rf_eval_heldout_btn.clicked.connect(self._evaluate_rf_tda_heldout_selected)
