    def _build_patching_tab(self) -> QWidget:
        tab = QWidget(self)
        layout = QVBoxLayout(tab)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(8)

        controls = QHBoxLayout()
        controls.addWidget(QLabel("Patch target class:"))
        self.patch_class_combo = QComboBox()
        controls.addWidget(self.patch_class_combo)
        self.patch_restrict_checkbox = QCheckBox("Restrict ground-truth edits to disagreement")
        self.patch_restrict_checkbox.setChecked(True)
        controls.addWidget(self.patch_restrict_checkbox)
        self.auto_adopt_btn = QPushButton("Copy Prediction -> GT (Disagreement)")
        self.clear_disagreement_btn = QPushButton("Clear GT in Disagreement")
        controls.addWidget(self.auto_adopt_btn)
        controls.addWidget(self.clear_disagreement_btn)
        controls.addStretch(1)
        layout.addLayout(controls)

        self.patch_canvas = SegmentationCanvas(editable=True)
        self.patch_canvas.set_tablet_pressure_enabled(True)
        self.patch_canvas.stroke_applied.connect(self._on_patch_stroke)
        self.patch_canvas.stroke_finished.connect(self._on_patch_stroke_finished)
        self.patch_canvas.mask_nudged.connect(self._on_patch_mask_nudged)
        self.patch_canvas.mask_nudge_finished.connect(self._on_patch_mask_nudge_finished)
        self.patch_canvas.brush_size_adjust.connect(self._on_canvas_brush_adjust)
        self.patch_canvas.zoom_changed.connect(self._on_canvas_zoom_changed)
        layout.addWidget(self.patch_canvas, 1)

        self.patch_info = QLabel("Run inference first to patch disagreement regions.")
        self.patch_info.setStyleSheet("color: #9eb2d8;")
        layout.addWidget(self.patch_info)

        self.patch_class_combo.currentIndexChanged.connect(self._on_patch_class_changed)
        self.patch_restrict_checkbox.stateChanged.connect(self._on_patch_restrict_changed)
        self.auto_adopt_btn.clicked.connect(self._auto_adopt_prediction)
        self.clear_disagreement_btn.clicked.connect(self._clear_disagreement_labels)

        return tab

