    def _build_timelapse_tab(self) -> QWidget:
        tab = QWidget(self)
        layout = QVBoxLayout(tab)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(8)

        controls = QHBoxLayout()
        self.timelapse_play_btn = QPushButton("Play")
        controls.addWidget(self.timelapse_play_btn)
        controls.addWidget(QLabel("FPS:"))
        self.timelapse_fps_slider = QSlider(Qt.Horizontal)
        self.timelapse_fps_slider.setRange(1, 24)
        self.timelapse_fps_slider.setValue(self.timelapse_fps)
        self.timelapse_fps_slider.setFixedWidth(120)
        controls.addWidget(self.timelapse_fps_slider)
        self.timelapse_fps_label = QLabel(f"{self.timelapse_fps}")
        controls.addWidget(self.timelapse_fps_label)

        controls.addSpacing(16)
        self.timelapse_original_cb = QCheckBox("Show Original")
        self.timelapse_original_cb.setChecked(True)
        self.timelapse_labels_cb = QCheckBox("Show Labels")
        self.timelapse_labels_cb.setChecked(True)
        self.timelapse_pred_cb = QCheckBox("Show Prediction")
        self.timelapse_pred_cb.setChecked(False)
        controls.addWidget(self.timelapse_original_cb)
        controls.addWidget(self.timelapse_labels_cb)
        controls.addWidget(self.timelapse_pred_cb)
        controls.addSpacing(10)
        self.timelapse_interp_cb = QCheckBox("Smooth")
        self.timelapse_interp_cb.setChecked(bool(self.timelapse_interp_enabled))
        controls.addWidget(self.timelapse_interp_cb)
        controls.addWidget(QLabel("Subframes:"))
        self.timelapse_interp_spin = QSpinBox()
        self.timelapse_interp_spin.setRange(1, 8)
        self.timelapse_interp_spin.setValue(int(self.timelapse_interp_steps))
        self.timelapse_interp_spin.setFixedWidth(64)
        controls.addWidget(self.timelapse_interp_spin)
        self.timelapse_tip_overlay_cb = QCheckBox("Tip Tracker")
        self.timelapse_tip_overlay_cb.setChecked(bool(self.timelapse_tip_overlay_enabled))
        self.timelapse_tip_overlay_cb.setToolTip(
            "Use Analytics tip tracks to render interpolated tip motion and direction between frames."
        )
        controls.addWidget(self.timelapse_tip_overlay_cb)
        controls.addSpacing(16)
        self.export_timelapse_btn = QPushButton("Export 1080p MP4")
        controls.addWidget(self.export_timelapse_btn)
        controls.addStretch(1)
        layout.addLayout(controls)

        frame_row = QHBoxLayout()
        frame_row.addWidget(QLabel("Frame"))
        self.timelapse_slider = QSlider(Qt.Horizontal)
        self.timelapse_slider.setRange(0, 0)
        frame_row.addWidget(self.timelapse_slider, 1)
        self.timelapse_frame_label = QLabel("0/0")
        frame_row.addWidget(self.timelapse_frame_label)
        layout.addLayout(frame_row)

        self.timelapse_canvas = SegmentationCanvas(editable=False)
        self.timelapse_canvas.zoom_changed.connect(self._on_canvas_zoom_changed)
        layout.addWidget(self.timelapse_canvas, 1)

        self.timelapse_info = QLabel("Use this tab to inspect image and label evolution across the timeline.")
        self.timelapse_info.setStyleSheet("color: #9eb2d8;")
        layout.addWidget(self.timelapse_info)

        self.timelapse_play_btn.clicked.connect(self._toggle_timelapse_playback)
        self.timelapse_fps_slider.valueChanged.connect(self._on_timelapse_fps_changed)
        self.timelapse_slider.valueChanged.connect(self._on_timelapse_slider_changed)
        self.timelapse_original_cb.stateChanged.connect(lambda _: self._refresh_timelapse_view())
        self.timelapse_labels_cb.stateChanged.connect(lambda _: self._refresh_timelapse_view())
        self.timelapse_pred_cb.stateChanged.connect(lambda _: self._refresh_timelapse_view())
        self.timelapse_interp_cb.stateChanged.connect(self._on_timelapse_interp_changed)
        self.timelapse_interp_spin.valueChanged.connect(self._on_timelapse_interp_steps_changed)
        self.timelapse_tip_overlay_cb.stateChanged.connect(self._on_timelapse_tip_overlay_changed)
        self.export_timelapse_btn.clicked.connect(self._export_timelapse_mp4_dialog)

        return tab

