    def _build_architecture_tab(self) -> QWidget:
        tab = QWidget(self)
        outer_layout = QVBoxLayout(tab)
        outer_layout.setContentsMargins(10, 10, 10, 10)
        outer_layout.setSpacing(0)

        self.architecture_scroll = QScrollArea()
        self.architecture_scroll.setWidgetResizable(True)
        self.architecture_scroll.setFrameShape(QFrame.NoFrame)
        self.architecture_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        content = QWidget()
        content.setMinimumWidth(1160)
        layout = QVBoxLayout(content)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(8)

        hint = QLabel(
            "Branch-level architecture tracking for persistent lateral-root IDs and color-graded vector growth. "
            "This tab reuses the class/tracking settings from 7) Analytics."
        )
        hint.setWordWrap(True)
        hint.setStyleSheet("color: #9eb2d8;")
        layout.addWidget(hint)

        run_row = QHBoxLayout()
        self.architecture_run_current_btn = QPushButton("Run Tracker (Current)")
        self.architecture_run_dataset_btn = QPushButton("Run Tracker (Dataset)")
        self.architecture_export_csv_btn = QPushButton("Export Branch CSV")
        self.architecture_export_json_btn = QPushButton("Export Summary JSON")
        self.architecture_export_csv_btn.setEnabled(False)
        self.architecture_export_json_btn.setEnabled(False)
        run_row.addWidget(self.architecture_run_current_btn)
        run_row.addWidget(self.architecture_run_dataset_btn)
        run_row.addWidget(self.architecture_export_csv_btn)
        run_row.addWidget(self.architecture_export_json_btn)
        run_row.addStretch(1)
        layout.addLayout(run_row)

        grid = QGridLayout()
        grid.setHorizontalSpacing(10)
        grid.setVerticalSpacing(6)

        grid.addWidget(QLabel("Branch link distance (px)"), 0, 0)
        self.architecture_link_distance_spin = QDoubleSpinBox()
        self.architecture_link_distance_spin.setDecimals(1)
        self.architecture_link_distance_spin.setRange(4.0, 512.0)
        self.architecture_link_distance_spin.setSingleStep(2.0)
        self.architecture_link_distance_spin.setValue(42.0)
        grid.addWidget(self.architecture_link_distance_spin, 0, 1)

        grid.addWidget(QLabel("Max gap (frames)"), 0, 2)
        self.architecture_gap_frames_spin = QSpinBox()
        self.architecture_gap_frames_spin.setRange(1, 16)
        self.architecture_gap_frames_spin.setValue(2)
        grid.addWidget(self.architecture_gap_frames_spin, 0, 3)

        grid.addWidget(QLabel("Min branch length (px)"), 1, 0)
        self.architecture_min_length_spin = QDoubleSpinBox()
        self.architecture_min_length_spin.setDecimals(1)
        self.architecture_min_length_spin.setRange(1.0, 256.0)
        self.architecture_min_length_spin.setSingleStep(1.0)
        self.architecture_min_length_spin.setValue(6.0)
        grid.addWidget(self.architecture_min_length_spin, 1, 1)

        grid.addWidget(QLabel("Min branch frames"), 1, 2)
        self.architecture_min_frames_spin = QSpinBox()
        self.architecture_min_frames_spin.setRange(1, 64)
        self.architecture_min_frames_spin.setValue(2)
        grid.addWidget(self.architecture_min_frames_spin, 1, 3)

        self.architecture_show_history_cb = QCheckBox("Show history")
        self.architecture_show_history_cb.setChecked(True)
        grid.addWidget(self.architecture_show_history_cb, 2, 0)

        grid.addWidget(QLabel("History depth"), 2, 2)
        self.architecture_history_depth_spin = QSpinBox()
        self.architecture_history_depth_spin.setRange(1, 64)
        self.architecture_history_depth_spin.setValue(8)
        grid.addWidget(self.architecture_history_depth_spin, 2, 3)

        self.architecture_show_primary_cb = QCheckBox("Show primary path")
        self.architecture_show_primary_cb.setChecked(True)
        grid.addWidget(self.architecture_show_primary_cb, 3, 0)

        self.architecture_show_branch_ids_cb = QCheckBox("Show branch IDs")
        self.architecture_show_branch_ids_cb.setChecked(True)
        grid.addWidget(self.architecture_show_branch_ids_cb, 3, 1)

        self.architecture_show_bbox_cb = QCheckBox("Show plant boxes")
        self.architecture_show_bbox_cb.setChecked(False)
        grid.addWidget(self.architecture_show_bbox_cb, 3, 2)

        self.architecture_show_predictions_cb = QCheckBox("Blend predictions")
        self.architecture_show_predictions_cb.setChecked(True)
        grid.addWidget(self.architecture_show_predictions_cb, 3, 3)

