    def _hitl_scope_items(self) -> tuple[list[DatasetImageItem], str]:
        selected = self._selected_dataset_items()
        if selected:
            return list(selected), "selected timeline images"
        return list(self.dataset_items), "all loaded images"

    def _hitl_selected_uids(self) -> list[str]:
        if not hasattr(self, "hitl_table"):
            return []
        rows = sorted({index.row() for index in self.hitl_table.selectionModel().selectedRows()})
        selected: list[str] = []
        for row in rows:
            item = self.hitl_table.item(row, 0)
            uid = item.data(Qt.UserRole) if item is not None else None
            if isinstance(uid, str) and uid:
                selected.append(uid)
        return selected

    def _on_hitl_template_preset_changed(self, _index: int = 0) -> None:
        if hasattr(self, "hitl_template_preset_combo"):
            self.hitl_session_template_preset_key = str(self.hitl_template_preset_combo.currentData() or "current")

    def _browse_hitl_input_folder(self, _checked: bool = False) -> None:
        directory = QFileDialog.getExistingDirectory(
            self,
            "Select HITL session image folder",
            self.hitl_input_folder_edit.text().strip() if hasattr(self, "hitl_input_folder_edit") else "",
        )
        if not directory:
            return
        self.hitl_session_input_folder = Path(directory).expanduser()
        if hasattr(self, "hitl_input_folder_edit"):
            self.hitl_input_folder_edit.setText(str(self.hitl_session_input_folder))

    def _hitl_selected_template_preset_key(self) -> str:
        if hasattr(self, "hitl_template_preset_combo"):
            return str(self.hitl_template_preset_combo.currentData() or "current")
        return str(self.hitl_session_template_preset_key or "current")

    def _apply_hitl_session_template(self, preset_key: str) -> str:
        normalized = str(preset_key or "current").strip() or "current"
        self.hitl_session_template_preset_key = normalized
        if normalized == "current":
            return "current segmentation setup"

        py_idx = self.inference_backend_combo.findData("pyphenotyper") if hasattr(self, "inference_backend_combo") else -1
        if py_idx >= 0 and str(self.inference_backend_combo.currentData() or "") != "pyphenotyper":
            self.inference_backend_combo.setCurrentIndex(py_idx)
        if hasattr(self, "pyphenotyper_preset_combo"):
            preset_idx = self.pyphenotyper_preset_combo.findData(normalized)
            if preset_idx >= 0:
                self.pyphenotyper_preset_combo.blockSignals(True)
                self.pyphenotyper_preset_combo.setCurrentIndex(preset_idx)
                self.pyphenotyper_preset_combo.blockSignals(False)
        if not self._apply_pyphenotyper_preset(normalized, mark_dirty=False):
            raise ValueError(f"The selected HITL template preset '{normalized}' is not available in this build.")
        label = normalized
        if hasattr(self, "hitl_template_preset_combo"):
            label = self.hitl_template_preset_combo.currentText().strip() or normalized
        return label

    def _hitl_folder_matches_loaded_dataset(self, folder: Path, paths: list[Path]) -> bool:
        if not self.dataset_items:
            return False
        try:
            current_paths = {str(Path(item.path).resolve()) for item in self.dataset_items}
            target_paths = {str(path.resolve()) for path in paths}
        except Exception:
            return False
        if not current_paths or current_paths != target_paths:
            return False
        try:
            folder_resolved = folder.resolve()
            return all(folder_resolved == Path(item.path).resolve() or folder_resolved in Path(item.path).resolve().parents for item in self.dataset_items)
        except Exception:
            return False

    def _ensure_hitl_session_dataset_loaded(self) -> tuple[str, bool]:
        folder_txt = self.hitl_input_folder_edit.text().strip() if hasattr(self, "hitl_input_folder_edit") else ""
        if not folder_txt:
            if not self.dataset_items:
                raise ValueError("Select a HITL session folder or load images first.")
            return ("current loaded images", False)

        folder = Path(folder_txt).expanduser()
        if not folder.exists() or not folder.is_dir():
            raise ValueError(f"HITL session folder does not exist:\n{folder}")
        self.hitl_session_input_folder = folder
        paths, walk_errors = self._collect_image_paths_recursive(folder)
        if not paths:
            raise ValueError(
                "No supported images were found in the selected HITL session folder.\n"
                "Supported: .png .jpg .jpeg .tif .tiff .bmp .jxl .hdr/.bil .tar"
            )
        if self._hitl_folder_matches_loaded_dataset(folder, paths):
            return (f"folder: {folder.name}", False)

        self._clear_dataset()
        added, skipped, _canceled = self._load_image_paths(paths, series_name=TIME_SERIES_DEFAULT, show_result_dialog=False)
        if added <= 0:
            raise ValueError(f"Failed to load images from the selected HITL session folder.\nSkipped: {skipped}")
        if walk_errors > 0:
            self.statusBar().showMessage(
                f"HITL session folder loaded with {walk_errors} unreadable subdirectory error(s).",
                6000,
            )
        return (f"folder: {folder.name}", True)

    def _load_hitl_session_folder_into_dataset(self, _checked: bool = False) -> None:
        try:
            scope_label, loaded = self._ensure_hitl_session_dataset_loaded()
        except Exception as exc:
            QMessageBox.warning(self, "HITL session folder", str(exc))
            return
        self._refresh_hitl_view()
        msg = f"Ready for HITL session from {scope_label}."
        if loaded:
            msg += f"\nImages loaded: {len(self.dataset_items)}"
        QMessageBox.information(self, "HITL session folder", msg)

    def _hitl_row_by_uid(self, uid: str) -> dict[str, object] | None:
        lookup = str(uid or "").strip()
        if not lookup:
            return None
        return next((row for row in self.hitl_candidate_rows if str(row.get("uid", "")) == lookup), None)

    def _hitl_index_mask_for_uid(self, uid: str) -> np.ndarray | None:
        pseudo = self.hitl_pseudo_labels.get(uid)
        if isinstance(pseudo, np.ndarray):
            return np.asarray(pseudo, dtype=np.uint8)
        pred = self.predictions.get(uid)
        if isinstance(pred, np.ndarray):
            return np.asarray(pred, dtype=np.uint8)
        item = self._dataset_item_by_uid(uid)
        if item is None:
            return None
        layers = self.annotations.get(uid, {})
        if not layers:
            return None
        return index_mask_from_layers(layers, self.classes, item.image.shape[:2])

    def _apply_index_mask_to_item_annotations(self, item: DatasetImageItem, index_mask: np.ndarray) -> None:
        pred_index = self._ensure_index_mask_shape(np.asarray(index_mask, dtype=np.uint8), item.image.shape[:2])
        layers = ensure_layer_map(self.annotations, item.uid, self.classes, item.image.shape[:2])
        for class_id in self._class_ids():
            layers[class_id][:] = (pred_index == class_id).astype(np.uint8)

    def _hitl_session_output_root(self) -> Path:
        output_dir = Path(self.hitl_synthetic_output_edit.text().strip() or str(self.hitl_synthetic_output_dir)).expanduser()
        output_dir.mkdir(parents=True, exist_ok=True)
        self.hitl_synthetic_output_dir = output_dir
        if hasattr(self, "hitl_synthetic_output_edit"):
            self.hitl_synthetic_output_edit.setText(str(output_dir))
        return output_dir

    def _augment_hitl_snapshot_with_synthetic(
        self,
        snapshot_items: list[DatasetImageItem],
        snapshot_annotations: dict[str, dict[int, np.ndarray]],
        *,
        additions_needed: int,
    ) -> dict[str, object]:
        needed = max(0, int(additions_needed))
        if needed <= 0:
            return {"added": 0, "items": [], "annotations": {}}

        labeled_sources = [
            item
            for item in snapshot_items
            if annotation_coverage_fraction(snapshot_annotations.get(item.uid, {}), item.image.shape[:2]) > 0.0
        ]
        if not labeled_sources:
            return {"added": 0, "items": [], "annotations": {}}

        added_items: list[DatasetImageItem] = []
        added_annotations: dict[str, dict[int, np.ndarray]] = {}
        added = 0
        variants_per_image = max(1, int(self.hitl_synthetic_variants_spin.value()))

        for item in labeled_sources:
            if added >= needed:
                break
            layers = snapshot_annotations.get(item.uid, {})
            if not layers:
                continue
            variants = generate_synthetic_variants(
                np.asarray(item.image, dtype=np.uint8),
                {int(class_id): np.asarray(mask, dtype=np.uint8) for class_id, mask in layers.items()},
                count=min(variants_per_image, needed - added),
                rng_seed=abs(hash((item.uid, needed, variants_per_image))) % (2**32),
            )
            for variant_image, variant_layers, _variant_meta in variants:
                if added >= needed:
                    break
                uid = f"hitl_session_synth_{item.uid}_{added:04d}"
                name = f"{Path(item.name).stem}__hitl_synth_{added:04d}.png"
                added_items.append(
                    DatasetImageItem(
                        uid=uid,
                        name=name,
                        path=Path(name),
                        image=np.asarray(variant_image, dtype=np.uint8).copy(),
                    )
                )
                added_annotations[uid] = {
                    int(class_id): np.asarray(mask, dtype=np.uint8).copy()
                    for class_id, mask in variant_layers.items()
                }
                added += 1

        return {
            "added": int(added),
            "items": added_items,
            "annotations": added_annotations,
        }

    def _write_hitl_session_bundle(
        self,
        snapshot_items: list[DatasetImageItem],
        snapshot_annotations: dict[str, dict[int, np.ndarray]],
        session_summary: dict[str, object],
    ) -> dict[str, object]:
        output_root = self._hitl_session_output_root()
        session_dir = output_root / f"hitl_session_{time.strftime('%Y%m%d_%H%M%S')}"
        images_dir = session_dir / "images"
        images_dir.mkdir(parents=True, exist_ok=True)

        written_items: list[DatasetImageItem] = []
        name_counts: dict[str, int] = {}
        for index, item in enumerate(snapshot_items):
            stem = re.sub(r"[^A-Za-z0-9._-]+", "_", Path(item.name).stem).strip("_") or f"image_{index:04d}"
            stem = stem[:80]
            count = name_counts.get(stem, 0)
            name_counts[stem] = count + 1
            suffix = f"_{count}" if count > 0 else ""
            filename = f"{index:04d}_{stem}{suffix}.png"
            image_path = images_dir / filename
            Image.fromarray(np.asarray(item.image, dtype=np.uint8), mode="RGB").save(image_path)
            written_items.append(
                DatasetImageItem(
                    uid=item.uid,
                    name=filename,
                    path=image_path,
                    image=np.asarray(item.image, dtype=np.uint8).copy(),
                )
            )

        subset_series_by_uid = {
            str(item.uid): str(self.series_by_uid.get(item.uid, "Ungrouped"))
            for item in written_items
        }
        subset_review_state = {
            str(item.uid): dict(self.hitl_review_state.get(item.uid, {}))
            for item in written_items
            if isinstance(self.hitl_review_state.get(item.uid), dict)
        }
        subset_predictions = {
            str(item.uid): np.asarray(self.predictions[item.uid], dtype=np.uint8).copy()
            for item in written_items
            if item.uid in self.predictions and isinstance(self.predictions.get(item.uid), np.ndarray)
        }
        subset_pseudo = {
            str(item.uid): np.asarray(self.hitl_pseudo_labels[item.uid], dtype=np.uint8).copy()
            for item in written_items
            if item.uid in self.hitl_pseudo_labels and isinstance(self.hitl_pseudo_labels.get(item.uid), np.ndarray)
        }
        subset_prediction_meta = {
            str(item.uid): dict(self.prediction_metadata_by_uid.get(item.uid, {}))
            for item in written_items
            if isinstance(self.prediction_metadata_by_uid.get(item.uid), dict)
        }

        project_path = session_dir / "hitl_retrain_bundle.oclp"
        save_project(
            project_path=project_path,
            dataset_items=written_items,
            classes=self.classes,
            annotations=snapshot_annotations,
            predictions=subset_predictions,
            current_index=0,
            active_class_id=self.active_class_id,
            patch_target_class_id=self.patch_target_class_id,
            next_class_id=self.next_class_id,
            model_path=self.model_path,
            inference_backend=self._current_inference_backend(),
            class_visibility=self.class_visibility,
            external_tf_python_path=self.external_tf_python_path,
            series_by_uid=subset_series_by_uid,
            series_order=[name for name in self.series_order if name in set(subset_series_by_uid.values())],
            series_filter_key=self.series_filter_key,
            prediction_metadata_by_uid=subset_prediction_meta,
            hitl_pseudo_labels=subset_pseudo,
            hitl_review_state=subset_review_state,
            pyphenotyper_preset_key=self.pyphenotyper_preset_key,
            pyphenotyper_pipeline_dir=self.pyphenotyper_pipeline_dir,
            pyphenotyper_root_model_path=self.pyphenotyper_root_model_path,
            pyphenotyper_shoot_model_path=self.pyphenotyper_shoot_model_path,
            pyphenotyper_lucifer_gan_gap_repair_enabled=(
                bool(self.pyphenotyper_lucifer_gan_gap_repair_cb.isChecked())
                if hasattr(self, "pyphenotyper_lucifer_gan_gap_repair_cb")
                else False
            ),
            pyphenotyper_lucifer_gan_gap_repair_dir=self._current_pyphenotyper_lucifer_gan_gap_repair_dir(),
            pyphenotyper_preserve_root_on_shoot_overlap=(
                bool(self.pyphenotyper_preserve_root_overlap_cb.isChecked())
                if hasattr(self, "pyphenotyper_preserve_root_overlap_cb")
                else bool(self.pyphenotyper_preserve_root_on_shoot_overlap)
            ),
            pyphenotyper_shoot_color_rescue_mode=self._current_pyphenotyper_shoot_color_rescue_mode(),
            pyphenotyper_pixel_size_mm=(
                float(self.pyphenotyper_pixel_size_mm_spin.value())
                if hasattr(self, "pyphenotyper_pixel_size_mm_spin")
                else None
            ),
            analytics_pixel_size_mm=(
                float(self.analytics_pixel_size_spin.value())
                if hasattr(self, "analytics_pixel_size_spin")
                else None
            ),
            analytics_root_ownership_mode=(
                str(self.analytics_root_ownership_mode_combo.currentData())
                if hasattr(self, "analytics_root_ownership_mode_combo")
                else "temporal_graph"
            ),
            analytics_freeze_ambiguous_ownership=(
                bool(self.analytics_freeze_ambiguous_ownership_cb.isChecked())
                if hasattr(self, "analytics_freeze_ambiguous_ownership_cb")
                else True
            ),
            pipeline_temporal_primary_lock_enabled=self._pipeline_temporal_primary_lock_active(),
            pipeline_lazy_analysis_mode=self._current_pipeline_lazy_analysis_mode(),
            pipeline_lazy_standard_expected_plants=int(
                max(1, getattr(self, "pipeline_lazy_standard_expected_plants", 5))
            ),
            pipeline_lazy_measure_class_ids=(
                self.pipeline_lazy_measure_class_ids_edit.text().strip()
                if hasattr(self, "pipeline_lazy_measure_class_ids_edit")
                else self.pipeline_lazy_measure_class_ids_text
            ),
            pipeline_lazy_shoot_class_ids=(
                self.pipeline_lazy_shoot_class_ids_edit.text().strip()
                if hasattr(self, "pipeline_lazy_shoot_class_ids_edit")
                else self.pipeline_lazy_shoot_class_ids_text
            ),
            pipeline_lazy_video_mask_only=(
                bool(self.pipeline_lazy_mask_only_video_cb.isChecked())
                if hasattr(self, "pipeline_lazy_mask_only_video_cb")
                else bool(self.pipeline_lazy_video_mask_only)
            ),
            pipeline_lazy_root_metric_mode=self._current_pipeline_lazy_root_metric_mode(),
            pipeline_lazy_shoot_rgb_rescue_enabled=self._current_pipeline_lazy_shoot_rgb_rescue_enabled(),
            pipeline_stabilization_target_mode=str(
                getattr(self, "pipeline_stabilization_target_mode", "plant_top") or "plant_top"
            ),
            pyphenotyper_general_starter_calibration=self.general_root_starter_calibration,
            hitl_session_input_folder=self.hitl_session_input_folder,
            hitl_session_template_preset_key=self._hitl_selected_template_preset_key(),
            hitl_synthetic_output_dir=self.hitl_synthetic_output_dir,
            hitl_long_session_cycle_count=(
                int(self.hitl_cycle_count_spin.value()) if hasattr(self, "hitl_cycle_count_spin") else int(self.hitl_long_session_cycle_count)
            ),
            store_relative_paths=True,
        )

        dataset_zip_path = session_dir / "hitl_retrain_masks.zip"
        export_dataset_zip(
            dataset_items=written_items,
            classes=self.classes,
            annotations=snapshot_annotations,
            output_path=dataset_zip_path,
        )

        summary_path = session_dir / "hitl_session_summary.json"
        summary_payload = dict(session_summary)
        summary_payload["project_path"] = str(project_path)
        summary_payload["dataset_zip_path"] = str(dataset_zip_path)
        summary_payload["session_dir"] = str(session_dir)
        summary_path.write_text(json.dumps(summary_payload, indent=2), encoding="utf-8")

        return {
            "session_dir": session_dir,
            "project_path": project_path,
            "dataset_zip_path": dataset_zip_path,
            "summary_path": summary_path,
            "written_items": written_items,
        }

    def _refresh_hitl_view(self) -> None:
        if not hasattr(self, "hitl_table"):
            return
        rows = build_hitl_candidate_rows(
            self.dataset_items,
            self.annotations,
            self.predictions,
            self.prediction_metadata_by_uid,
            self.hitl_pseudo_labels,
            self.hitl_review_state,
        )
        self.hitl_candidate_rows = rows
        filter_key = str(self.hitl_filter_combo.currentData()) if hasattr(self, "hitl_filter_combo") else "all"
        filtered: list[dict[str, object]] = []
        for row in rows:
            labeled = bool(row.get("labeled"))
            status = str(row.get("pseudo_status", "none"))
            if filter_key == "unlabeled" and labeled:
                continue
            if filter_key == "pending" and status not in {"pending", "opened"}:
                continue
            if filter_key == "reviewed" and status not in {"accepted", "refined", "auto-accepted"}:
                continue
            if filter_key == "labeled" and not labeled:
                continue
            filtered.append(row)

        top_n = int(self.hitl_top_n_spin.value()) if hasattr(self, "hitl_top_n_spin") else len(filtered)
        filtered = filtered[: max(1, top_n)]

        self.hitl_table.blockSignals(True)
        self.hitl_table.setRowCount(0)
        for row_idx, row in enumerate(filtered):
            self.hitl_table.insertRow(row_idx)
            values = [
                str(row.get("image_name", "")),
                str(row.get("pseudo_status", "none")),
                f"{float(row.get('uncertainty_score', 0.0)):.3f}",
                f"{float(row.get('confidence_score', 0.0)):.3f}",
                f"{float(row.get('prediction_coverage_fraction', 0.0)):.3f}",
                "yes" if bool(row.get("has_pseudo_label")) else "no",
                "yes" if bool(row.get("labeled")) else "no",
                str(row.get("recommendation", "")),
            ]
            for col, value in enumerate(values):
                cell = QTableWidgetItem(value)
                if col == 0:
                    cell.setData(Qt.UserRole, str(row.get("uid", "")))
                self.hitl_table.setItem(row_idx, col, cell)
        self.hitl_table.blockSignals(False)

        total = len(self.dataset_items)
        unlabeled = sum(1 for row in rows if not bool(row.get("labeled")))
        pending = sum(1 for row in rows if str(row.get("pseudo_status", "")) in {"pending", "opened"})
        retraining_pool = sum(1 for row in rows if str(row.get("pseudo_status", "")) in {"accepted", "refined", "auto-accepted"})
        session_bits: list[str] = []
        folder_txt = self.hitl_input_folder_edit.text().strip() if hasattr(self, "hitl_input_folder_edit") else ""
        if folder_txt:
            session_bits.append(f"Session folder: {Path(folder_txt).name}")
        template_label = self.hitl_template_preset_combo.currentText().strip() if hasattr(self, "hitl_template_preset_combo") else ""
        if template_label:
            session_bits.append(f"Template: {template_label}")
        cycles = int(self.hitl_cycle_count_spin.value()) if hasattr(self, "hitl_cycle_count_spin") else int(self.hitl_long_session_cycle_count)
        session_bits.append(f"Cycles: {max(1, cycles)}")
        session_prefix = " | ".join(session_bits)
        self.hitl_summary_label.setText(
            f"{session_prefix}\n"
            f"Dataset: {total} image(s). Unlabeled: {unlabeled}. Pending pseudo-label review: {pending}. "
            f"Retraining-pool pseudo-labels: {retraining_pool}. The self-training loop saves a retrain-ready bundle from manual labels + strong pseudo-labels."
        )
        if self.hitl_table.rowCount() > 0 and not self._hitl_selected_uids():
            self.hitl_table.selectRow(0)
        else:
            self._on_hitl_table_selection_changed()

    def _on_hitl_table_selection_changed(self) -> None:
        if not hasattr(self, "hitl_preview_canvas"):
            return
        uids = self._hitl_selected_uids()
        has_selection = bool(uids)
        for button_name in ("hitl_accept_btn", "hitl_open_btn", "hitl_clear_btn"):
            button = getattr(self, button_name, None)
            if button is not None:
                button.setEnabled(has_selection)
        if not uids:
            self.hitl_preview_label.setText("Preview")
            self.hitl_preview_canvas.set_image(None)
            self.hitl_details_text.setPlainText("Select one or more rows from the queue to inspect the pseudo-label or prediction.")
            return
        uid = uids[0]
        item = self._dataset_item_by_uid(uid)
        row = self._hitl_row_by_uid(uid)
        if item is None or row is None:
            self.hitl_preview_canvas.set_image(None)
            self.hitl_details_text.setPlainText("Selected row is no longer available.")
            return
        index_mask = self._hitl_index_mask_for_uid(uid)
        preview = np.asarray(item.image, dtype=np.uint8)
        if isinstance(index_mask, np.ndarray):
            preview = blend_index_mask(
                preview,
                self._ensure_index_mask_shape(index_mask, item.image.shape[:2]),
                self.classes,
                alpha=float(self.overlay_alpha),
                edge_thickness=int(self.mask_edge_thickness),
                edge_alpha=float(self.mask_edge_alpha),
            )
        self.hitl_preview_label.setText(f"{item.name} · {item.image.shape[1]}x{item.image.shape[0]}")
        self.hitl_preview_canvas.set_image(preview)
        details = {
            "uid": uid,
            "recommendation": row.get("recommendation"),
            "pseudo_status": row.get("pseudo_status"),
            "labeled": bool(row.get("labeled")),
            "confidence_score": float(row.get("confidence_score", 0.0)),
            "uncertainty_score": float(row.get("uncertainty_score", 0.0)),
            "prediction_coverage_fraction": float(row.get("prediction_coverage_fraction", 0.0)),
            "metadata": row.get("metadata", {}),
        }
        self.hitl_details_text.setPlainText(json.dumps(details, indent=2))

    def _stage_hitl_pseudo_labels_from_scope(self, _checked: bool = False) -> None:
        if not self.dataset_items:
            QMessageBox.warning(self, "No dataset", "Load images first.")
            return
        targets, scope_label = self._hitl_scope_items()
        result = stage_pseudo_labels(
            targets,
            self.annotations,
            self.predictions,
            self.prediction_metadata_by_uid,
            self.hitl_pseudo_labels,
            self.hitl_review_state,
            min_confidence=float(self.hitl_confidence_spin.value()),
        )
        staged = int(result.get("staged", 0))
        if staged > 0:
            self._set_dirty(True)
        self._refresh_hitl_view()
        QMessageBox.information(
            self,
            "Pseudo-label staging complete",
            f"Scope: {scope_label}\n"
            f"Staged: {staged}\n"
            f"Skipped labeled: {int(result.get('skipped_labeled', 0))}\n"
            f"Skipped low confidence: {int(result.get('skipped_low_conf', 0))}\n"
            f"Missing predictions: {int(result.get('skipped_missing', 0))}",
        )

    def _run_hitl_self_training_loop(self, _checked: bool = False) -> None:
        self.hitl_long_session_state = None
        requested_cycles = int(self.hitl_cycle_count_spin.value()) if hasattr(self, "hitl_cycle_count_spin") else 1
        self.hitl_long_session_cycle_count = max(1, requested_cycles)
        if requested_cycles > 1 and not self.hitl_auto_retrain_cb.isChecked():
            QMessageBox.information(
                self,
                "Long session adjusted",
                "Long-session cycles greater than 1 require auto-start retraining. "
                "Running a single HITL cycle with the current settings.",
            )
            requested_cycles = 1
        plan = {
            "remaining_cycles": max(0, requested_cycles - 1),
            "current_cycle": 1,
            "total_cycles": max(1, requested_cycles),
            "template_preset_key": self._hitl_selected_template_preset_key(),
            "input_folder": self.hitl_input_folder_edit.text().strip() if hasattr(self, "hitl_input_folder_edit") else "",
            "switch_to_trained_standard_model": True,
            "use_current_setup_after_first_cycle": True,
        }
        self._run_hitl_self_training_cycle(plan, first_cycle=True)

    def _run_hitl_self_training_cycle(self, plan: dict[str, object] | None = None, *, first_cycle: bool = False) -> None:
        if self._is_training_running():
            QMessageBox.warning(self, "Training in progress", "Wait for the current training run to finish before starting another HITL cycle.")
            return
        plan_obj = dict(plan or {})
        cycle_number = int(plan_obj.get("current_cycle", 1) or 1)
        total_cycles = int(plan_obj.get("total_cycles", 1) or 1)
        template_preset_key = str(plan_obj.get("template_preset_key", self._hitl_selected_template_preset_key()) or "current")
        if (
            not first_cycle
            and bool(plan_obj.get("use_current_setup_after_first_cycle", False))
            and self.training_last_output_model is not None
        ):
            template_preset_key = "current"
        try:
            template_label = self._apply_hitl_session_template(template_preset_key)
            scope_label, _loaded = self._ensure_hitl_session_dataset_loaded()
        except Exception as exc:
            QMessageBox.warning(self, "HITL session setup", str(exc))
            return
        if not self.dataset_items:
            QMessageBox.warning(self, "No dataset", "Load images first.")
            return
        try:
            self._validate_inference_ready()
        except Exception as exc:
            QMessageBox.warning(self, "Inference setup", str(exc))
            return
        if self.hitl_session_input_folder is not None:
            targets = list(self.dataset_items)
            scope_label = f"{scope_label} · template: {template_label}"
        else:
            targets, selected_scope = self._hitl_scope_items()
            scope_label = f"{selected_scope} · template: {template_label}"
        unlabeled = [
            item
            for item in targets
            if annotation_coverage_fraction(self.annotations.get(item.uid, {}), item.image.shape[:2]) <= 0.0
        ]
        if not unlabeled:
            QMessageBox.information(self, "Human-in-the-Loop", "All images in the chosen scope already have labels.")
            return

        progress = QProgressDialog("Running self-training loop...", "Cancel", 0, max(1, len(unlabeled)), self)
        progress.setWindowModality(Qt.WindowModal)
        progress.setMinimumDuration(0)
        QApplication.setOverrideCursor(Qt.WaitCursor)
        completed = 0
        try:
            predictions, metadata, completed = self._run_segmentation_for_items(unlabeled, progress=progress)
            any_updates = False
            for uid, prediction in predictions.items():
                self.predictions[uid] = prediction
                details = metadata.get(uid, {})
                if isinstance(details, dict):
                    self.prediction_metadata_by_uid[uid] = dict(details)
                any_updates = True
            if any_updates:
                self._mark_predictions_changed()
                self._set_dirty(True)
            stage_result = stage_pseudo_labels(
                unlabeled,
                self.annotations,
                self.predictions,
                self.prediction_metadata_by_uid,
                self.hitl_pseudo_labels,
                self.hitl_review_state,
                min_confidence=float(self.hitl_confidence_spin.value()),
            )
            auto_accept_result = auto_accept_pseudo_labels(
                unlabeled,
                self.annotations,
                self.hitl_pseudo_labels,
                self.hitl_review_state,
                min_confidence=float(self.hitl_confidence_spin.value()),
            )
            if int(auto_accept_result.get("auto_accepted", 0)) > 0:
                self._set_dirty(True)

            snapshot_items, snapshot_annotations, snapshot_summary = build_retrain_snapshot(
                self.dataset_items,
                self.classes,
                self.annotations,
                self.hitl_pseudo_labels,
                self.hitl_review_state,
            )
            synthetic_result = {"added": 0, "items": [], "annotations": {}}
            synthetic_target = max(0, int(self.hitl_min_auto_accept_spin.value()))
            auto_accepted = int(auto_accept_result.get("auto_accepted", 0))
            if synthetic_target > 0 and auto_accepted < synthetic_target:
                synthetic_result = self._augment_hitl_snapshot_with_synthetic(
                    snapshot_items,
                    snapshot_annotations,
                    additions_needed=synthetic_target - auto_accepted,
                )
                for synth_item in synthetic_result.get("items", []):
                    if isinstance(synth_item, DatasetImageItem):
                        snapshot_items.append(synth_item)
                for uid, per_class in dict(synthetic_result.get("annotations", {})).items():
                    if isinstance(per_class, dict):
                        snapshot_annotations[str(uid)] = {
                            int(class_id): np.asarray(mask, dtype=np.uint8).copy()
                            for class_id, mask in per_class.items()
                            if isinstance(mask, np.ndarray)
                        }
            if not snapshot_items:
                raise RuntimeError(
                    "The self-training loop did not produce any retraining samples. "
                    "Add a few labeled images first or lower the pseudo-label confidence threshold."
                )

            session_summary = {
                "scope": scope_label,
                "cycle_number": int(cycle_number),
                "total_cycles": int(total_cycles),
                "template_preset_key": template_preset_key,
                "template_label": template_label,
                "inference_completed": int(completed),
                "confidence_threshold": float(self.hitl_confidence_spin.value()),
                "staged": int(stage_result.get("staged", 0)),
                "auto_accepted": int(auto_accept_result.get("auto_accepted", 0)),
                "synthetic_added": int(synthetic_result.get("added", 0)),
                "snapshot": snapshot_summary,
                "training_requested": bool(self.hitl_auto_retrain_cb.isChecked()),
            }
            bundle_info = self._write_hitl_session_bundle(snapshot_items, snapshot_annotations, session_summary)

            retraining_started = False
            retraining_note = ""
            if self.hitl_auto_retrain_cb.isChecked():
                try:
                    config = self._build_training_config_from_ui()
                    training_dataset = [
                        DatasetImageItem(uid=item.uid, name=item.name, path=item.path, image=np.asarray(item.image, dtype=np.uint8).copy())
                        for item in snapshot_items
                    ]
                    training_annotations = {
                        str(uid): {
                            int(class_id): np.asarray(mask, dtype=np.uint8).copy()
                            for class_id, mask in per_class.items()
                        }
                        for uid, per_class in snapshot_annotations.items()
                    }
                    classes_copy = [
                        LabelClass(class_id=cls.class_id, name=cls.name, color_hex=cls.color_hex)
                        for cls in self.classes
                    ]
                    retraining_started = self._start_training_with_snapshot(
                        training_dataset,
                        training_annotations,
                        classes_copy,
                        config,
                        summary_text="Human-in-the-Loop retraining is running...",
                        startup_log=(
                            f"HITL session bundle prepared from {len(training_dataset)} image(s). "
                            f"Project: {bundle_info['project_path']}"
                        ),
                    )
                    if retraining_started:
                        if int(plan_obj.get("remaining_cycles", 0) or 0) > 0:
                            self.hitl_long_session_state = dict(plan_obj)
                        self.tabs.setCurrentWidget(self.training_tab)
                except Exception as exc:
                    retraining_note = f"Retraining was not started automatically: {exc}"
                    self.hitl_long_session_state = None
            else:
                self.hitl_long_session_state = None

            self._refresh_hitl_view()
            QMessageBox.information(
                self,
                "Self-training loop complete",
                f"Cycle: {cycle_number}/{total_cycles}\n"
                f"Scope: {scope_label}\n"
                f"Inference completed: {completed}\n"
                f"Pseudo-labels staged: {int(stage_result.get('staged', 0))}\n"
                f"Auto-accepted into retraining pool: {int(auto_accept_result.get('auto_accepted', 0))}\n"
                f"Synthetic boost samples: {int(synthetic_result.get('added', 0))}\n"
                f"Retrain bundle project:\n{bundle_info['project_path']}\n"
                f"Bundle summary:\n{bundle_info['summary_path']}\n"
                + ("Retraining started on the expanded set.\n" if retraining_started else "")
                + (f"{retraining_note}\n" if retraining_note else "")
                + (
                    f"Remaining long-session cycles after training: {int(plan_obj.get('remaining_cycles', 0))}\n"
                    if retraining_started and int(plan_obj.get("remaining_cycles", 0)) > 0
                    else ""
                )
                + "Low-confidence edge cases remain in the review queue so you can inspect them later.",
            )
        except Exception as exc:
            self.hitl_long_session_state = None
            QMessageBox.critical(self, "Self-training loop failed", str(exc))
        finally:
            progress.close()
            QApplication.restoreOverrideCursor()

    def _continue_hitl_long_session(self) -> None:
        plan = self.hitl_long_session_state
        if not isinstance(plan, dict):
            return
        remaining = int(plan.get("remaining_cycles", 0) or 0)
        if remaining <= 0:
            self.hitl_long_session_state = None
            return
        next_plan = dict(plan)
        next_plan["remaining_cycles"] = max(0, remaining - 1)
        next_plan["current_cycle"] = int(plan.get("current_cycle", 1) or 1) + 1
        self.hitl_long_session_state = next_plan
        self.statusBar().showMessage(
            f"Continuing Human-in-the-Loop long session: cycle {next_plan['current_cycle']}/{next_plan.get('total_cycles', next_plan['current_cycle'])}",
            5000,
        )
        QTimer.singleShot(0, lambda: self._run_hitl_self_training_cycle(next_plan, first_cycle=False))

    def _accept_hitl_selected_pseudo_labels(self, _checked: bool = False) -> None:
        uids = self._hitl_selected_uids()
        if not uids:
            QMessageBox.information(self, "No selection", "Select one or more queued images first.")
            return
        applied = 0
        for uid in uids:
            item = self._dataset_item_by_uid(uid)
            if item is None:
                continue
            index_mask = self._hitl_index_mask_for_uid(uid)
            if not isinstance(index_mask, np.ndarray):
                continue
            self._apply_index_mask_to_item_annotations(item, index_mask)
            state = dict(self.hitl_review_state.get(uid, {}))
            state["status"] = "accepted"
            self.hitl_review_state[uid] = state
            applied += 1
        if applied <= 0:
            QMessageBox.warning(self, "Nothing applied", "The selected rows do not currently have predictions or pseudo-labels.")
            return
        self._mark_annotations_changed()
        self._set_dirty(True)
        self._refresh_all_views()
        QMessageBox.information(self, "Pseudo-labels accepted", f"Accepted {applied} pseudo-label(s) into editable labels.")

    def _clear_hitl_selected(self, _checked: bool = False) -> None:
        uids = self._hitl_selected_uids()
        if not uids:
            QMessageBox.information(self, "No selection", "Select one or more queued images first.")
            return
        for uid in uids:
            self.hitl_pseudo_labels.pop(uid, None)
            self.hitl_review_state.pop(uid, None)
        self._set_dirty(True)
        self._refresh_hitl_view()

    def _open_hitl_selected_in_labeling(self, _checked: bool = False) -> None:
        uids = self._hitl_selected_uids()
        if not uids:
            QMessageBox.information(self, "No selection", "Select a queued image first.")
            return
        uid = uids[0]
        item = self._dataset_item_by_uid(uid)
        if item is None:
            QMessageBox.warning(self, "Missing image", "The selected image is no longer available.")
            return
        if annotation_coverage_fraction(self.annotations.get(uid, {}), item.image.shape[:2]) <= 0.0:
            index_mask = self._hitl_index_mask_for_uid(uid)
            if isinstance(index_mask, np.ndarray):
                self._apply_index_mask_to_item_annotations(item, index_mask)
                self._mark_annotations_changed()
        state = dict(self.hitl_review_state.get(uid, {}))
        if state.get("status") not in {"accepted", "refined"}:
            state["status"] = "opened"
        self.hitl_review_state[uid] = state
        self._set_dirty(True)
        self._set_current_item_by_uid(uid, switch_to_labeling=True)
        self._refresh_all_views()

    def _browse_hitl_synthetic_output_dir(self, _checked: bool = False) -> None:
        directory = QFileDialog.getExistingDirectory(
            self,
            "Synthetic output folder",
            self.hitl_synthetic_output_edit.text().strip() or str(self.hitl_synthetic_output_dir),
        )
        if not directory:
            return
        self.hitl_synthetic_output_dir = Path(directory).expanduser()
        self.hitl_synthetic_output_edit.setText(str(self.hitl_synthetic_output_dir))

    def _generate_hitl_synthetic_batch(self, _checked: bool = False) -> None:
        if not self.dataset_items:
            QMessageBox.warning(self, "No dataset", "Load images first.")
            return
        output_dir = Path(self.hitl_synthetic_output_edit.text().strip() or str(self.hitl_synthetic_output_dir)).expanduser()
        output_dir.mkdir(parents=True, exist_ok=True)
        source_items, scope_label = self._hitl_scope_items()
        labeled_items = [
            item
            for item in source_items
            if annotation_coverage_fraction(self.annotations.get(item.uid, {}), item.image.shape[:2]) > 0.0
        ]
        if not labeled_items:
            QMessageBox.warning(self, "No labeled sources", "The chosen scope does not contain labeled images yet.")
            return
        variants_per_image = int(self.hitl_synthetic_variants_spin.value())
        images_dir = output_dir / "images"
        images_dir.mkdir(parents=True, exist_ok=True)
        added = 0
        for item in labeled_items:
            layers = ensure_layer_map(self.annotations, item.uid, self.classes, item.image.shape[:2])
            variants = generate_synthetic_variants(
                np.asarray(item.image, dtype=np.uint8),
                {class_id: np.asarray(mask, dtype=np.uint8) for class_id, mask in layers.items()},
                count=variants_per_image,
                rng_seed=abs(hash((item.uid, variants_per_image))) % (2**32),
            )
            for variant_image, variant_layers, variant_meta in variants:
                stem = Path(item.name).stem
                uid = f"hitl_synth_{item.uid}_{int(time.time() * 1000)}_{added}"
                image_path = images_dir / f"{stem}__synth_{added:04d}.png"
                Image.fromarray(np.asarray(variant_image, dtype=np.uint8), mode="RGB").save(image_path)
                dataset_item = DatasetImageItem(
                    uid=uid,
                    name=image_path.name,
                    path=image_path,
                    image=np.asarray(variant_image, dtype=np.uint8),
                )
                self.dataset_items.append(dataset_item)
                self.annotations[uid] = {
                    int(class_id): np.asarray(mask, dtype=np.uint8).copy()
                    for class_id, mask in variant_layers.items()
                }
                self.series_by_uid[uid] = "Synthetic"
                if "Synthetic" not in self.series_order:
                    self.series_order.append("Synthetic")
                self.hitl_review_state[uid] = {
                    "status": "synthetic",
                    "source_uid": item.uid,
                    "augmentation": variant_meta,
                }
                added += 1
        if added <= 0:
            QMessageBox.information(self, "Synthetic generation", "No synthetic images were generated.")
            return
        self._mark_annotations_changed()
        self._set_dirty(True)
        self._refresh_series_widgets()
        self._refresh_dataset_widgets()
        self._refresh_all_views()
        QMessageBox.information(
            self,
            "Synthetic data generated",
            f"Scope: {scope_label}\nGenerated {added} synthetic image(s) into:\n{output_dir}",
        )

    def _run_hitl_external_gan_hook(self, _checked: bool = False) -> None:
        command = self.hitl_external_gan_edit.text().strip()
        if not command:
            QMessageBox.information(
                self,
                "External GAN hook",
                "Set a command first. Use placeholders like {output_dir} and {image_count}.",
            )
            return
        output_dir = Path(self.hitl_synthetic_output_edit.text().strip() or str(self.hitl_synthetic_output_dir)).expanduser()
        output_dir.mkdir(parents=True, exist_ok=True)
        source_items, _scope_label = self._hitl_scope_items()
        labeled_count = sum(
            1
            for item in source_items
            if annotation_coverage_fraction(self.annotations.get(item.uid, {}), item.image.shape[:2]) > 0.0
        )
        rendered = command.format(
            output_dir=str(output_dir),
            image_count=str(labeled_count),
            project_path=str(self.project_path) if self.project_path is not None else "",
        )
        completed = subprocess.run(
            rendered,
            shell=True,
            capture_output=True,
            text=True,
            cwd=str(Path(__file__).resolve().parent),
            check=False,
        )
        if completed.returncode != 0:
            detail = (completed.stderr or completed.stdout or "Unknown external GAN error.").strip()
            QMessageBox.warning(self, "GAN hook failed", detail)
            return
        QMessageBox.information(
            self,
            "GAN hook complete",
            f"External generator finished successfully.\nOutput folder:\n{output_dir}",
        )

    def _active_canvas(self) -> SegmentationCanvas:
        tab_idx = self.tabs.currentIndex()
        if tab_idx == 0:
            return self.label_canvas
        if tab_idx == 1:
            return self.gt_canvas
        if tab_idx == 2:
            return self.rf_seed_canvas
        if tab_idx == 3:
            return self.patch_canvas
        if tab_idx == 5:
            return self.timelapse_canvas
        if tab_idx == 6:
            return self.analytics_canvas
        if tab_idx == 7:
            return self.sensor_overlay_canvas
        if tab_idx == 8:
            return self.foundation_prompt_canvas
        if tab_idx == 9:
            return self.cons_preview_canvas
        if tab_idx == 10:
            return self.architecture_canvas
        if tab_idx == 11:
            return self.hitl_preview_canvas
        return self.label_canvas

    def _on_canvas_zoom_changed(self, zoom: float) -> None:
        self.zoom_status.setText(f"Zoom: {zoom * 100.0:.0f}%")

    def _on_tool_changed(self, action: QAction) -> None:
        tool = str(action.data())
        self.active_tool = tool
        self.label_canvas.set_tool(tool)
        self.patch_canvas.set_tool(tool)
        if hasattr(self, "rf_seed_canvas"):
            self.rf_seed_canvas.set_tool(tool)
        if hasattr(self, "rf_refine_canvas"):
            self.rf_refine_canvas.set_tool(tool)
        if hasattr(self, "foundation_prompt_canvas"):
            self.foundation_prompt_canvas.set_tool(tool)
        self._refresh_tool_status()
        self._refresh_patching_view()
        self._refresh_random_forest_view()
        self._refresh_foundation_view(update_info=False)

    def _focus_widget_blocks_class_shortcuts(self) -> bool:
        focus = QApplication.focusWidget()
        if focus is None:
            return False
        return isinstance(focus, (QLineEdit, QTextEdit, QSpinBox, QDoubleSpinBox, QComboBox))

    def _on_mask_move_scope_toggled(self, enabled: bool) -> None:
        self.mask_move_apply_visible_classes = bool(enabled)
        self._refresh_tool_status()

    def _select_active_class_by_id(self, class_id: int) -> bool:
        target_id = int(class_id)
        if target_id not in {int(cls.class_id) for cls in self.classes}:
            return False
        if hasattr(self, "class_list"):
            for row in range(self.class_list.count()):
                item = self.class_list.item(row)
                if item is None:
                    continue
                data = item.data(Qt.UserRole)
                try:
                    if int(data) == target_id:
                        self.class_list.setCurrentRow(row)
                        return True
                except Exception:
                    continue
        self.active_class_id = target_id
        self._sync_canvas_brush_colors()
        self._refresh_tool_status()
        self._refresh_all_views()
        return True

    def _select_class_from_numeric_shortcut(self, digit: int) -> bool:
        if digit <= 0:
            return False
        if self._select_active_class_by_id(int(digit)):
            return True
        if 1 <= int(digit) <= len(self.classes):
            return self._select_active_class_by_id(int(self.classes[int(digit) - 1].class_id))
        return False

    def _current_mask_move_target_class_ids(self, preferred_class_id: int | None = None) -> list[int]:
        if bool(getattr(self, "mask_move_apply_visible_classes", False)):
            visible_ids = [int(cls.class_id) for cls in self._visible_classes_for_render()]
            if visible_ids:
                return visible_ids
        if preferred_class_id is not None:
            return [int(preferred_class_id)]
        return [int(self.active_class_id)] if self._class_by_id(self.active_class_id) is not None else []

    def _translate_current_annotation_layers(
        self,
        dx: int,
        dy: int,
        *,
        context_key: str,
        preferred_class_id: int | None = None,
        description: str,
        finalize_after: bool,
    ) -> bool:
        item = self._current_item()
        if item is None:
            return False
        layers = self._current_layers()
        if layers is None:
            return False
        class_ids = self._current_mask_move_target_class_ids(preferred_class_id)
        if not class_ids:
            return False
        shift_x = int(dx)
        shift_y = int(dy)
        if shift_x == 0 and shift_y == 0:
            return False
        self._begin_stroke_history(str(context_key), "annotations", item.uid, str(description))
        changed_pixels = translate_selected_layers(layers, class_ids, shift_x, shift_y)
        if changed_pixels <= 0:
            self._pending_stroke_history.pop(str(context_key), None)
            if finalize_after:
                self._finalize_stroke_history(str(context_key))
            return False
        self._mark_annotations_changed()
        self._set_dirty(True)
        if finalize_after:
            self._finalize_stroke_history(str(context_key))
        self._refresh_all_views()
        return True

    def _on_label_mask_nudged(self, dx: int, dy: int) -> None:
        self._translate_current_annotation_layers(
            int(dx),
            int(dy),
            context_key="label_move",
            preferred_class_id=int(self.active_class_id),
            description="Move label mask",
            finalize_after=False,
        )

    def _on_label_mask_nudge_finished(self) -> None:
        finalized = self._finalize_stroke_history("label_move")
        if finalized and self.tabs.currentIndex() == 0:
            self._refresh_labeling_view(update_stats=True)

    def _on_patch_mask_nudged(self, dx: int, dy: int) -> None:
        self._translate_current_annotation_layers(
            int(dx),
            int(dy),
            context_key="patch_move",
            preferred_class_id=int(self.patch_target_class_id),
            description="Move patch mask",
            finalize_after=False,
        )

    def _on_patch_mask_nudge_finished(self) -> None:
        finalized = self._finalize_stroke_history("patch_move")
        if finalized and self.tabs.currentIndex() == 3:
            self._refresh_patching_view()

    def _on_mask_nudge_shortcut(self, dx: int, dy: int) -> None:
        if self._focus_widget_blocks_class_shortcuts():
            return
        if str(self.active_tool).lower() != "move":
            return
        tab_idx = int(self.tabs.currentIndex()) if hasattr(self, "tabs") else 0
        if tab_idx == 0:
            moved = self._translate_current_annotation_layers(
                int(dx),
                int(dy),
                context_key="label_move_key",
                preferred_class_id=int(self.active_class_id),
                description="Nudge label mask",
                finalize_after=True,
            )
        elif tab_idx == 3:
            moved = self._translate_current_annotation_layers(
                int(dx),
                int(dy),
                context_key="patch_move_key",
                preferred_class_id=int(self.patch_target_class_id),
                description="Nudge patch mask",
                finalize_after=True,
            )
        else:
            moved = False
        if moved:
            scope = "visible classes" if bool(getattr(self, "mask_move_apply_visible_classes", False)) else "active class"
            self.statusBar().showMessage(f"Moved {scope} by dx={int(dx)}, dy={int(dy)}.", 1500)

    def _wand_prediction_cache_key(self, item: DatasetImageItem) -> tuple[object, ...]:
        backend = str(self._current_inference_backend())
        if backend == "pyphenotyper":
            return (
                "wand",
                str(item.uid),
                backend,
                str(self.pyphenotyper_preset_key),
                str(self.pyphenotyper_pipeline_dir or ""),
                str(self.pyphenotyper_root_model_path or ""),
                str(self.pyphenotyper_shoot_model_path or ""),
                str(self.pyphenotyper_seed_model_path or ""),
                int(self.pyphenotyper_patch_size_spin.value()) if hasattr(self, "pyphenotyper_patch_size_spin") else 0,
                int(self.pyphenotyper_refinement_steps_spin.value()) if hasattr(self, "pyphenotyper_refinement_steps_spin") else 0,
                int(self.pyphenotyper_root_class_combo.currentData() or 0) if hasattr(self, "pyphenotyper_root_class_combo") else 0,
                int(self.pyphenotyper_shoot_class_combo.currentData() or 0) if hasattr(self, "pyphenotyper_shoot_class_combo") else 0,
                int(self.pyphenotyper_seed_class_combo.currentData() or 0) if hasattr(self, "pyphenotyper_seed_class_combo") else 0,
            )
        return ("wand", str(item.uid), backend, str(self.model_path or ""))

    def _wand_prediction_for_item(self, item: DatasetImageItem) -> np.ndarray:
        cached_prediction = self.predictions.get(item.uid)
        if isinstance(cached_prediction, np.ndarray) and cached_prediction.shape[:2] == item.image.shape[:2]:
            return self._ensure_index_mask_shape(cached_prediction, item.image.shape[:2])

        cache_key = self._wand_prediction_cache_key(item)
        cached = self._wand_prediction_cache.get(cache_key)
        if isinstance(cached, np.ndarray) and cached.shape[:2] == item.image.shape[:2]:
            return np.asarray(cached, dtype=np.uint8)

        self._validate_inference_ready()
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            prediction, _details = self._run_inference_item(item)
        finally:
            QApplication.restoreOverrideCursor()
        pred_u8 = self._ensure_index_mask_shape(np.asarray(prediction, dtype=np.uint8), item.image.shape[:2])
        self._wand_prediction_cache[cache_key] = pred_u8
        if len(self._wand_prediction_cache) > 96:
            self._wand_prediction_cache.pop(next(iter(self._wand_prediction_cache)), None)
        return pred_u8

    def _wand_stroke_for_item(
        self,
        item: DatasetImageItem,
        target_class_id: int,
        point_xy: tuple[int, int],
    ) -> dict[str, object] | None:
        prediction = self._wand_prediction_for_item(item)
        return build_wand_stroke_from_prediction(
            prediction,
            int(target_class_id),
            (int(point_xy[0]), int(point_xy[1])),
            search_radius=max(4, int(round(max(1, self.brush_size) * 0.75))),
            min_component_area=1,
        )

    def _should_use_immediate_label_stroke_refresh(self, bbox: tuple[int, int, int, int] | None) -> bool:
        if bbox is None:
            return False
        if str(self.active_tool) not in {"brush", "eraser", "razor"}:
            return False
        if int(self.brush_size) > 3:
            return False
        width = max(1, int(bbox[2]) - int(bbox[0]) + 1)
        height = max(1, int(bbox[3]) - int(bbox[1]) + 1)
        return (width * height) <= 4096

    def _on_brush_size_changed(self, size: int) -> None:
        self.brush_size = int(size)
        self.label_canvas.set_brush_size(self.brush_size)
        self.patch_canvas.set_brush_size(self.brush_size)
        if hasattr(self, "rf_seed_canvas"):
            self.rf_seed_canvas.set_brush_size(self.brush_size)
        if hasattr(self, "rf_refine_canvas"):
            self.rf_refine_canvas.set_brush_size(self.brush_size)
        if hasattr(self, "foundation_prompt_canvas"):
            self.foundation_prompt_canvas.set_brush_size(self.brush_size)

    def _adjust_brush(self, delta: int) -> None:
        current = self.brush_slider.value()
        minimum = self.brush_slider.minimum() if hasattr(self, "brush_slider") else 1
        maximum = self.brush_slider.maximum() if hasattr(self, "brush_slider") else 320
        self.brush_slider.setValue(max(minimum, min(maximum, current + int(delta))))

    def _brush_step_for_keys(self) -> int:
        size = int(self.brush_slider.value()) if hasattr(self, "brush_slider") else int(self.brush_size)
        return 1 if size < 10 else 2

    def _brush_step_for_wheel(self) -> int:
        if self.brush_size < 10:
            return 1
        if self.brush_size >= 200:
            return 16
        if self.brush_size >= 120:
            return 8
        if self.brush_size >= 64:
            return 4
        return 2

    def _on_canvas_brush_adjust(self, direction: int) -> None:
        raw = int(direction)
        if raw == 0:
            return
        step = self._brush_step_for_wheel()
        self._adjust_brush((1 if raw > 0 else -1) * step)

    def _on_overlay_alpha_changed(self, value: int) -> None:
        self.overlay_alpha = max(0.05, min(0.95, value / 100.0))
        self._refresh_all_views()

    def _on_preview_contrast_changed(self, value: int) -> None:
        self.preview_contrast = max(0.50, min(2.50, float(value) / 100.0))
        if hasattr(self, "contrast_value_label"):
            self.contrast_value_label.setText(f"{self.preview_contrast:.2f}x")
        self._invalidate_model_cache()
        self._refresh_all_views()

    def _on_mask_edge_thickness_changed(self, value: int) -> None:
        self.mask_edge_thickness = max(0, min(12, int(value)))
        if hasattr(self, "mask_edge_label"):
            self.mask_edge_label.setText(f"{self.mask_edge_thickness} px")
        self._invalidate_model_cache()
        self._refresh_all_views()

    def _on_mask_edge_alpha_changed(self, value: int) -> None:
        self.mask_edge_alpha = max(0.10, min(1.00, float(value) / 100.0))
        if hasattr(self, "mask_edge_alpha_label"):
            self.mask_edge_alpha_label.setText(f"{self.mask_edge_alpha:.2f}")
        self._invalidate_model_cache()
        self._refresh_all_views()

    def _on_split_compare_changed(self, value: int) -> None:
        self.split_compare_label.setText(f"{int(value)}%")
        if self._model_split_refresh_timer.isActive():
            self._model_split_refresh_timer.stop()
        self._model_split_refresh_timer.start()

    def _flush_model_split_refresh(self) -> None:
        if hasattr(self, "tabs") and int(self.tabs.currentIndex()) != 1:
            return
        self._refresh_model_split_only()

    def _compose_split_compare_image(
        self,
        gt_overlay: np.ndarray,
        pred_overlay: np.ndarray,
        ratio_percent: int,
    ) -> np.ndarray:
        gt_u8 = np.asarray(gt_overlay, dtype=np.uint8)
        pred_u8 = np.asarray(pred_overlay, dtype=np.uint8)
        if gt_u8.ndim != 3 or pred_u8.ndim != 3:
            raise ValueError("Split compare expects RGB overlays.")
        h = min(gt_u8.shape[0], pred_u8.shape[0])
        w = min(gt_u8.shape[1], pred_u8.shape[1])
        if h <= 0 or w <= 0:
            return np.zeros((1, 1, 3), dtype=np.uint8)
        if gt_u8.shape[:2] != (h, w):
            gt_u8 = cv2.resize(gt_u8, (w, h), interpolation=cv2.INTER_LINEAR)
        if pred_u8.shape[:2] != (h, w):
            pred_u8 = cv2.resize(pred_u8, (w, h), interpolation=cv2.INTER_LINEAR)
        split_ratio = max(0.0, min(1.0, float(ratio_percent) / 100.0))
        split_x = int(round(w * split_ratio))
        split_x = max(0, min(w, split_x))
        split_image = gt_u8.copy()
        split_image[:, split_x:] = pred_u8[:, split_x:]
        if 0 < split_x < split_image.shape[1]:
            split_image[:, split_x - 1 : split_x + 1] = np.array([255, 255, 255], dtype=np.uint8)
        return split_image

    def _refresh_model_split_only(self) -> None:
        if not hasattr(self, "split_canvas"):
            return
        item = self._current_item()
        if item is None:
            self.split_canvas.set_image(None)
            return
        cached = self._model_view_cache.get(item.uid)
        if not isinstance(cached, dict):
            self._refresh_model_view()
            return
        gt_overlay = cached.get("gt_overlay")
        pred_overlay = cached.get("pred_overlay")
        if not isinstance(gt_overlay, np.ndarray) or not isinstance(pred_overlay, np.ndarray):
            self._refresh_model_view()
            return
        try:
            split_image = self._compose_split_compare_image(
                gt_overlay,
                pred_overlay,
                int(self.split_compare_slider.value()) if hasattr(self, "split_compare_slider") else 50,
            )
        except Exception:
            self._refresh_model_view()
            return
        self.split_canvas.set_image(split_image)
        cached["split_overlay"] = split_image

    def _on_tablet_pressure_toggled(self, enabled: bool) -> None:
        self.label_canvas.set_tablet_pressure_enabled(enabled)
        self.patch_canvas.set_tablet_pressure_enabled(enabled)
        if hasattr(self, "rf_seed_canvas"):
            self.rf_seed_canvas.set_tablet_pressure_enabled(enabled)
        if hasattr(self, "rf_refine_canvas"):
            self.rf_refine_canvas.set_tablet_pressure_enabled(enabled)
        if hasattr(self, "foundation_prompt_canvas"):
            self.foundation_prompt_canvas.set_tablet_pressure_enabled(enabled)
        self._refresh_labeling_view()
        self._refresh_patching_view()
        self._refresh_foundation_view(update_info=False)

    def _current_inference_backend(self) -> str:
        if not hasattr(self, "inference_backend_combo"):
            return "standard"
        data = self.inference_backend_combo.currentData()
        backend = str(data) if data is not None else "standard"
        return backend if backend in {"standard", "hailo", "pyphenotyper"} else "standard"

    def _resolve_bundled_resource_path(self, *parts: str) -> Path | None:
        candidate_roots: list[Path] = []

        module_root = Path(__file__).resolve().parent
        candidate_roots.append(module_root)

        executable_path = Path(sys.executable).resolve() if getattr(sys, "executable", None) else None
        if executable_path is not None:
            exe_dir = executable_path.parent
            candidate_roots.extend(
                [
                    exe_dir,
                    exe_dir / "resources",
                    exe_dir / "_internal",
                    exe_dir / "_internal" / "resources",
                    exe_dir.parent / "Resources",
                    exe_dir.parent / "Resources" / "resources",
                    exe_dir.parent / "Frameworks",
                    exe_dir.parent / "Frameworks" / "_internal",
                    exe_dir.parent / "Frameworks" / "_internal" / "resources",
                ]
            )

        meipass = getattr(sys, "_MEIPASS", None)
        if meipass is not None:
            meipass_root = Path(meipass)
            candidate_roots.extend(
                [
                    meipass_root,
                    meipass_root / "resources",
                ]
            )

        seen: set[str] = set()
        for root in candidate_roots:
            key = str(root)
            if key in seen:
                continue
            seen.add(key)
            candidate = root.joinpath(*parts)
            if candidate.exists():
                return candidate
        return None

    def _detect_builtin_pyphenotyper_pipeline_dir(self) -> Path | None:
        candidate = self._resolve_bundled_resource_path("npec_pyphenotyper")
        if candidate is None:
            return None
        features_path = candidate / "pyphenotyper" / "features" / "features.py"
        return candidate if features_path.exists() else None

