    def _detect_builtin_five_seedling_owner_profile(self) -> dict[str, object] | None:
        profile_path = self._resolve_bundled_resource_path(
            "builtin_models",
            "five_seedling_ownership",
            "yang_rgb_owner_ranker_v1.json",
        )
        if profile_path is None:
            return None
        try:
            payload = json.loads(profile_path.read_text(encoding="utf-8"))
        except Exception:
            return None
        if not isinstance(payload, dict) or not isinstance(payload.get("ranker"), dict):
            return None
        return payload

    def _apply_builtin_five_seedling_owner_profile(
        self,
        config: AnalyticsConfig,
    ) -> bool:
        eligible = bool(
            int(getattr(config, "expected_track_count", 0) or 0) == 5
            and str(getattr(config, "tracking_mode", "") or "").strip().lower()
            == "arabidopsis_crown_lanes"
            and str(
                getattr(config, "root_ownership_assignment_mode", "") or ""
            ).strip().lower()
            in {"temporal_graph", "graph", "geodesic", "skeleton_graph"}
        )
        if not eligible:
            config.learned_owner_enabled = False
            config.learned_owner_ranker_payload = None
            return False
        profile = self._detect_builtin_five_seedling_owner_profile()
        if profile is None:
            config.learned_owner_enabled = False
            config.learned_owner_ranker_payload = None
            return False
        config.learned_owner_enabled = True
        config.learned_owner_ranker_payload = profile
        config.learned_owner_feature_set = str(
            profile.get("feature_set", "crown_coordinates_orientation")
            or "crown_coordinates_orientation"
        )
        config.learned_owner_support_margin = float(
            profile.get("support_margin", 0.50) or 0.50
        )
        config.learned_owner_prior_weight_px = float(
            profile.get("prior_weight_px", 4.0) or 4.0
        )
        config.learned_owner_temporal_score_bonus = float(
            profile.get("temporal_score_bonus", 0.18) or 0.18
        )
        config.learned_owner_qc_margin = float(
            profile.get("qc_margin", 0.10) or 0.10
        )
        return True

