    def _dataset_prefers_rgb_scale(self) -> bool:
        items = self._selected_dataset_items()
        if not items:
            items = list(self.dataset_items[: min(len(self.dataset_items), 24)])
        if not items:
            return False

        rgb_like = 0
        for item in items:
            image = np.asarray(item.image)
            if image.ndim != 3 or image.shape[2] < 3:
                continue
            rgb = image[..., :3].astype(np.int16, copy=False)
            channel_delta = max(
                float(np.mean(np.abs(rgb[..., 0] - rgb[..., 1]))),
                float(np.mean(np.abs(rgb[..., 1] - rgb[..., 2]))),
                float(np.mean(np.abs(rgb[..., 0] - rgb[..., 2]))),
            )
            if channel_delta > 0.5:
                rgb_like += 1
        return rgb_like >= max(1, int(np.ceil(len(items) * 0.5)))

    def _preset_default_pixel_size_mm(self, preset_key: str) -> float | None:
        key = str(preset_key or "custom")
        if key == "potato_builtin":
            return float(POTATO_PIXEL_SIZE_MM)
        if key == "hades_lucifer_builtin":
            return float(HADES_PIXEL_SIZE_MM)
        if key in {"lucifer_builtin", "lucifer_inoculated_builtin"}:
            return float(LUCIFER_PIXEL_SIZE_MM)
        if key == "mxlab_dark_rgb_builtin":
            return float(LUCIFER_PIXEL_SIZE_MM)
        if key in {"hades_lucifer_auto_hybrid", "general_root_starter_auto"}:
            return float(LUCIFER_PIXEL_SIZE_MM if self._dataset_prefers_rgb_scale() else HADES_PIXEL_SIZE_MM)
        return None

    def _preset_fixed_patch_size(self, preset_key: str) -> int | None:
        key = str(preset_key or "custom")
        if key in {
            "potato_builtin",
            "hades_lucifer_builtin",
            "lucifer_builtin",
            "lucifer_inoculated_builtin",
            "hades_lucifer_auto_hybrid",
            "mxlab_dark_rgb_builtin",
            "general_root_starter_auto",
        }:
            return 256
        return None

    def _set_pixel_size_defaults(
        self,
        pixel_size_mm: float | None,
        *,
        sync_analytics: bool = True,
        mark_dirty: bool = False,
        status_hint: str | None = None,
    ) -> bool:
        if pixel_size_mm is None:
            return False
        value = float(pixel_size_mm)
        if value <= 0.0:
            return False
        changed = False
        if hasattr(self, "pyphenotyper_pixel_size_mm_spin"):
            if abs(float(self.pyphenotyper_pixel_size_mm_spin.value()) - value) > 1.0e-9:
                self.pyphenotyper_pixel_size_mm_spin.blockSignals(True)
                self.pyphenotyper_pixel_size_mm_spin.setValue(value)
                self.pyphenotyper_pixel_size_mm_spin.blockSignals(False)
                changed = True
        if sync_analytics and hasattr(self, "analytics_pixel_size_spin"):
            if abs(float(self.analytics_pixel_size_spin.value()) - value) > 1.0e-9:
                self.analytics_pixel_size_spin.blockSignals(True)
                self.analytics_pixel_size_spin.setValue(value)
                self.analytics_pixel_size_spin.blockSignals(False)
                changed = True
        if changed and status_hint:
            self.statusBar().showMessage(status_hint, 5000)
        if changed and mark_dirty:
            self._set_dirty(True)
        return changed

    def _apply_detected_pipeline_scale(
        self,
        pipeline_dir: Path | None,
        *,
        sync_analytics: bool = True,
        mark_dirty: bool = False,
    ) -> bool:
        if pipeline_dir is None:
            return False
        pixel_size_mm, source = detect_pyphenotyper_pixel_size_mm(pipeline_dir)
        if pixel_size_mm is None:
            return False
        source_name = Path(str(source)).name if source else "pipeline metadata"
        return self._set_pixel_size_defaults(
            float(pixel_size_mm),
            sync_analytics=sync_analytics,
            mark_dirty=mark_dirty,
            status_hint=f"Loaded PyPhenotyper scale {float(pixel_size_mm):.5f} mm/px from {source_name}.",
        )

