    def _apply_pyphenotyper_preset(self, preset_key: str, mark_dirty: bool = True) -> bool:
        self.pyphenotyper_preset_key = str(preset_key or "custom")
        if self.pyphenotyper_preset_key in {
            "mxlab_dark_rgb_builtin",
            "hades_lucifer_builtin",
            "lucifer_builtin",
            "lucifer_inoculated_builtin",
            "hades_lucifer_auto_hybrid",
            "potato_builtin",
            "general_root_starter_auto",
        }:
            pipeline_dir = self._detect_builtin_pyphenotyper_pipeline_dir()
            seed_model = None
            if self.pyphenotyper_preset_key == "potato_builtin":
                root_model, shoot_model = self._detect_builtin_potato_model_paths()
            elif self.pyphenotyper_preset_key == "mxlab_dark_rgb_builtin":
                root_model, shoot_model, seed_model = self._detect_builtin_mxlab_dark_rgb_mixed_model_paths()
            elif self.pyphenotyper_preset_key == "lucifer_builtin":
                root_model, shoot_model = self._detect_builtin_lucifer_model_paths()
            elif self.pyphenotyper_preset_key == "lucifer_inoculated_builtin":
                root_model, _legacy_shoot_model = self._detect_builtin_lucifer_model_paths()
                shoot_model = self._detect_builtin_rgb_inoculated_model_path()
            elif self.pyphenotyper_preset_key == "general_root_starter_auto":
                experts = self._general_root_starter_builtin_experts()
                if not experts:
                    return False
                root_model = experts[0].root_model_path
                shoot_model = experts[0].shoot_model_path
            else:
                root_model, shoot_model = self._detect_builtin_hades_lucifer_model_paths()
            if pipeline_dir is None or root_model is None or shoot_model is None:
                return False
            lucifer_root_model = None
            lucifer_shoot_model = None
            general_experts: tuple[PyPhenotyperExpertConfig, ...] = ()
            if self.pyphenotyper_preset_key == "hades_lucifer_auto_hybrid":
                lucifer_root_model, lucifer_shoot_model = self._detect_builtin_lucifer_model_paths()
                if lucifer_root_model is None or lucifer_shoot_model is None:
                    return False
            elif self.pyphenotyper_preset_key == "general_root_starter_auto":
                general_experts = self._general_root_starter_builtin_experts()
                if not general_experts:
                    return False
            self.pyphenotyper_pipeline_dir = pipeline_dir
            self.pyphenotyper_root_model_path = root_model
            self.pyphenotyper_shoot_model_path = shoot_model
            self.pyphenotyper_seed_model_path = seed_model
            self._wand_prediction_cache.clear()
            if hasattr(self, "pyphenotyper_pipeline_edit"):
                self.pyphenotyper_pipeline_edit.setText(str(self.pyphenotyper_pipeline_dir))
            if hasattr(self, "pyphenotyper_root_model_edit"):
                if self.pyphenotyper_preset_key == "hades_lucifer_auto_hybrid" and lucifer_root_model is not None:
                    self.pyphenotyper_root_model_edit.setText(
                        f"BW: {self.pyphenotyper_root_model_path.name} | RGB: {lucifer_root_model.name}"
                    )
                elif self.pyphenotyper_preset_key == "general_root_starter_auto" and general_experts:
                    self.pyphenotyper_root_model_edit.setText(
                        " | ".join(f"{expert.label}: {expert.root_model_path.name}" for expert in general_experts)
                    )
                else:
                    self.pyphenotyper_root_model_edit.setText(str(self.pyphenotyper_root_model_path))
            if hasattr(self, "pyphenotyper_shoot_model_edit"):
                if self.pyphenotyper_preset_key == "hades_lucifer_auto_hybrid" and lucifer_shoot_model is not None:
                    self.pyphenotyper_shoot_model_edit.setText(
                        f"BW: {self.pyphenotyper_shoot_model_path.name} | RGB: {lucifer_shoot_model.name}"
                    )
                elif self.pyphenotyper_preset_key == "general_root_starter_auto" and general_experts:
                    self.pyphenotyper_shoot_model_edit.setText(
                        " | ".join(f"{expert.label}: {expert.shoot_model_path.name}" for expert in general_experts)
                    )
                elif self.pyphenotyper_preset_key == "mxlab_dark_rgb_builtin" and seed_model is not None:
                    self.pyphenotyper_shoot_model_edit.setText(
                        f"{self.pyphenotyper_shoot_model_path.name} | seed: {seed_model.name}"
                    )
                else:
                    self.pyphenotyper_shoot_model_edit.setText(str(self.pyphenotyper_shoot_model_path))
            if hasattr(self, "pyphenotyper_patch_size_spin"):
                fixed_patch_size = self._preset_fixed_patch_size(self.pyphenotyper_preset_key)
                if fixed_patch_size is not None:
                    self.pyphenotyper_patch_size_spin.setValue(int(fixed_patch_size))
            if hasattr(self, "pyphenotyper_refinement_steps_spin"):
                self.pyphenotyper_refinement_steps_spin.setValue(2)
            if hasattr(self, "pyphenotyper_include_occlusion_cb"):
                self.pyphenotyper_include_occlusion_cb.setChecked(
                    self.pyphenotyper_preset_key != "lucifer_inoculated_builtin"
                )
            if hasattr(self, "pyphenotyper_enable_bbox_tracking_cb"):
                self.pyphenotyper_enable_bbox_tracking_cb.setChecked(True)
            self._set_pixel_size_defaults(
                self._preset_default_pixel_size_mm(self.pyphenotyper_preset_key),
                sync_analytics=True,
                mark_dirty=False,
            )
            if hasattr(self, "class_list"):
                self._ensure_segmentation_pipeline_classes(
                    select_defaults=True,
                    include_seed=self.pyphenotyper_preset_key == "mxlab_dark_rgb_builtin",
                )
                self._pending_pyphenotyper_class_defaults = False
            else:
                self._pending_pyphenotyper_class_defaults = True
        else:
            self.pyphenotyper_seed_model_path = None
            self._pending_pyphenotyper_class_defaults = False
        self._update_model_info_label()
        self._refresh_general_root_starter_controls()
        if mark_dirty:
            self._set_dirty(True)
        return True

    def _on_pyphenotyper_preset_changed(self, _index: int = 0) -> None:
        preset_key = str(self.pyphenotyper_preset_combo.currentData() or "custom")
        if self._apply_pyphenotyper_preset(preset_key, mark_dirty=True):
            if preset_key in {
                "hades_lucifer_builtin",
                "lucifer_builtin",
                "lucifer_inoculated_builtin",
                "hades_lucifer_auto_hybrid",
            }:
                self._activate_arabidopsis_lazy_defaults(
                    lucifer_rgb=preset_key in {"lucifer_builtin", "lucifer_inoculated_builtin"},
                )
            if hasattr(self, "cons_preset_combo"):
                idx = self.cons_preset_combo.findData(preset_key)
                if idx >= 0 and int(self.cons_preset_combo.currentIndex()) != int(idx):
                    self.cons_preset_combo.blockSignals(True)
                    self.cons_preset_combo.setCurrentIndex(idx)
                    self.cons_preset_combo.blockSignals(False)
            return
        QMessageBox.warning(self, "Preset unavailable", f"The preset '{preset_key}' is missing bundled files.")
        idx_custom = self.pyphenotyper_preset_combo.findData("custom")
        if idx_custom >= 0:
            self.pyphenotyper_preset_combo.blockSignals(True)
            self.pyphenotyper_preset_combo.setCurrentIndex(idx_custom)
            self.pyphenotyper_preset_combo.blockSignals(False)
        self._apply_pyphenotyper_preset("custom", mark_dirty=False)
        if hasattr(self, "cons_preset_combo"):
            cons_idx = self.cons_preset_combo.findData("custom")
            if cons_idx >= 0:
                self.cons_preset_combo.blockSignals(True)
                self.cons_preset_combo.setCurrentIndex(cons_idx)
                self.cons_preset_combo.blockSignals(False)

    def _detect_external_tf_python_from_env(self, framework: str | None = None) -> Path | None:
        normalized = str(framework or "").strip().lower()
        if normalized == "pytorch":
            env_candidates = [
                os.environ.get("NPEC_EXTERNAL_TRAINING_PYTHON"),
                os.environ.get("NPEC_EXTERNAL_TORCH_PYTHON"),
                os.environ.get("NPEC_EXTERNAL_TF_PYTHON"),
                os.environ.get("NPEC_TF_PYTHON"),
            ]
        elif normalized == "tensorflow":
            env_candidates = [
                os.environ.get("NPEC_EXTERNAL_TRAINING_PYTHON"),
                os.environ.get("NPEC_EXTERNAL_TF_PYTHON"),
                os.environ.get("NPEC_TF_PYTHON"),
                os.environ.get("NPEC_EXTERNAL_TORCH_PYTHON"),
            ]
        else:
            env_candidates = [
                os.environ.get("NPEC_EXTERNAL_TRAINING_PYTHON"),
                os.environ.get("NPEC_EXTERNAL_TORCH_PYTHON"),
                os.environ.get("NPEC_EXTERNAL_TF_PYTHON"),
                os.environ.get("NPEC_TF_PYTHON"),
            ]
        for raw in env_candidates:
            if not raw:
                continue
            try:
                candidate = Path(raw).expanduser().absolute()
            except Exception:
                continue
            if candidate.exists() and candidate.is_file():
                return candidate
        return None

    def _external_runtime_probe_candidates(self) -> list[Path]:
        return common_external_python_candidates()

    def _auto_detect_external_runtime_python_path(self, framework: str | None = None) -> Path | None:
        normalized = str(framework or "tensorflow").strip().lower()
        if normalized not in {"tensorflow", "pytorch"}:
            normalized = "tensorflow"
        cached = self._external_runtime_autodetect_cache.get(normalized)
        if cached is not None or normalized in self._external_runtime_autodetect_cache:
            return cached

        env_candidate = self._detect_external_tf_python_from_env(normalized)
        if env_candidate is not None:
            self._external_runtime_autodetect_cache[normalized] = env_candidate
            return env_candidate

        best_cpu_candidate: Path | None = None
        for candidate in self._external_runtime_probe_candidates():
            if not candidate.exists() or not candidate.is_file():
                continue
            try:
                info = detect_training_backends(external_python=candidate, framework=normalized)
            except Exception:
                continue
            if not bool(info.get("available", False)):
                continue
            if int(info.get("gpu_count") or 0) > 0:
                self._external_runtime_autodetect_cache[normalized] = candidate
                return candidate
            if best_cpu_candidate is None:
                best_cpu_candidate = candidate

        self._external_runtime_autodetect_cache[normalized] = best_cpu_candidate
        return best_cpu_candidate

    def _default_foundation_external_runner_path(self) -> Path | None:
        candidate = self._resolve_bundled_resource_path("foundation_external_runner.py")
        if candidate is not None and candidate.is_file():
            return candidate
        return None

    def _detect_foundation_external_python_from_env(self) -> Path | None:
        env_candidates = [
            os.environ.get("NPEC_FOUNDATION_PYTHON"),
            os.environ.get("NPEC_EXTERNAL_TF_PYTHON"),
            os.environ.get("NPEC_TF_PYTHON"),
        ]
        for raw in env_candidates:
            if not raw:
                continue
            try:
                candidate = Path(raw).expanduser().absolute()
            except Exception:
                continue
            if candidate.exists() and candidate.is_file():
                return candidate
        return self.external_tf_python_path

    def _resolved_foundation_external_python_path(self, strict: bool = False) -> Path | None:
        candidate: Path | None = self.foundation_external_python_path
        raw_text = ""
        if hasattr(self, "foundation_external_python_edit"):
            raw_text = self.foundation_external_python_edit.text().strip()
            if raw_text:
                try:
                    candidate = Path(raw_text).expanduser().absolute()
                except Exception:
                    candidate = Path(raw_text).expanduser()
        if candidate is None:
            return None
        if candidate.exists() and candidate.is_file():
            return candidate
        if strict and (raw_text or self.foundation_external_python_path is not None):
            raise RuntimeError(f"Foundation external python path is invalid: {candidate}")
        return None

    def _set_foundation_external_python_path(self, path: Path | None, mark_dirty: bool = True) -> None:
        normalized: Path | None = None
        if path is not None:
            candidate = Path(path).expanduser().absolute()
            if not candidate.exists() or not candidate.is_file():
                raise ValueError(f"Python executable not found: {candidate}")
            normalized = candidate
        self.foundation_external_python_path = normalized
        if hasattr(self, "foundation_external_python_edit"):
            self.foundation_external_python_edit.setText(str(normalized) if normalized is not None else "")
        if mark_dirty:
            self._set_dirty(True)

