    def _selected_dataset_items(self) -> list[DatasetImageItem]:
        rows = sorted({idx.row() for idx in self.timeline_list.selectedIndexes() if idx.isValid()})
        items: list[DatasetImageItem] = []
        for row in rows:
            if 0 <= row < len(self._visible_dataset_indices):
                dataset_index = self._visible_dataset_indices[row]
                if 0 <= dataset_index < len(self.dataset_items):
                    items.append(self.dataset_items[dataset_index])
        return items

    def _refresh_dataset_action_states(self) -> None:
        button = getattr(self, "remove_dataset_btn", None)
        rotate_left_btn = getattr(self, "rotate_left_btn", None)
        rotate_right_btn = getattr(self, "rotate_right_btn", None)
        if not isinstance(button, QPushButton):
            return
        selected_count = len(self._selected_dataset_items()) if hasattr(self, "timeline_list") else 0
        has_current = 0 <= int(self.current_index) < len(self.dataset_items)
        has_target = selected_count > 0 or has_current
        button.setEnabled(bool(self.dataset_items) and has_target)
        if isinstance(rotate_left_btn, QPushButton):
            rotate_left_btn.setEnabled(bool(self.dataset_items) and has_target)
        if isinstance(rotate_right_btn, QPushButton):
            rotate_right_btn.setEnabled(bool(self.dataset_items) and has_target)
        if selected_count > 1:
            remove_tip = f"Remove {selected_count} selected images from the current project. Files on disk are not deleted."
            rotate_left_tip = f"Rotate {selected_count} selected images 90 degrees counterclockwise inside the current project."
            rotate_right_tip = f"Rotate {selected_count} selected images 90 degrees clockwise inside the current project."
        elif selected_count == 1:
            remove_tip = "Remove the selected image from the current project. File on disk is not deleted."
            rotate_left_tip = "Rotate the selected image 90 degrees counterclockwise inside the current project."
            rotate_right_tip = "Rotate the selected image 90 degrees clockwise inside the current project."
        elif has_current:
            remove_tip = "Remove the current image from the current project. File on disk is not deleted."
            rotate_left_tip = "Rotate the current image 90 degrees counterclockwise inside the current project."
            rotate_right_tip = "Rotate the current image 90 degrees clockwise inside the current project."
        else:
            remove_tip = "Remove selected images from the current project. Files on disk are not deleted."
            rotate_left_tip = "Rotate selected images 90 degrees counterclockwise inside the current project."
            rotate_right_tip = "Rotate selected images 90 degrees clockwise inside the current project."
        button.setToolTip(remove_tip)
        if isinstance(rotate_left_btn, QPushButton):
            rotate_left_btn.setToolTip(rotate_left_tip)
        if isinstance(rotate_right_btn, QPushButton):
            rotate_right_btn.setToolTip(rotate_right_tip)

    def _prune_series_order(self) -> None:
        remaining_uids = {item.uid for item in self.dataset_items}
        remaining_series = {
            self._ensure_series_name(name)
            for uid, name in self.series_by_uid.items()
            if uid in remaining_uids
        }
        ordered: list[str] = []
        for name in self.series_order:
            normalized = self._ensure_series_name(name)
            if normalized in remaining_series and normalized not in ordered:
                ordered.append(normalized)
        for name in sorted(remaining_series, key=self._natural_sort_key):
            if name not in ordered:
                ordered.append(name)
        self.series_order = ordered

