        self.foundation_last_details = None
        self.foundation_batch_rows = []
        self.foundation_batch_target_count = 0
        self.foundation_box_pick_mode = False
        self._foundation_stroke_segments = 0
        self._foundation_stroke_pixels = 0
        self._foundation_stroke_tool = "brush"
