    def _dataset_edit_targets(self) -> list[DatasetImageItem]:
        targets = self._selected_dataset_items()
        if targets:
            return targets
        current = self._current_dataset_item()
        return [current] if current is not None else []

    def _rotate_foundation_suggestion_payload(
        self,
        suggestion: dict[str, object] | None,
        shape_hw: tuple[int, int],
        turns: int,
    ) -> dict[str, object] | None:
        if not isinstance(suggestion, dict):
            return None
        rotated = dict(suggestion)
        if "x" in rotated and "y" in rotated:
            try:
                x_new, y_new = rotate_point_xy((int(rotated["x"]), int(rotated["y"])), shape_hw, turns)
                rotated["x"] = int(x_new)
                rotated["y"] = int(y_new)
            except Exception:
                pass
        return rotated

    def _rotate_foundation_interactions_payload(
        self,
        rows: list[dict[str, object]] | None,
        shape_hw: tuple[int, int],
        turns: int,
    ) -> list[dict[str, object]]:
        rotated_rows: list[dict[str, object]] = []
        for row in rows or []:
            if not isinstance(row, dict):
                continue
            rotated = dict(row)
            if "x" in rotated and "y" in rotated:
                try:
                    x_new, y_new = rotate_point_xy((int(rotated["x"]), int(rotated["y"])), shape_hw, turns)
                    rotated["x"] = int(x_new)
                    rotated["y"] = int(y_new)
                except Exception:
                    pass
            rotated_rows.append(rotated)
        return rotated_rows

    def _rotate_dataset_targets(self, turns: int, direction_label: str) -> None:
        if self._is_training_running():
            QMessageBox.warning(self, "Training in progress", "Stop the current training run before rotating images.")
            return
        if self._is_rf_batch_running():
            QMessageBox.warning(self, "RF batch in progress", "Wait for Random Forest batch to finish before rotating images.")
            return
        if self._is_foundation_batch_running():
            QMessageBox.warning(self, "Zero-shot batch in progress", "Wait for Zero-shot batch to finish before rotating images.")
            return

        targets = self._dataset_edit_targets()
        if not targets:
            QMessageBox.information(self, "No image selected", "Select one or more images in the left timeline first.")
            return

        turns = int(turns) % 4
        if turns == 0:
            return

        target_count = len(targets)
        noun = "image" if target_count == 1 else "images"
        answer = QMessageBox.question(
            self,
            f"Rotate {noun}",
            (
                f"Rotate {target_count} {noun} {direction_label} in the current project?\n\n"
                "Associated labels, predictions, pseudo-labels, and prompt layers will rotate with the images.\n"
                "Source image files on disk will not be modified."
            ),
            QMessageBox.Yes | QMessageBox.Cancel,
            QMessageBox.Yes,
        )
        if answer != QMessageBox.Yes:
            return

        self._clear_stroke_history()
        self._stop_label_replay(restore_origin=False)
        self._pause_timelapse_playback()
        self._pause_analytics_playback()

        progress: QProgressDialog | None = None
        if target_count >= 8:
            progress = QProgressDialog(f"Rotating {noun}...", "Cancel", 0, target_count, self)
            progress.setWindowModality(Qt.WindowModal)
            progress.setMinimumDuration(0)

        rotated_count = 0
        rotated_annotation_layers = 0
        rotated_prediction_masks = 0
        current_uid = self._current_item().uid if self._current_item() is not None else None

        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            for index, item in enumerate(targets, start=1):
                if progress is not None:
                    progress.setValue(index - 1)
                    progress.setLabelText(f"{index}/{target_count} · {item.name}")
                    QApplication.processEvents()
                    if progress.wasCanceled():
                        break

                shape_before = item.image.shape[:2]
                item.image = np.asarray(rotate_image_90(item.image, turns), dtype=np.uint8)
                uid = str(item.uid)

                per_image_layers = self.annotations.get(uid)
                if isinstance(per_image_layers, dict):
                    for class_id, layer in list(per_image_layers.items()):
                        per_image_layers[class_id] = np.asarray(rotate_image_90(layer, turns), dtype=np.uint8)
                        rotated_annotation_layers += 1

                pred = self.predictions.get(uid)
                if isinstance(pred, np.ndarray):
                    self.predictions[uid] = np.asarray(rotate_image_90(pred, turns), dtype=np.uint8)
                    rotated_prediction_masks += 1

                pseudo = self.hitl_pseudo_labels.get(uid)
                if isinstance(pseudo, np.ndarray):
                    self.hitl_pseudo_labels[uid] = np.asarray(rotate_image_90(pseudo, turns), dtype=np.uint8)

                rf_layers = self.rf_seed_layers.get(uid)
                if isinstance(rf_layers, dict):
                    for class_id, layer in list(rf_layers.items()):
                        rf_layers[class_id] = np.asarray(rotate_image_90(layer, turns), dtype=np.uint8)
                if uid in self.rf_roi_by_uid:
                    self.rf_roi_by_uid[uid] = rotate_rect_xywh(self.rf_roi_by_uid[uid], shape_before, turns)

                foundation_layers = self.foundation_prompt_layers.get(uid)
                if isinstance(foundation_layers, dict):
                    for class_id, layer in list(foundation_layers.items()):
                        foundation_layers[class_id] = np.asarray(rotate_image_90(layer, turns), dtype=np.uint8)
                if uid in self.foundation_box_by_uid:
                    self.foundation_box_by_uid[uid] = rotate_rect_xywh(self.foundation_box_by_uid[uid], shape_before, turns)
                if uid in self.foundation_suggestions:
                    self.foundation_suggestions[uid] = self._rotate_foundation_suggestion_payload(
                        self.foundation_suggestions.get(uid),
                        shape_before,
                        turns,
                    ) or {}
                if uid in self.foundation_interactions_by_uid:
                    self.foundation_interactions_by_uid[uid] = self._rotate_foundation_interactions_payload(
                        self.foundation_interactions_by_uid.get(uid),
                        shape_before,
                        turns,
                    )

                rotated_count += 1
        finally:
            if progress is not None:
                progress.setValue(rotated_count)
            QApplication.restoreOverrideCursor()

        if rotated_count <= 0:
            return

        if current_uid:
            self._set_current_item_by_uid(current_uid)
        self._mark_annotations_changed()
        self._mark_predictions_changed()
        self._invalidate_dataset_derived_state()
        self._refresh_dataset_widgets()
        self._refresh_all_views(force_all=True)
        self._set_dirty(True)
        QMessageBox.information(
            self,
            "Rotation complete",
            (
                f"Rotated {rotated_count} {noun} {direction_label}.\n"
                f"Annotation layers rotated: {rotated_annotation_layers}\n"
                f"Prediction masks rotated: {rotated_prediction_masks}\n\n"
                "The changes are stored in the project state; original image files on disk were not modified."
            ),
        )

    def _rotate_selected_images_left(self, _checked: bool = False) -> None:
        self._rotate_dataset_targets(1, "90 degrees left")

    def _rotate_selected_images_right(self, _checked: bool = False) -> None:
        self._rotate_dataset_targets(3, "90 degrees right")

    def _remove_selected_dataset_items(self, _checked: bool = False) -> None:
        if self._is_training_running():
            QMessageBox.warning(self, "Training in progress", "Stop the current training run before removing images.")
            return
        if self._is_rf_batch_running():
            QMessageBox.warning(
                self,
                "RF batch in progress",
                "Wait for Random Forest batch to finish before removing images.",
            )
            return
        if self._is_foundation_batch_running():
            QMessageBox.warning(
                self,
                "Zero-shot batch in progress",
                "Wait for Zero-shot batch to finish before removing images.",
            )
            return

        targets = self._selected_dataset_items()
        if not targets:
            current = self._current_dataset_item()
            if current is not None:
                targets = [current]
        if not targets:
            QMessageBox.information(self, "No image selected", "Select one or more images in the left timeline first.")
            return

        removed_uids = {item.uid for item in targets}
        removed_count = len(removed_uids)
        noun = "image" if removed_count == 1 else "images"
        answer = QMessageBox.question(
            self,
            "Remove images",
            f"Remove {removed_count} {noun} from the current project and timeline?\n\n"
            "Their labels, predictions, and per-image cached state will be removed from the project.\n"
            "Source image files on disk will not be deleted.",
            QMessageBox.Yes | QMessageBox.Cancel,
            QMessageBox.Cancel,
        )
        if answer != QMessageBox.Yes:
            return

        self._clear_stroke_history()
        self._stop_label_replay(restore_origin=False)
        self._pause_timelapse_playback()
        self._pause_analytics_playback()

        previous_items = list(self.dataset_items)
        removed_start_index = min(
            (idx for idx, item in enumerate(previous_items) if item.uid in removed_uids),
            default=0,
        )
        preserved_current_uid = None
        if 0 <= self.current_index < len(previous_items):
            preserved_current_uid = previous_items[self.current_index].uid
            if preserved_current_uid in removed_uids:
                preserved_current_uid = None

        self.dataset_items = [item for item in previous_items if item.uid not in removed_uids]
        for uid in removed_uids:
            self.series_by_uid.pop(uid, None)
            self.annotations.pop(uid, None)
            self.predictions.pop(uid, None)
            self.prediction_metadata_by_uid.pop(uid, None)
            self.image_identity_by_uid.pop(uid, None)
            self.hitl_pseudo_labels.pop(uid, None)
            self.hitl_review_state.pop(uid, None)
            self.rf_seed_layers.pop(uid, None)
            self.rf_roi_by_uid.pop(uid, None)
            self.rf_probability_by_uid.pop(uid, None)
            self.foundation_prompt_layers.pop(uid, None)
            self.foundation_box_by_uid.pop(uid, None)
            self.foundation_suggestions.pop(uid, None)
            self.foundation_interactions_by_uid.pop(uid, None)
            self.foundation_run_history_by_uid.pop(uid, None)
        self.root_decomposition_cache = {
            key: value for key, value in self.root_decomposition_cache.items() if key[0] not in removed_uids
        }
        self._annotation_revision += 1
        self._prediction_revision += 1
        self._prune_series_order()
        self._invalidate_dataset_derived_state()

        if self.dataset_items:
            if preserved_current_uid is not None:
                self.current_index = next(
                    (idx for idx, item in enumerate(self.dataset_items) if item.uid == preserved_current_uid),
                    0,
                )
            else:
                self.current_index = max(0, min(int(removed_start_index), len(self.dataset_items) - 1))
            self.timelapse_index = self.current_index
        else:
            self.current_index = -1
            self.timelapse_index = 0

        self._refresh_series_widgets()
        self._refresh_dataset_widgets()
        self._refresh_all_views()
        self._set_dirty(True)

    def _build_pyphenotyper_config_from_ui(self) -> PyPhenotyperConfig:
        pipeline_class_ids = self._ensure_segmentation_pipeline_classes(
            select_defaults=True,
            include_seed=self.pyphenotyper_preset_key == "mxlab_dark_rgb_builtin",
        )
        pipeline_dir = self.pyphenotyper_pipeline_dir
        root_model_path = self.pyphenotyper_root_model_path
        shoot_model_path = self.pyphenotyper_shoot_model_path
        seed_model_path = self.pyphenotyper_seed_model_path

        if pipeline_dir is None:
            text = self.pyphenotyper_pipeline_edit.text().strip()
            pipeline_dir = Path(text) if text else None
        if root_model_path is None:
            text = self.pyphenotyper_root_model_edit.text().strip()
            root_model_path = Path(text) if text else None
        if shoot_model_path is None:
            text = self.pyphenotyper_shoot_model_edit.text().strip()
            shoot_model_path = Path(text) if text else None
        lucifer_gan_gap_repair_dir = self._current_pyphenotyper_lucifer_gan_gap_repair_dir()

        if pipeline_dir is None:
            raise ValueError("Select the PyPhenotyper pipeline folder first.")
        if root_model_path is None:
            raise ValueError("Select the PyPhenotyper root model (.h5/.keras).")
        if shoot_model_path is None:
            # Single-model fallback: reuse root model for both branches when
            # shoot weights are not provided.
            shoot_model_path = root_model_path

        root_class_id = self.pyphenotyper_root_class_combo.currentData()
        shoot_class_id = self.pyphenotyper_shoot_class_combo.currentData()
        seed_class_id = self.pyphenotyper_seed_class_combo.currentData() if hasattr(self, "pyphenotyper_seed_class_combo") else 0
        if root_class_id is None or shoot_class_id is None:
            raise ValueError("Map root and shoot outputs to classes before running segmentation.")
        seed_class_id = int(seed_class_id) if seed_class_id not in (None, "") else 0
        if seed_class_id <= 0:
            seed_class_id = None

        pipeline_overrides: dict[str, object] | None = None
        grayscale_variant: PyPhenotyperVariantConfig | None = None
        rgb_variant: PyPhenotyperVariantConfig | None = None
        expert_variants: tuple[PyPhenotyperExpertConfig, ...] = ()
        router_mode = "legacy"
        calibration_profile = self.general_root_starter_calibration if isinstance(self.general_root_starter_calibration, dict) else None
        if self.pyphenotyper_preset_key in {
            "mxlab_dark_rgb_builtin",
            "hades_lucifer_builtin",
            "lucifer_builtin",
            "lucifer_inoculated_builtin",
            "hades_lucifer_auto_hybrid",
            "potato_builtin",
            "general_root_starter_auto",
        }:
            pipeline_overrides = {
                "shoot_postprocess_mode": "legacy",
                "adapter_shoot_guard_mode": "off",
            }
        if self.pyphenotyper_preset_key == "hades_lucifer_auto_hybrid":
            pipeline_overrides = {
                "shoot_postprocess_mode": "guarded",
                "adapter_shoot_guard_mode": "default",
                "ownership_backend": "bw_arabidopsis_seed_centers",
                "expected_plant_count": 5,
            }
        if self.pyphenotyper_preset_key == "hades_lucifer_builtin":
            pipeline_overrides = {
                "shoot_postprocess_mode": "bw_arabidopsis",
                "adapter_shoot_guard_mode": "default",
                "ownership_backend": "bw_arabidopsis_seed_centers",
                "expected_plant_count": 5,
                "shoot_color_rescue_model_locked": True,
                "shoot_color_rescue_eligibility": "model_locked",
            }
        if self.pyphenotyper_preset_key == "lucifer_builtin":
            pipeline_overrides = {
                "shoot_postprocess_mode": "bw_arabidopsis",
                "adapter_shoot_guard_mode": "off",
                "ownership_backend": "bw_arabidopsis_seed_centers",
                "expected_plant_count": 5,
                "shoot_color_rescue_mode": "lucifer_green",
                "shoot_color_rescue_eligible": True,
                "shoot_color_rescue_failure_policy": "retain_model",
            }
        if self.pyphenotyper_preset_key == "lucifer_inoculated_builtin":
            pipeline_overrides = {
                # "native" historically resolved to guarded in the bundled
                # compatibility layer. Name the executed mode explicitly so
                # run manifests and publications describe the same behavior.
                "shoot_postprocess_mode": "guarded",
                "adapter_shoot_guard_mode": "off",
                "ownership_backend": "bw_arabidopsis_seed_centers",
                "expected_plant_count": 5,
                "root_min_area": 1,
                "shoot_min_area": 1,
                "root_edge_margin_fraction": 0.0,
                "shoot_edge_margin_fraction": 0.0,
                "shoot_color_rescue_mode": "off",
            }
        if self.pyphenotyper_preset_key == "mxlab_dark_rgb_builtin":
            pipeline_overrides = {
                "shoot_postprocess_mode": "simple",
                "adapter_shoot_guard_mode": "off",
                "shoot_min_area": 1,
                "root_min_area": 8,
                "root_edge_margin_fraction": 0.0,
                "shoot_edge_margin_fraction": 0.0,
                "shoot_color_rescue_model_locked": True,
                "shoot_color_rescue_eligibility": "model_locked",
            }
        if self.pyphenotyper_preset_key == "potato_builtin":
            pipeline_overrides = {
                **(pipeline_overrides or {}),
                "shoot_color_rescue_model_locked": True,
                "shoot_color_rescue_eligibility": "model_locked",
            }
        if self.pyphenotyper_preset_key == "general_root_starter_auto":
            expert_variants = self._general_root_starter_builtin_experts()
            if not expert_variants:
                raise ValueError("The General Root Starter preset is missing bundled expert files.")
            pipeline_dir = expert_variants[0].pipeline_dir
            root_model_path = expert_variants[0].root_model_path
            shoot_model_path = expert_variants[0].shoot_model_path
            router_mode = "general_root_starter"
        elif self.pyphenotyper_preset_key == "mxlab_dark_rgb_builtin":
            builtin_pipeline_dir = self._detect_builtin_pyphenotyper_pipeline_dir()
            mxlab_root_model, mxlab_shoot_model, mxlab_seed_model = self._detect_builtin_mxlab_dark_rgb_mixed_model_paths()
            if builtin_pipeline_dir is None or mxlab_root_model is None or mxlab_shoot_model is None:
                raise ValueError("The dark-background RGB preset is missing bundled PyPhenotyper files.")
            pipeline_dir = builtin_pipeline_dir
            root_model_path = mxlab_root_model
            shoot_model_path = mxlab_shoot_model
            seed_model_path = mxlab_seed_model
            seed_class_id = int(seed_class_id) if seed_class_id is not None else None
        elif self.pyphenotyper_preset_key == "hades_lucifer_auto_hybrid":
            builtin_pipeline_dir = self._detect_builtin_pyphenotyper_pipeline_dir()
            gray_root_model, gray_shoot_model = self._detect_builtin_hades_lucifer_model_paths()
            rgb_root_model, rgb_shoot_model = self._detect_builtin_lucifer_model_paths()
            if (
                builtin_pipeline_dir is None
                or gray_root_model is None
                or gray_shoot_model is None
                or rgb_root_model is None
                or rgb_shoot_model is None
            ):
                raise ValueError("The auto hybrid preset is missing bundled PyPhenotyper files.")
            pipeline_dir = builtin_pipeline_dir
            root_model_path = gray_root_model
            shoot_model_path = gray_shoot_model
            grayscale_variant = PyPhenotyperVariantConfig(
                pipeline_dir=builtin_pipeline_dir,
                root_model_path=gray_root_model,
                shoot_model_path=gray_shoot_model,
                pipeline_overrides={
                    **pipeline_overrides,
                    "shoot_color_rescue_model_locked": True,
                    "shoot_color_rescue_eligibility": "model_locked",
                },
                label="grayscale_hades",
                pixel_size_mm=float(HADES_PIXEL_SIZE_MM),
            )
            rgb_variant = PyPhenotyperVariantConfig(
                pipeline_dir=builtin_pipeline_dir,
                root_model_path=rgb_root_model,
                shoot_model_path=rgb_shoot_model,
                pipeline_overrides={
                    **pipeline_overrides,
                    "shoot_color_rescue_mode": "lucifer_green",
                    "shoot_color_rescue_eligible": True,
                    "shoot_color_rescue_failure_policy": "retain_model",
                },
                label="lucifer_rgb",
                pixel_size_mm=float(LUCIFER_PIXEL_SIZE_MM),
            )
        elif self.pyphenotyper_preset_key == "lucifer_builtin":
            builtin_pipeline_dir = self._detect_builtin_pyphenotyper_pipeline_dir()
            lucifer_root_model, lucifer_shoot_model = self._detect_builtin_lucifer_model_paths()
            if builtin_pipeline_dir is None or lucifer_root_model is None or lucifer_shoot_model is None:
                raise ValueError("The Lucifer RGB Arabidopsis preset is missing bundled PyPhenotyper files.")
            pipeline_dir = builtin_pipeline_dir
            root_model_path = lucifer_root_model
            shoot_model_path = lucifer_shoot_model
        elif self.pyphenotyper_preset_key == "lucifer_inoculated_builtin":
            builtin_pipeline_dir = self._detect_builtin_pyphenotyper_pipeline_dir()
            lucifer_root_model, _lucifer_shoot_model = self._detect_builtin_lucifer_model_paths()
            inoculated_shoot_model = self._detect_builtin_rgb_inoculated_model_path()
            if builtin_pipeline_dir is None or lucifer_root_model is None or inoculated_shoot_model is None:
                raise ValueError("The validated Lucifer RGB inoculated preset is missing bundled files.")
            pipeline_dir = builtin_pipeline_dir
            root_model_path = lucifer_root_model
            shoot_model_path = inoculated_shoot_model
            seed_model_path = None
            seed_class_id = None
        elif self.pyphenotyper_preset_key == "potato_builtin":
            builtin_pipeline_dir = self._detect_builtin_pyphenotyper_pipeline_dir()
            potato_root_model, potato_shoot_model = self._detect_builtin_potato_model_paths()
            if builtin_pipeline_dir is None or potato_root_model is None or potato_shoot_model is None:
                raise ValueError("The Potato preset is missing bundled PyPhenotyper files.")
            pipeline_dir = builtin_pipeline_dir
            root_model_path = potato_root_model
            shoot_model_path = potato_shoot_model

        fixed_patch_size = self._preset_fixed_patch_size(self.pyphenotyper_preset_key)
        effective_patch_size = int(fixed_patch_size) if fixed_patch_size is not None else int(self.pyphenotyper_patch_size_spin.value())
        if fixed_patch_size is not None and hasattr(self, "pyphenotyper_patch_size_spin"):
            current_patch_value = int(self.pyphenotyper_patch_size_spin.value())
            if current_patch_value != int(fixed_patch_size):
                self.pyphenotyper_patch_size_spin.blockSignals(True)
                self.pyphenotyper_patch_size_spin.setValue(int(fixed_patch_size))
                self.pyphenotyper_patch_size_spin.blockSignals(False)
                self.statusBar().showMessage(
                    f"{self.pyphenotyper_preset_combo.currentText()} uses fixed {int(fixed_patch_size)} px tiles; saved patch size {current_patch_value} was ignored.",
                    7000,
                )

        if bool(
            self.pyphenotyper_preserve_root_overlap_cb.isChecked()
            if hasattr(self, "pyphenotyper_preserve_root_overlap_cb")
            else self.pyphenotyper_preserve_root_on_shoot_overlap
        ):
            pipeline_overrides = dict(pipeline_overrides or {})
            pipeline_overrides["shoot_priority_over_root"] = False

        shoot_color_rescue_mode = self._current_pyphenotyper_shoot_color_rescue_mode()

        def _apply_shoot_color_rescue_mode(overrides: dict[str, object] | None) -> dict[str, object] | None:
            if shoot_color_rescue_mode == "auto":
                return overrides
            updated = dict(overrides or {})
            if (
                shoot_color_rescue_mode == "lucifer_green"
                and bool(updated.get("shoot_color_rescue_model_locked", False))
            ):
                return updated
            updated["shoot_color_rescue_mode"] = "lucifer_green" if shoot_color_rescue_mode == "lucifer_green" else "off"
            return updated

        pipeline_overrides = _apply_shoot_color_rescue_mode(pipeline_overrides)
        if grayscale_variant is not None:
            grayscale_variant.pipeline_overrides = _apply_shoot_color_rescue_mode(grayscale_variant.pipeline_overrides)
        if rgb_variant is not None:
            rgb_variant.pipeline_overrides = _apply_shoot_color_rescue_mode(rgb_variant.pipeline_overrides)
        for expert in expert_variants:
            expert.pipeline_overrides = _apply_shoot_color_rescue_mode(expert.pipeline_overrides)

        config = PyPhenotyperConfig(
            pipeline_dir=Path(pipeline_dir).expanduser(),
            root_model_path=Path(root_model_path).expanduser(),
            shoot_model_path=Path(shoot_model_path).expanduser(),
            seed_model_path=Path(seed_model_path).expanduser() if seed_model_path is not None else None,
            patch_size=int(effective_patch_size),
            refinement_steps=int(self.pyphenotyper_refinement_steps_spin.value()),
            root_class_id=int(root_class_id),
            shoot_class_id=int(shoot_class_id),
            lateral_class_id=int(pipeline_class_ids["lateral"]),
            seed_class_id=int(seed_class_id) if seed_class_id is not None else None,
            include_occlusion=(
                False
                if self.pyphenotyper_preset_key == "lucifer_inoculated_builtin"
                else bool(self.pyphenotyper_include_occlusion_cb.isChecked())
            ),
            enable_bbox_tracking=bool(self.pyphenotyper_enable_bbox_tracking_cb.isChecked()),
            min_component_area=int(self.pyphenotyper_min_component_area_spin.value()),
            bbox_padding=int(self.pyphenotyper_bbox_padding_spin.value()),
            tracking_search_margin=int(self.pyphenotyper_tracking_margin_spin.value()),
            pixel_size_mm=float(self.pyphenotyper_pixel_size_mm_spin.value()),
            profile_overrides=None,
            pipeline_overrides=pipeline_overrides,
            root_profile_overrides=(
                {
                    "name": "mxlab_dark_rgb_root_original",
                    "mode": "binary_pair",
                    "input_mode": "rgb",
                    "flip_horizontal": False,
                    "return_original_coords": True,
                    "root_threshold": 0.5,
                    "shoot_threshold": 0.5,
                    "batch_size": 12,
                    "predictor_kind": "mxlab_legacy_patch256",
                    "predictor_patch_size": 256,
                }
                if self.pyphenotyper_preset_key == "mxlab_dark_rgb_builtin"
                else None
            ),
            shoot_profile_overrides=(
                {
                    "name": "rgb_inoculated_shoot_v3",
                    "mode": "multiclass",
                    "input_mode": "rgb",
                    "flip_horizontal": False,
                    "return_original_coords": True,
                    "root_label_ids": (3,),
                    "lateral_label_ids": (),
                    "shoot_label_ids": (2,),
                    "seed_label_ids": (1,),
                    "include_seed_in_shoot": False,
                    "batch_size": 8,
                    "tile_halo": 32,
                    "class_probability_scales": (1.0, 1.0, 1.0, 1.0),
                }
                if self.pyphenotyper_preset_key == "lucifer_inoculated_builtin"
                else {
                    "name": "mxlab_dark_rgb_multiclass",
                    "mode": "multiclass",
                    "input_mode": "rgb",
                    "flip_horizontal": False,
                    "root_label_ids": (3,),
                    "shoot_label_ids": (2,),
                    "seed_label_ids": (1,),
                    "include_seed_in_shoot": False,
                }
                if self.pyphenotyper_preset_key == "mxlab_dark_rgb_builtin"
                else None
            ),
            seed_profile_overrides=(
                {
                    "name": "mxlab_dark_rgb_seed_original",
                    "mode": "binary_pair",
                    "input_mode": "rgb",
                    "flip_horizontal": False,
                    "return_original_coords": True,
                    "root_threshold": 0.5,
                    "shoot_threshold": 0.5,
                    "batch_size": 12,
                    "predictor_kind": "mxlab_legacy_patch256",
                    "predictor_patch_size": 256,
                }
                if self.pyphenotyper_preset_key == "mxlab_dark_rgb_builtin" and seed_model_path is not None
                else None
            ),
            grayscale_variant=grayscale_variant,
            rgb_variant=rgb_variant,
            expert_variants=expert_variants,
            router_mode=router_mode,
            calibration_profile=calibration_profile,
            lucifer_gan_gap_repair_enabled=(
                bool(self.pyphenotyper_lucifer_gan_gap_repair_cb.isChecked())
                if hasattr(self, "pyphenotyper_lucifer_gan_gap_repair_cb")
                else False
            ),
            lucifer_gan_gap_repair_dir=(
                Path(lucifer_gan_gap_repair_dir).expanduser()
                if lucifer_gan_gap_repair_dir is not None
                else None
            ),
        )
        validate_pyphenotyper_setup(config)
        self.pyphenotyper_pipeline_dir = config.pipeline_dir
        self.pyphenotyper_root_model_path = config.root_model_path
        self.pyphenotyper_shoot_model_path = config.shoot_model_path
        self.pyphenotyper_seed_model_path = config.seed_model_path
        self.pyphenotyper_lucifer_gan_gap_repair_dir = config.lucifer_gan_gap_repair_dir
        self.pyphenotyper_preserve_root_on_shoot_overlap = bool(
            self.pyphenotyper_preserve_root_overlap_cb.isChecked()
            if hasattr(self, "pyphenotyper_preserve_root_overlap_cb")
            else self.pyphenotyper_preserve_root_on_shoot_overlap
        )
        self.pyphenotyper_shoot_color_rescue_mode = shoot_color_rescue_mode
        self.pyphenotyper_pipeline_edit.setText(str(config.pipeline_dir))
        if self.pyphenotyper_preset_key == "general_root_starter_auto" and config.expert_variants:
            self.pyphenotyper_root_model_edit.setText(
                " | ".join(f"{expert.label}: {expert.root_model_path.name}" for expert in config.expert_variants)
            )
            self.pyphenotyper_shoot_model_edit.setText(
                " | ".join(f"{expert.label}: {expert.shoot_model_path.name}" for expert in config.expert_variants)
            )
        elif self.pyphenotyper_preset_key == "hades_lucifer_auto_hybrid" and config.rgb_variant is not None:
            self.pyphenotyper_root_model_edit.setText(
                f"BW: {config.root_model_path.name} | RGB: {config.rgb_variant.root_model_path.name}"
            )
            self.pyphenotyper_shoot_model_edit.setText(
                f"BW: {config.shoot_model_path.name} | RGB: {config.rgb_variant.shoot_model_path.name}"
            )
        elif self.pyphenotyper_preset_key == "mxlab_dark_rgb_builtin" and config.seed_model_path is not None:
            self.pyphenotyper_root_model_edit.setText(str(config.root_model_path))
            self.pyphenotyper_shoot_model_edit.setText(
                f"{config.shoot_model_path.name} | seed: {config.seed_model_path.name}"
            )
        else:
            self.pyphenotyper_root_model_edit.setText(str(config.root_model_path))
            self.pyphenotyper_shoot_model_edit.setText(str(config.shoot_model_path))
        if hasattr(self, "pyphenotyper_lucifer_gan_gap_repair_edit"):
            self.pyphenotyper_lucifer_gan_gap_repair_edit.setText(
                str(config.lucifer_gan_gap_repair_dir) if config.lucifer_gan_gap_repair_dir is not None else ""
            )
        if hasattr(self, "pyphenotyper_lucifer_gan_gap_repair_cb"):
            self.pyphenotyper_lucifer_gan_gap_repair_cb.blockSignals(True)
            self.pyphenotyper_lucifer_gan_gap_repair_cb.setChecked(bool(config.lucifer_gan_gap_repair_enabled))
            self.pyphenotyper_lucifer_gan_gap_repair_cb.blockSignals(False)
        return config

    def _is_training_running(self) -> bool:
        return bool(self.training_thread is not None and self.training_thread.isRunning())

    def _is_rf_batch_running(self) -> bool:
        return bool(self.rf_batch_thread is not None and self.rf_batch_thread.isRunning())

    def _is_foundation_batch_running(self) -> bool:
        return bool(self.foundation_batch_thread is not None and self.foundation_batch_thread.isRunning())

    def _append_training_log(self, message: str) -> None:
        text = str(message).strip()
        if not text:
            return
        self.training_log.append(text)

    def _refresh_training_backend(self, _checked: bool = False) -> None:
        if getattr(self, "_initializing_training_ui", False) and bool(getattr(sys, "frozen", False)):
            self.training_backend_label.setText(
                "Backend check deferred on app startup. Click Refresh Backend when needed."
            )
            return
        framework = self._current_training_framework()
        external = self._effective_external_runtime_python_path(framework, strict=False)
        manual = self._resolved_external_tf_python_path(strict=False)
        info = detect_training_backends(external_python=external, framework=framework)
        runtime_name = "PyTorch" if framework == "pytorch" else "TensorFlow"
        if not bool(info.get("available", False)):
            if external is not None:
                self.training_backend_label.setText(
                    f"External backend unavailable: {info.get('error', f'{runtime_name} not found')} (fallback: bundled CPU/GPU)"
                )
            else:
                self.training_backend_label.setText(f"Backend unavailable: {info.get('error', f'{runtime_name} not found')}")
            return
        gpu_count = int(info.get("gpu_count", 0))
        version = str(info.get("version", "unknown"))
        runtime_kind = str(info.get("runtime_kind", "bundled"))
        runtime_label = "external" if runtime_kind == "external" else "bundled"
        auto_txt = ""
        if manual is None and external is not None and runtime_kind == "external":
            auto_txt = f" · auto: {external.name}"
        if gpu_count > 0:
            names = info.get("gpu_names", [])
            names_txt = ", ".join(str(n) for n in names[:2]) if names else "GPU detected"
            extra = "" if len(names) <= 2 else f" (+{len(names) - 2} more)"
            self.training_backend_label.setText(
                f"{runtime_name} {version} ({runtime_label}) · GPU x{gpu_count}: {names_txt}{extra}{auto_txt}"
            )
        else:
            self.training_backend_label.setText(
                f"{runtime_name} {version} ({runtime_label}) · CPU only (no GPU detected){auto_txt}"
            )

    def _on_training_finetune_toggled(self, _state: int = 0) -> None:
        enabled = self.training_finetune_enabled_cb.isChecked()
        self.training_finetune_path_edit.setEnabled(enabled)
        self.training_finetune_browse_btn.setEnabled(enabled)
        self.training_finetune_clear_btn.setEnabled(enabled)
        self.training_freeze_fraction_spin.setEnabled(enabled)
        if not enabled:
            self.training_freeze_fraction_spin.setValue(0.0)

    def _on_training_augmentation_toggled(self, _state: int = 0) -> None:
        enabled = self.training_aug_enable_cb.isChecked()
        self.training_aug_replicas_spin.setEnabled(enabled)
        self.training_aug_hflip_prob_spin.setEnabled(enabled)
        self.training_aug_vflip_prob_spin.setEnabled(enabled)
        self.training_aug_rotate90_prob_spin.setEnabled(enabled)
        self.training_aug_brightness_delta_spin.setEnabled(enabled)
        self.training_aug_contrast_range_spin.setEnabled(enabled)
        self.training_aug_noise_std_spin.setEnabled(enabled)
        self.training_aug_gamma_range_spin.setEnabled(enabled)
        self.training_aug_blur_prob_spin.setEnabled(enabled)

    def _current_training_framework(self) -> str:
        if not hasattr(self, "training_framework_combo"):
            return "tensorflow"
        data = self.training_framework_combo.currentData()
        framework = str(data) if data is not None else "tensorflow"
        return framework if framework in {"tensorflow", "pytorch"} else "tensorflow"

    def _recommended_training_output_path(self, framework: str | None = None) -> Path:
        normalized = str(framework or self._current_training_framework()).strip().lower()
        suffix = ".pt" if normalized == "pytorch" else ".keras"
        return Path.home() / f"npec_trained_model{suffix}"

    def _on_training_framework_changed(self, _index: int = 0) -> None:
        framework = self._current_training_framework()
        is_tf = framework == "tensorflow"
        if hasattr(self, "training_finetune_enabled_cb"):
            if not is_tf:
                self.training_finetune_enabled_cb.setChecked(False)
            self.training_finetune_enabled_cb.setEnabled(is_tf)
        if hasattr(self, "training_export_tflite_cb"):
            if not is_tf:
                self.training_export_tflite_cb.setChecked(False)
            self.training_export_tflite_cb.setEnabled(is_tf)
        if hasattr(self, "training_export_hef_cb"):
            if not is_tf:
                self.training_export_hef_cb.setChecked(False)
            self.training_export_hef_cb.setEnabled(is_tf)
        if hasattr(self, "training_hef_output_path_edit"):
            self.training_hef_output_path_edit.setEnabled(is_tf and self.training_export_hef_cb.isChecked())
        if hasattr(self, "training_hef_output_browse_btn"):
            self.training_hef_output_browse_btn.setEnabled(is_tf and self.training_export_hef_cb.isChecked())
        if hasattr(self, "training_hailo_compile_cmd_edit"):
            self.training_hailo_compile_cmd_edit.setEnabled(is_tf and self.training_export_hef_cb.isChecked())
        if hasattr(self, "training_external_tf_python_edit"):
            if is_tf:
                self.training_external_tf_python_edit.setPlaceholderText(
                    "Optional path to python with TensorFlow GPU support"
                )
            else:
                self.training_external_tf_python_edit.setPlaceholderText(
                    "Optional path to python with PyTorch CUDA / Metal (MPS) support"
                )
        if hasattr(self, "training_output_path_edit"):
            current_text = self.training_output_path_edit.text().strip()
            if not current_text:
                self.training_output_path_edit.setText(str(self._recommended_training_output_path(framework)))
            else:
                current_path = Path(current_text).expanduser()
                valid_suffixes = {".keras", ".h5"} if is_tf else {".pt", ".pth"}
                if current_path.suffix.lower() not in valid_suffixes:
                    self.training_output_path_edit.setText(str(self._recommended_training_output_path(framework)))
        self._refresh_training_backend()
        self._set_dirty(True)

    def _on_training_export_hef_toggled(self, _state: int = 0) -> None:
        enabled = self.training_export_hef_cb.isChecked() and self._current_training_framework() == "tensorflow"
        self.training_hef_output_path_edit.setEnabled(enabled)
        self.training_hef_output_browse_btn.setEnabled(enabled)
        self.training_hailo_compile_cmd_edit.setEnabled(enabled)
        if enabled:
            self.training_export_tflite_cb.setChecked(True)

    def _browse_training_output(self, _checked: bool = False) -> None:
        framework = self._current_training_framework()
        previous_output_text = self.training_output_path_edit.text().strip()
        previous_output_path = Path(previous_output_text).expanduser() if previous_output_text else None
        default_name = self.training_output_path_edit.text().strip() or str(self._recommended_training_output_path(framework))
        file_filter = "Keras Model (*.keras *.h5)" if framework == "tensorflow" else "PyTorch Checkpoint (*.pt *.pth)"
        save_path, _ = QFileDialog.getSaveFileName(
            self,
            "Select output model path",
            default_name,
            file_filter,
        )
        if not save_path:
            return
        path = Path(save_path)
        if framework == "tensorflow":
            if path.suffix.lower() not in {".keras", ".h5"}:
                path = path.with_suffix(".keras")
        else:
            if path.suffix.lower() not in {".pt", ".pth"}:
                path = path.with_suffix(".pt")
        self.training_output_path_edit.setText(str(path))
        if hasattr(self, "training_hef_output_path_edit"):
            current_hef = self.training_hef_output_path_edit.text().strip()
            can_autosync = not current_hef
            if not can_autosync and previous_output_path is not None:
                can_autosync = (Path(current_hef).expanduser() == previous_output_path.with_suffix(".hef"))
            if can_autosync:
                self.training_hef_output_path_edit.setText(str(path.with_suffix(".hef")))

    def _browse_training_hef_output(self, _checked: bool = False) -> None:
        save_path, _ = QFileDialog.getSaveFileName(
            self,
            "Select output HEF path",
            self.training_hef_output_path_edit.text().strip() or "npec_trained_model.hef",
            "HEF (*.hef);;All files (*)",
        )
        if not save_path:
            return
        path = Path(save_path)
        if path.suffix.lower() != ".hef":
            path = path.with_suffix(".hef")
        self.training_hef_output_path_edit.setText(str(path))

    def _browse_training_finetune_model(self, _checked: bool = False) -> None:
        open_path, _ = QFileDialog.getOpenFileName(
            self,
            "Select base model for fine-tuning",
            "",
            "Keras Models (*.keras *.h5)",
        )
        if not open_path:
            return
        self.training_finetune_model_path = Path(open_path)
        self.training_finetune_path_edit.setText(str(self.training_finetune_model_path))

    def _clear_training_finetune_model(self, _checked: bool = False) -> None:
        self.training_finetune_model_path = None
        self.training_finetune_path_edit.clear()

    def _snapshot_training_data(
        self,
    ) -> tuple[list[DatasetImageItem], dict[str, dict[int, np.ndarray]], list[LabelClass]]:
        dataset_copy = [
            DatasetImageItem(uid=item.uid, name=item.name, path=item.path, image=item.image.copy())
            for item in self.dataset_items
        ]
        annotations_copy: dict[str, dict[int, np.ndarray]] = {}
        for uid, per_class in self.annotations.items():
            annotations_copy[uid] = {int(class_id): mask.copy() for class_id, mask in per_class.items()}
        classes_copy = [LabelClass(class_id=cls.class_id, name=cls.name, color_hex=cls.color_hex) for cls in self.classes]
        return dataset_copy, annotations_copy, classes_copy

    def _build_training_config_from_ui(self) -> TrainingConfig:
        framework = self._current_training_framework()
        output_txt = self.training_output_path_edit.text().strip()
        if not output_txt:
            raise ValueError("Please define an output model path.")
        output_path = Path(output_txt).expanduser()
        if framework == "tensorflow":
            if output_path.suffix.lower() not in {".keras", ".h5"}:
                output_path = output_path.with_suffix(".keras")
        else:
            if output_path.suffix.lower() not in {".pt", ".pth"}:
                output_path = output_path.with_suffix(".pt")

        fine_tune_path: Path | None = None
        if self.training_finetune_enabled_cb.isChecked():
            if self.training_finetune_model_path is None:
                raise ValueError("Fine-tune is enabled, but no base model was selected.")
            fine_tune_path = self.training_finetune_model_path
            if framework != "tensorflow":
                raise ValueError("Fine-tuning from an existing checkpoint is only supported for TensorFlow right now.")
            if fine_tune_path.suffix.lower() not in {".keras", ".h5"}:
                raise ValueError("Fine-tune model must be a .keras or .h5 file.")

        external_tf_python = self._effective_external_runtime_python_path(framework, strict=False)
        export_hef = (
            bool(self.training_export_hef_cb.isChecked()) if hasattr(self, "training_export_hef_cb") else False
        ) and framework == "tensorflow"
        hef_output_path: Path | None = None
        hailo_compile_cmd = ""
        if export_hef:
            hef_txt = self.training_hef_output_path_edit.text().strip() if hasattr(self, "training_hef_output_path_edit") else ""
            hef_output_path = Path(hef_txt).expanduser() if hef_txt else output_path.with_suffix(".hef")
            if hef_output_path.suffix.lower() != ".hef":
                hef_output_path = hef_output_path.with_suffix(".hef")
            hailo_compile_cmd = (
                self.training_hailo_compile_cmd_edit.text().strip()
                if hasattr(self, "training_hailo_compile_cmd_edit")
                else ""
            )

        return TrainingConfig(
            framework=framework,
            patch_size=int(self.training_patch_size_spin.value()),
            patch_stride=int(self.training_patch_stride_spin.value()),
            batch_size=int(self.training_batch_size_spin.value()),
            epochs=int(self.training_epochs_spin.value()),
            learning_rate=float(self.training_lr_spin.value()),
            val_split=float(self.training_val_split_spin.value()),
            max_patches_per_image=int(self.training_max_patches_spin.value()),
            min_labeled_ratio=float(self.training_min_labeled_ratio_spin.value()),
            base_filters=int(self.training_base_filters_spin.value()),
            dropout=float(self.training_dropout_spin.value()),
            device_mode=str(self.training_device_combo.currentData()),
            output_path=output_path,
            fine_tune_path=fine_tune_path,
            freeze_fraction=float(self.training_freeze_fraction_spin.value()),
            export_tflite=bool((self.training_export_tflite_cb.isChecked() or export_hef) and framework == "tensorflow"),
            export_hef=bool(export_hef),
            hef_output_path=hef_output_path,
            hailo_compile_command=hailo_compile_cmd,
            augment_enabled=bool(self.training_aug_enable_cb.isChecked()),
            augment_replicas=int(self.training_aug_replicas_spin.value()),
            aug_hflip_prob=float(self.training_aug_hflip_prob_spin.value()),
            aug_vflip_prob=float(self.training_aug_vflip_prob_spin.value()),
            aug_rotate90_prob=float(self.training_aug_rotate90_prob_spin.value()),
            aug_brightness_delta=float(self.training_aug_brightness_delta_spin.value()),
            aug_contrast_range=float(self.training_aug_contrast_range_spin.value()),
            aug_noise_std=float(self.training_aug_noise_std_spin.value()),
            aug_gamma_range=float(self.training_aug_gamma_range_spin.value()),
            aug_blur_prob=float(self.training_aug_blur_prob_spin.value()),
            external_python_path=external_tf_python,
            external_fallback_cpu=True,
        )

    def _start_training_with_snapshot(
        self,
        dataset_copy: list[DatasetImageItem],
        annotations_copy: dict[str, dict[int, np.ndarray]],
        classes_copy: list[LabelClass],
        config: TrainingConfig,
        *,
        summary_text: str = "Training is running...",
        startup_log: str | None = None,
    ) -> bool:
        if self.training_thread is not None:
            QMessageBox.warning(self, "Training in progress", "A training run is already active.")
            return False
        if not dataset_copy:
            QMessageBox.warning(self, "No dataset", "Load images and labels before training.")
            return False

        self.training_log.clear()
        self.training_progress.setValue(0)
        self.training_progress_label.setText("Starting...")
        self.training_summary.setText(summary_text)
        self.training_start_btn.setEnabled(False)
        self.training_stop_btn.setEnabled(True)
        self.training_params_widget.setEnabled(False)
        framework = str(config.framework or "tensorflow").strip().lower()
        if config.external_python_path is not None:
            self._append_training_log(
                f"Runtime preference: external {'PyTorch' if framework == 'pytorch' else 'TensorFlow'} "
                f"({config.external_python_path}) with CPU fallback enabled."
            )
        else:
            self._append_training_log(
                f"Runtime preference: bundled {'PyTorch' if framework == 'pytorch' else 'TensorFlow'}."
            )
        if bool(config.export_hef):
            self._append_training_log(
                "HEF export enabled: training will export TFLite then run Hailo compile command "
                f"to generate {config.hef_output_path if config.hef_output_path is not None else '<auto>.hef'}."
            )
        if startup_log:
            self._append_training_log(startup_log)

        self.training_thread = QThread(self)
        self.training_worker = TrainingWorker(dataset_copy, annotations_copy, classes_copy, config)
        self.training_worker.moveToThread(self.training_thread)

        self.training_thread.started.connect(self.training_worker.run)
        self.training_worker.log.connect(self._append_training_log)
        self.training_worker.progress.connect(self._on_training_progress)
        self.training_worker.epoch_finished.connect(self._on_training_epoch_finished)
        self.training_worker.finished.connect(self._on_training_finished)
        self.training_worker.failed.connect(self._on_training_failed)
        self.training_worker.finished.connect(self.training_thread.quit)
        self.training_worker.failed.connect(self.training_thread.quit)
        self.training_thread.finished.connect(self._on_training_thread_finished)
        self.training_thread.finished.connect(self.training_worker.deleteLater)
        self.training_thread.finished.connect(self.training_thread.deleteLater)

        self.training_thread.start()
        self._append_training_log("Training worker started.")
        return True

    def _start_training(self, _checked: bool = False) -> None:
        try:
            config = self._build_training_config_from_ui()
        except Exception as exc:
            QMessageBox.warning(self, "Invalid training config", str(exc))
            return

        dataset_copy, annotations_copy, classes_copy = self._snapshot_training_data()
        self._start_training_with_snapshot(
            dataset_copy,
            annotations_copy,
            classes_copy,
            config,
            summary_text="Training is running...",
        )

    def _cancel_training(self, _checked: bool = False) -> None:
        if not self._is_training_running() or self.training_worker is None:
            return
        self.training_worker.cancel()

    def _on_training_progress(self, epoch: int, total_epochs: int) -> None:
        total_epochs = max(1, int(total_epochs))
        progress = int(round((int(epoch) / total_epochs) * 100.0))
        self.training_progress.setValue(max(0, min(100, progress)))
        self.training_progress_label.setText(f"Epoch {int(epoch)}/{total_epochs}")

    def _on_training_epoch_finished(self, payload: object) -> None:
        if not isinstance(payload, dict):
            return
        epoch = int(payload.get("epoch", 0))
        total_epochs = int(payload.get("total_epochs", max(1, self.training_epochs_spin.value())))
        loss = payload.get("loss")
        val_loss = payload.get("val_loss")
        acc = payload.get("acc")
        val_acc = payload.get("val_acc")
        if loss is None:
            return
        line = f"Epoch {epoch}/{total_epochs} loss={float(loss):.4f}"
        if val_loss is not None:
            line += f" val_loss={float(val_loss):.4f}"
        if acc is not None:
            line += f" acc={float(acc):.4f}"
        if val_acc is not None:
            line += f" val_acc={float(val_acc):.4f}"
        self._append_training_log(line)

    def _on_training_finished(self, summary: object) -> None:
        if not isinstance(summary, dict):
            summary = {}
        cancelled = bool(summary.get("cancelled", False))
        stats = summary.get("stats", {}) if isinstance(summary.get("stats"), dict) else {}
        out_model = summary.get("output_model")
        out_tflite = summary.get("output_tflite")
        out_hef = summary.get("output_hef")
        hist = summary.get("history_final", {}) if isinstance(summary.get("history_final"), dict) else {}
        runtime = str(summary.get("runtime", "")).strip()
        runtime_python = str(summary.get("runtime_python", "")).strip()

        if out_model:
            self.training_last_output_model = Path(str(out_model))
            self.training_output_path_edit.setText(str(self.training_last_output_model))
            if self.training_last_output_model.suffix.lower() in {".keras", ".h5", ".tflite", ".hef", ".pt", ".pth"}:
                try:
                    self._set_model(self.training_last_output_model)
                except Exception as exc:
                    self._append_training_log(f"Auto-load trained model failed: {exc}")
            else:
                self._append_training_log(
                    f"Auto-load skipped for {self.training_last_output_model.suffix} training artifact."
                )
            if (
                self.hitl_long_session_state is not None
                and bool(self.hitl_long_session_state.get("switch_to_trained_standard_model", False))
                and self.training_last_output_model.suffix.lower() in {".keras", ".h5", ".tflite", ".pt", ".pth"}
                and hasattr(self, "inference_backend_combo")
            ):
                standard_idx = self.inference_backend_combo.findData("standard")
                if standard_idx >= 0:
                    self.inference_backend_combo.setCurrentIndex(standard_idx)
                self.hitl_long_session_state["template_preset_key"] = "current"
                self.hitl_session_template_preset_key = "current"
                if hasattr(self, "hitl_template_preset_combo"):
                    hitl_idx = self.hitl_template_preset_combo.findData("current")
                    if hitl_idx >= 0:
                        self.hitl_template_preset_combo.blockSignals(True)
                        self.hitl_template_preset_combo.setCurrentIndex(hitl_idx)
                        self.hitl_template_preset_combo.blockSignals(False)

        status_text = "Training cancelled." if cancelled else "Training completed."
        patches = int(stats.get("num_patches", 0))
        augmented_patches = int(stats.get("augmented_patches", 0))
        train_patches_final = int(stats.get("train_patches_final", 0))
        images = int(stats.get("num_images", 0))
        metric_text = ", ".join(f"{k}={v:.4f}" for k, v in hist.items() if isinstance(v, float))
        lines = [status_text, f"Images: {images}, patches: {patches}"]
        if train_patches_final > 0 or augmented_patches > 0:
            lines.append(f"Train patches after augmentation: {train_patches_final} (+{augmented_patches})")
        if out_model:
            lines.append(f"Model: {out_model}")
        if out_tflite:
            lines.append(f"TFLite: {out_tflite}")
        if out_hef:
            self.training_last_output_hef = Path(str(out_hef))
            lines.append(f"HEF: {out_hef}")
        else:
            self.training_last_output_hef = None
        if runtime:
            runtime_txt = runtime
            if runtime_python:
                runtime_txt += f" ({runtime_python})"
            lines.append(f"Runtime: {runtime_txt}")
        tflite_error = summary.get("tflite_error")
        if tflite_error:
            lines.append(f"TFLite export error: {tflite_error}")
        hef_error = summary.get("hef_error")
        if hef_error:
            lines.append(f"HEF export error: {hef_error}")
        if metric_text:
            lines.append(f"Final metrics: {metric_text}")
        self.training_summary.setText(" | ".join(lines))
        self.training_progress_label.setText("Done" if not cancelled else "Cancelled")
        self.training_progress.setValue(100 if not cancelled else self.training_progress.value())
        self._append_training_log(self.training_summary.text())
        if cancelled:
            self.hitl_long_session_state = None

    def _on_training_failed(self, details: str) -> None:
        self.training_progress_label.setText("Failed")
        self.training_summary.setText("Training failed. Check logs for details.")
        self._append_training_log(details)
        self.hitl_long_session_state = None

    def _on_training_thread_finished(self) -> None:
        sender_thread = self.sender()
        if sender_thread is not self.training_thread:
            return
        self.training_start_btn.setEnabled(True)
        self.training_stop_btn.setEnabled(False)
        self.training_params_widget.setEnabled(True)
        self.training_worker = None
        self.training_thread = None
        self._refresh_training_view()
        if isinstance(self.hitl_long_session_state, dict) and int(self.hitl_long_session_state.get("remaining_cycles", 0) or 0) > 0:
            QTimer.singleShot(0, self._continue_hitl_long_session)

    def _show_about_dialog(self) -> None:
        QMessageBox.about(
            self,
            f"About {APP_TITLE}",
            APP_ABOUT_TEXT,
        )

