        self.rf_last_mask = None
        self.rf_last_probability = None
        self.rf_last_details = None
        self.rf_probability_by_uid.clear()
        self.rf_last_eval_rows = []
        self.rf_sigma_scores = []
        self.rf_batch_rows = []
        self.rf_batch_target_count = 0
        self.foundation_prompt_layers.clear()
        self.foundation_box_by_uid.clear()
        self.foundation_suggestions.clear()
        self.foundation_interactions_by_uid.clear()
        self.foundation_run_history_by_uid.clear()
