        self._foundation_stroke_class_id = FOUNDATION_POSITIVE_ID
        self.pipeline_dataset_summary = None
        self.pipeline_measurement_rows = []
        self.plant_track_rows = []
        self.plant_track_include_overrides.clear()
        self.analytics_payload = None
        self.analytics_rows = []
        self.analytics_benchmark = None
        self.analytics_config = None
        self.analytics_track_include_overrides.clear()
        self.sensor_base_image = None
