    def _browse_sensor_base_image(self, _checked: bool = False) -> None:
        file_name, _ = QFileDialog.getOpenFileName(
            self,
            "Select base image (B/W)",
            "",
            "Images (*.png *.jpg *.jpeg *.tif *.tiff *.bmp *.jxl);;All files (*)",
        )
        if not file_name:
            return
        path = Path(file_name)
        image = self._decode_image_path(path)
        if image is None:
            QMessageBox.warning(self, "Load failed", f"Could not decode image:\n{path}")
            return
        self.sensor_base_image = image
        self.sensor_base_path_edit.setText(str(path))
        self._apply_sensor_processing(silent=True)

    def _browse_sensor_fluorcam_series(self, _checked: bool = False) -> None:
        directory = QFileDialog.getExistingDirectory(self, "Select FluorCam series folder")
        if not directory:
            return
        self.sensor_fluorcam_series_dir = Path(directory)
        if hasattr(self, "sensor_fluorcam_series_edit"):
            self.sensor_fluorcam_series_edit.setText(str(self.sensor_fluorcam_series_dir))

    def _infer_fluorcam_series_dir_from_item(self, item: DatasetImageItem | None) -> Path | None:
        if item is None:
            return None
        try:
            parent = Path(item.path).resolve().parent
        except Exception:
            parent = Path(item.path).parent
        root_type = "ROOT2" if "ROOT2" in str(item.path).upper() else "ROOT1"
        preferred = "FC2" if root_type == "ROOT2" else "FC1"
        candidates = [
            parent.with_name(f"{parent.name}_{preferred}"),
            parent.with_name(f"{parent.name}_FC1"),
            parent.with_name(f"{parent.name}_FC2"),
        ]
        seen: set[str] = set()
        for candidate in candidates:
            key = str(candidate)
            if key in seen:
                continue
            seen.add(key)
            if candidate.exists() and candidate.is_dir():
                return candidate
        return None

    def _guess_sensor_fluorcam_series(self, _checked: bool = False) -> None:
        item = self._current_item()
        guessed = self._infer_fluorcam_series_dir_from_item(item)
        if guessed is None:
            QMessageBox.information(
                self,
                "No FluorCam folder found",
                "Could not infer a sibling FluorCam folder from the current image.",
            )
            return
        self.sensor_fluorcam_series_dir = guessed
        if hasattr(self, "sensor_fluorcam_series_edit"):
            self.sensor_fluorcam_series_edit.setText(str(guessed))

    def _resolve_sensor_fluorcam_series_dir(self, item: DatasetImageItem | None = None) -> Path:
        if self.sensor_fluorcam_series_dir is not None and self.sensor_fluorcam_series_dir.exists():
            return self.sensor_fluorcam_series_dir
        guessed = self._infer_fluorcam_series_dir_from_item(item or self._current_item())
        if guessed is not None:
            self.sensor_fluorcam_series_dir = guessed
            if hasattr(self, "sensor_fluorcam_series_edit"):
                self.sensor_fluorcam_series_edit.setText(str(guessed))
            return guessed
        raise RuntimeError("Set the FluorCam series folder first.")

    def _sensor_root_gap_class_ids(self) -> tuple[int, int | None]:
        class_ids = self._ensure_segmentation_pipeline_classes(select_defaults=False)
        root_class_id = int(class_ids.get("root", 0))
        lateral_class_id = int(class_ids.get("lateral", 0))
        if lateral_class_id <= 0 or lateral_class_id == root_class_id:
            return root_class_id, None
        return root_class_id, lateral_class_id

    def _fluorcam_pairs_for_items(
        self,
        items: list[DatasetImageItem],
        fluorescence_dir: Path,
    ) -> dict[str, FluorCamPair]:
        fluor_by_key: dict[str, Path] = {}
        for path in sorted(Path(fluorescence_dir).iterdir()):
            if not path.is_file():
                continue
            key = extract_frame_key(path)
            if key:
                fluor_by_key[str(key)] = path
        pairs: dict[str, FluorCamPair] = {}
        for item in items:
            key = extract_frame_key(Path(item.path))
            if key is None:
                continue
            fluor_path = fluor_by_key.get(str(key))
            if fluor_path is None:
                continue
            pairs[str(item.uid)] = FluorCamPair(
                frame_key=str(key),
                root_image_path=Path(item.path),
                fluorescence_path=fluor_path,
            )
        return pairs

    def _current_item_rgb(self, item: DatasetImageItem) -> np.ndarray:
        image = np.asarray(item.image)
        if image.ndim == 2:
            return cv2.cvtColor(np.asarray(image, dtype=np.uint8), cv2.COLOR_GRAY2RGB)
        if image.ndim == 3 and image.shape[2] >= 3:
            return np.asarray(image[:, :, :3], dtype=np.uint8)
        raise ValueError(f"Unsupported image shape: {image.shape}")

    def _sensor_prediction_overlay(
        self,
        item: DatasetImageItem,
        *,
        prediction_index: np.ndarray | None = None,
        added_mask: np.ndarray | None = None,
    ) -> np.ndarray | None:
        pred = prediction_index if prediction_index is not None else self.predictions.get(item.uid)
        if not isinstance(pred, np.ndarray):
            return None
        pred_u8 = self._ensure_index_mask_shape(np.asarray(pred, dtype=np.uint8), item.image.shape[:2])
        base_rgb = self._current_item_rgb(item)
        overlay = self._blend_index_for_display(base_rgb, pred_u8, alpha=0.40)
        if isinstance(added_mask, np.ndarray):
            added = self._ensure_index_mask_shape(np.asarray(added_mask, dtype=np.uint8), item.image.shape[:2]) > 0
            if np.any(added):
                highlight = np.array([255.0, 255.0, 255.0], dtype=np.float32)
                out = overlay.astype(np.float32)
                out[added] = out[added] * 0.15 + highlight * 0.85
                overlay = np.clip(out, 0, 255).astype(np.uint8)
        return overlay

    def _preview_fluorcam_support_for_item(self, item: DatasetImageItem) -> dict[str, object]:
        fluorescence_dir = self._resolve_sensor_fluorcam_series_dir(item)
        pair = self._fluorcam_pairs_for_items([item], fluorescence_dir).get(str(item.uid))
        if pair is None:
            raise RuntimeError(f"No matching FluorCam frame found for {item.name}.")

        root_rgb = self._current_item_rgb(item)
        aligned_fluor, metadata, alignment = load_aligned_fluorcam_frame(
            pair.fluorescence_path,
            root_image_path=pair.root_image_path,
        )
        support = compute_fluorescence_support_map(root_rgb, aligned_fluor)
        fluor_u8 = normalize_to_uint8(aligned_fluor, pmin=1.0, pmax=99.5)
        fluor_rgb = cv2.applyColorMap(fluor_u8, cv2.COLORMAP_HOT)[:, :, ::-1]
        prediction_overlay = self._sensor_prediction_overlay(item)
        overlay = prediction_overlay if prediction_overlay is not None else render_support_overlay(root_rgb, support)
        has_prediction = prediction_overlay is not None

        self.sensor_base_image = root_rgb
        self.sensor_data_raw = np.asarray(aligned_fluor, dtype=np.float32)
        self.sensor_corrected_rgb = fluor_rgb
        self.sensor_overlay_rgb = overlay
        self.sensor_base_path_edit.setText(str(item.path))
        self.sensor_data_path_edit.setText(str(pair.fluorescence_path))
        self._refresh_sensors_view()

        details = {
            "frame_key": pair.frame_key,
            "fluor_file": pair.fluorescence_path.name,
            "filter_name": metadata.filter_name or "unknown",
            "alignment_source": alignment.source,
            "mirror_horizontal": bool(alignment.mirror_horizontal),
            "mirror_source": str(alignment.mirror_source),
            "offset_x": int(alignment.offset_x),
            "offset_y": int(alignment.offset_y),
            "resized_shape": tuple(int(v) for v in alignment.resized_shape),
            "support_mean": float(np.mean(support)),
            "support_p95": float(np.percentile(support, 95)),
            "support_p99": float(np.percentile(support, 99)),
            "support_map": support,
            "aligned_fluor": aligned_fluor,
            "has_prediction": bool(has_prediction),
        }
        info_lines = [
            f"FluorCam pair: {pair.fluorescence_path.name}",
            f"Filter: {details['filter_name']}",
            f"Alignment: {alignment.source} | mirror={'on' if alignment.mirror_horizontal else 'off'} ({alignment.mirror_source}) | resize={alignment.resized_shape} | offset=({alignment.offset_x}, {alignment.offset_y})",
            f"Support mean: {details['support_mean']:.4f}",
            f"Support P95/P99: {details['support_p95']:.4f} / {details['support_p99']:.4f}",
            (
                "Overlay: stored prediction mask"
                if has_prediction
                else "Overlay: fluorescence support only (no stored prediction found for this image)"
            ),
            "Use the center panel for fluorescence support and the right panel to inspect the prediction layer.",
        ]
        self.sensor_info.setPlainText("\n".join(info_lines))
        return details

    def _repair_prediction_with_fluorcam_support(self, item: DatasetImageItem) -> dict[str, object]:
        prediction = self.predictions.get(item.uid)
        if not isinstance(prediction, np.ndarray):
            raise RuntimeError("Run segmentation first so there is a prediction to repair.")

        preview = self._preview_fluorcam_support_for_item(item)
        root_class_id, lateral_class_id = self._sensor_root_gap_class_ids()
        pred_u8 = self._ensure_index_mask_shape(np.asarray(prediction, dtype=np.uint8), item.image.shape[:2])
        rootish_ids = [int(root_class_id)]
        if lateral_class_id is not None:
            rootish_ids.append(int(lateral_class_id))
        rootish_mask = np.isin(pred_u8, np.asarray(rootish_ids, dtype=np.uint8)).astype(np.uint8)

        repaired_mask, bridges = repair_root_gaps_with_fluorescence(
            rootish_mask,
            np.asarray(preview["support_map"], dtype=np.float32),
            max_gap_px=int(self.sensor_gap_max_spin.value()),
            min_mean_support=float(self.sensor_gap_support_spin.value()),
        )
        updated, root_added, lateral_added = assign_repaired_pixels_to_root_classes(
            pred_u8,
            repaired_mask,
            root_class_id=int(root_class_id),
            lateral_class_id=int(lateral_class_id) if lateral_class_id is not None else None,
        )
        added_pixels = int(root_added + lateral_added)
        added_mask = np.logical_and(np.asarray(updated, dtype=np.uint8) > 0, np.asarray(pred_u8, dtype=np.uint8) == 0)
        return {
            "updated_prediction": updated,
            "bridges": bridges,
            "bridge_count": int(len(bridges)),
            "added_pixels": added_pixels,
            "added_root_pixels": int(root_added),
            "added_lateral_pixels": int(lateral_added),
            "support_mean": float(preview["support_mean"]),
            "support_p95": float(preview["support_p95"]),
            "filter_name": str(preview["filter_name"]),
            "alignment_source": str(preview["alignment_source"]),
            "mirror_horizontal": bool(preview["mirror_horizontal"]),
            "mirror_source": str(preview["mirror_source"]),
            "fluor_file": str(preview["fluor_file"]),
            "added_mask": np.asarray(added_mask, dtype=np.uint8),
        }

    def _preview_fluorcam_support_current(self, _checked: bool = False) -> None:
        item = self._current_item()
        if item is None:
            QMessageBox.warning(self, "No image", "Load dataset images first.")
            return
        try:
            self._preview_fluorcam_support_for_item(item)
        except Exception as exc:
            QMessageBox.warning(self, "FluorCam preview failed", str(exc))

    def _apply_fluorcam_gap_repair_current(self, _checked: bool = False) -> None:
        item = self._current_item()
        if item is None:
            QMessageBox.warning(self, "No image", "Load dataset images first.")
            return
        try:
            result = self._repair_prediction_with_fluorcam_support(item)
        except Exception as exc:
            QMessageBox.warning(self, "Gap repair failed", str(exc))
            return
        updated = np.asarray(result["updated_prediction"], dtype=np.uint8)
        self.predictions[item.uid] = updated
        preview_overlay = self._sensor_prediction_overlay(
            item,
            prediction_index=updated,
            added_mask=np.asarray(result.get("added_mask"), dtype=np.uint8),
        )
        if isinstance(preview_overlay, np.ndarray):
            self.sensor_overlay_rgb = preview_overlay
            self._refresh_sensors_view()
            info_lines = self.sensor_info.toPlainText().splitlines()
            info_lines.append(
                (
                    f"Repair result: {int(result['bridge_count'])} bridge(s), {int(result['added_pixels'])} added pixel(s). "
                    "New bridge pixels are highlighted in white."
                    if int(result["added_pixels"]) > 0
                    else "Repair result: no disconnected root gaps passed the current support threshold, so the prediction was unchanged."
                )
            )
            self.sensor_info.setPlainText("\n".join(info_lines))
        meta = dict(self.prediction_metadata_by_uid.get(item.uid, {}))
        meta["fluorcam_gap_repair"] = {
            "bridge_count": int(result["bridge_count"]),
            "added_pixels": int(result["added_pixels"]),
            "added_root_pixels": int(result["added_root_pixels"]),
            "added_lateral_pixels": int(result["added_lateral_pixels"]),
            "support_mean": float(result["support_mean"]),
            "support_p95": float(result["support_p95"]),
            "filter_name": str(result["filter_name"]),
            "alignment_source": str(result["alignment_source"]),
            "mirror_horizontal": bool(result["mirror_horizontal"]),
            "mirror_source": str(result["mirror_source"]),
            "fluor_file": str(result["fluor_file"]),
        }
        self.prediction_metadata_by_uid[item.uid] = meta
        self._mark_predictions_changed()
        self._set_dirty(True)
        self._refresh_all_views()
        QMessageBox.information(
            self,
            "Gap repair complete",
            (
                f"Image: {item.name}\n"
                f"Bridges accepted: {int(result['bridge_count'])}\n"
                f"Added pixels: {int(result['added_pixels'])}\n"
                f"Root / lateral added: {int(result['added_root_pixels'])} / {int(result['added_lateral_pixels'])}\n"
                + (
                    "The right panel now shows the updated prediction overlay."
                    if int(result["added_pixels"]) > 0
                    else "No disconnected gaps met the current criteria, so the prediction layer was unchanged."
                )
            ),
        )

    def _apply_fluorcam_gap_repair_batch(self, _checked: bool = False) -> None:
        if not self.dataset_items:
            QMessageBox.warning(self, "No dataset", "Load dataset images first.")
            return
        selected = self._selected_dataset_items()
        if 1 < len(selected) < len(self.dataset_items):
            targets = selected
            scope_label = "selected images"
        else:
            targets = list(self.dataset_items)
            scope_label = "loaded dataset"

        try:
            fluorescence_dir = self._resolve_sensor_fluorcam_series_dir(targets[0] if targets else None)
        except Exception as exc:
            QMessageBox.warning(self, "Missing FluorCam folder", str(exc))
            return

        pairs = self._fluorcam_pairs_for_items(targets, fluorescence_dir)
        if not pairs:
            QMessageBox.warning(self, "No pairs", "No matching FluorCam frames were found for the chosen scope.")
            return

        progress = QProgressDialog("Repairing prediction gaps with FluorCam support...", "Cancel", 0, len(targets), self)
        progress.setWindowModality(Qt.WindowModal)
        self._prime_progress_dialog(progress, "Repairing prediction gaps with FluorCam support...")

        repaired_images = 0
        missing_pairs = 0
        missing_predictions = 0
        bridge_count = 0
        added_pixels = 0
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            for index, item in enumerate(targets, start=1):
                if progress.wasCanceled():
                    break
                progress.setValue(index - 1)
                progress.setLabelText(f"Processing {index}/{len(targets)}: {item.name}")
                QApplication.processEvents()

                if item.uid not in pairs:
                    missing_pairs += 1
                    continue
                if not isinstance(self.predictions.get(item.uid), np.ndarray):
                    missing_predictions += 1
                    continue

                try:
                    result = self._repair_prediction_with_fluorcam_support(item)
                except Exception:
                    continue
                if int(result["added_pixels"]) <= 0 and int(result["bridge_count"]) <= 0:
                    continue
                self.predictions[item.uid] = np.asarray(result["updated_prediction"], dtype=np.uint8)
                meta = dict(self.prediction_metadata_by_uid.get(item.uid, {}))
                meta["fluorcam_gap_repair"] = {
                    "bridge_count": int(result["bridge_count"]),
                    "added_pixels": int(result["added_pixels"]),
                    "added_root_pixels": int(result["added_root_pixels"]),
                    "added_lateral_pixels": int(result["added_lateral_pixels"]),
                    "support_mean": float(result["support_mean"]),
                    "support_p95": float(result["support_p95"]),
                    "filter_name": str(result["filter_name"]),
                    "alignment_source": str(result["alignment_source"]),
                    "mirror_horizontal": bool(result["mirror_horizontal"]),
                    "mirror_source": str(result["mirror_source"]),
                    "fluor_file": str(result["fluor_file"]),
                }
                self.prediction_metadata_by_uid[item.uid] = meta
                repaired_images += 1
                bridge_count += int(result["bridge_count"])
                added_pixels += int(result["added_pixels"])
        finally:
            progress.setValue(len(targets))
            progress.close()
            QApplication.restoreOverrideCursor()

        if repaired_images > 0:
            self._mark_predictions_changed()
            self._set_dirty(True)
        self._refresh_all_views()
        QMessageBox.information(
            self,
            "Batch gap repair finished",
            (
                f"Scope: {scope_label}\n"
                f"Repaired images: {repaired_images}\n"
                f"Accepted bridges: {bridge_count}\n"
                f"Added pixels: {added_pixels}\n"
                f"Missing FluorCam pairs: {missing_pairs}\n"
                f"Missing predictions: {missing_predictions}\n"
                f"FluorCam folder: {fluorescence_dir}"
            ),
        )

    def _browse_sensor_analysis_output_dir(self, _checked: bool = False) -> None:
        start_dir = self.sensor_analysis_output_edit.text().strip()
        if not start_dir:
            start_dir = str(self._default_sensor_analysis_output_dir())
        directory = QFileDialog.getExistingDirectory(self, "Select sensor analysis output folder", start_dir)
        if not directory:
            return
        self.sensor_analysis_output_edit.setText(str(Path(directory)))

    def _default_sensor_analysis_output_dir(self) -> Path:
        mode = str(self.sensor_mode_combo.currentData() or "fluorescence")
        suffix = "fluorcam_analysis_exports" if mode == "fluorescence" else "hyperspectral_analysis_exports"
        for text in (
            self.sensor_analysis_output_edit.text().strip() if hasattr(self, "sensor_analysis_output_edit") else "",
            self.sensor_data_path_edit.text().strip() if hasattr(self, "sensor_data_path_edit") else "",
            self.sensor_base_path_edit.text().strip() if hasattr(self, "sensor_base_path_edit") else "",
        ):
            if not text:
                continue
            path = Path(text).expanduser()
            base = path if path.is_dir() else path.parent
            if base.exists():
                return base / suffix
        item = self._current_item()
        if item is not None:
            return Path(item.path).expanduser().parent / suffix
        return Path.home() / suffix

    def _resolved_sensor_analysis_output_dir(self, create: bool = True) -> Path:
        text = self.sensor_analysis_output_edit.text().strip() if hasattr(self, "sensor_analysis_output_edit") else ""
        target = Path(text).expanduser() if text else self._default_sensor_analysis_output_dir()
        if create:
            target.mkdir(parents=True, exist_ok=True)
        if hasattr(self, "sensor_analysis_output_edit"):
            self.sensor_analysis_output_edit.setText(str(target))
        return target

    def _sensor_mask_source_key(self) -> str:
        if not hasattr(self, "sensor_mask_source_combo"):
            return "prefer_predictions"
        data = self.sensor_mask_source_combo.currentData()
        return str(data or "prefer_predictions")

    def _sensor_index_mask_for_item(self, item: DatasetImageItem) -> tuple[np.ndarray | None, str]:
        shape_hw = item.image.shape[:2]
        source_key = self._sensor_mask_source_key()

        pred = self.predictions.get(item.uid)
        if source_key in {"prefer_predictions", "predictions_only"} and isinstance(pred, np.ndarray):
            pred_u8 = self._ensure_index_mask_shape(np.asarray(pred, dtype=np.uint8), shape_hw)
            if np.any(pred_u8 > 0):
                return pred_u8, "predictions"
            if source_key == "predictions_only":
                return None, ""

        if source_key in {"prefer_predictions", "labels_only"}:
            layers = self.annotations.get(item.uid)
            if isinstance(layers, dict) and layers:
                label_mask = index_mask_from_layers(layers, self.classes, shape_hw)
                if np.any(label_mask > 0):
                    return np.asarray(label_mask, dtype=np.uint8), "labels"

        return None, ""

    def _sensor_class_masks_for_item(self, item: DatasetImageItem) -> tuple[dict[str, np.ndarray], str]:
        index_mask, mask_source = self._sensor_index_mask_for_item(item)
        if not isinstance(index_mask, np.ndarray):
            raise RuntimeError("No compatible predictions or labels were found for this image.")

        h, w = item.image.shape[:2]
        main_root = np.zeros((h, w), dtype=np.uint8)
        lateral = np.zeros((h, w), dtype=np.uint8)
        shoot = np.zeros((h, w), dtype=np.uint8)
        for cls in self.classes:
            pixels = index_mask == int(cls.class_id)
            if not np.any(pixels):
                continue
            name = str(cls.name).strip().lower()
            if self._is_lateral_class_name(name):
                lateral[pixels] = 1
            elif self._is_root_class_name(name, allow_lateral=False):
                main_root[pixels] = 1
            elif self._is_shoot_class_name(name):
                shoot[pixels] = 1

        if not np.any(main_root) and not np.any(lateral):
            raise RuntimeError(
                "No root-like classes were found in the chosen mask source. "
                "Use predictions/labels that contain Root or Lateral Root classes."
            )
        return {"main_root": main_root, "lateral_root": lateral, "shoot": shoot}, mask_source

    def _sensor_analysis_provenance_label(self, item: DatasetImageItem, mask_source: str) -> str:
        return f"{mask_source}:{item.name}"

    def _sensor_hyperspectral_pairs_for_items(self, items: list[DatasetImageItem]) -> dict[str, Path]:
        source_text = self.sensor_data_path_edit.text().strip() if hasattr(self, "sensor_data_path_edit") else ""
        if not source_text:
            return {}
        source_path = Path(source_text).expanduser()
        directory = source_path if source_path.is_dir() else source_path.parent
        if not directory.exists() or not directory.is_dir():
            return {}

        ranked: dict[str, tuple[int, Path]] = {}
        for path in sorted(directory.iterdir()):
            if not path.is_file():
                continue
            suffix = path.suffix.lower()
            if suffix not in {".hdr", ".bil", ".npy", ".npz", ".png", ".jpg", ".jpeg", ".tif", ".tiff", ".bmp"}:
                continue
            key = extract_frame_key(path)
            if key is None:
                continue
            priority = 0
            if suffix == ".hdr":
                priority = 30
            elif suffix == ".bil":
                priority = 20
            elif suffix in {".npy", ".npz"}:
                priority = 10
            previous = ranked.get(str(key))
            if previous is None or priority > int(previous[0]):
                ranked[str(key)] = (priority, path)

        pairs: dict[str, Path] = {}
        for item in items:
            key = extract_frame_key(Path(item.path))
            if key is None:
                continue
            selected = ranked.get(str(key))
            if selected is not None:
                pairs[str(item.uid)] = selected[1]
        return pairs

    def _sensor_current_optical_config(self):
        try:
            return load_optical_correction_config(self.sensor_optical_config_path)
        except Exception:
            return load_optical_correction_config(None)

    def _analyze_fluorescence_item(self, item: DatasetImageItem) -> dict[str, object]:
        fluorescence_dir = self._resolve_sensor_fluorcam_series_dir(item)
        pair = self._fluorcam_pairs_for_items([item], fluorescence_dir).get(str(item.uid))
        if pair is None:
            raise RuntimeError(f"No matching FluorCam frame found for {item.name}.")

        class_masks, mask_source = self._sensor_class_masks_for_item(item)
        analyses = derive_plant_region_analyses(
            class_masks["main_root"],
            class_masks["lateral_root"],
            class_masks["shoot"],
        )
        if not analyses:
            raise RuntimeError("The selected mask source did not yield any plant regions to analyze.")

        root_rgb = self._current_item_rgb(item)
        aligned_fluor, metadata, alignment = load_aligned_fluorcam_frame(
            pair.fluorescence_path,
            root_image_path=pair.root_image_path,
        )
        fluor_u8 = normalize_to_uint8(aligned_fluor, pmin=1.0, pmax=99.5)
        fluor_rgb = cv2.applyColorMap(fluor_u8, cv2.COLORMAP_HOT)[:, :, ::-1]
        overlay = render_region_overlay(fluor_rgb, analyses, alpha=float(self.sensor_alpha_spin.value()))
        summary_rows, pixel_rows = summarize_fluorescence_regions(aligned_fluor, analyses, pair.fluorescence_path.name)

        return {
            "mode": "fluorescence",
            "item": item,
            "mask_source": mask_source,
            "mask_source_label": self._sensor_analysis_provenance_label(item, mask_source),
            "analyses": analyses,
            "base_rgb": root_rgb,
            "sensor_preview_rgb": fluor_rgb,
            "overlay_rgb": overlay,
            "summary_rows": summary_rows,
            "pixel_rows": pixel_rows,
            "source_name": pair.fluorescence_path.name,
            "source_path": pair.fluorescence_path,
            "filter_name": metadata.filter_name or "unknown",
            "alignment_source": alignment.source,
            "mirror_horizontal": bool(alignment.mirror_horizontal),
        }

    def _analyze_hyperspectral_item(self, item: DatasetImageItem, sensor_path: Path | None = None) -> dict[str, object]:
        path_text = self.sensor_data_path_edit.text().strip() if sensor_path is None else str(sensor_path)
        if not path_text:
            raise RuntimeError("Select a hyperspectral file first.")
        path = Path(path_text).expanduser()
        if not path.exists():
            raise FileNotFoundError(f"Sensor file not found: {path}")

        if sensor_path is None and self.sensor_data_raw is not None and Path(self.sensor_data_path_edit.text().strip()) == path:
            raw_data = np.asarray(self.sensor_data_raw)
        else:
            raw_data = np.asarray(load_sensor_data(path))
        if raw_data.ndim != 3 or raw_data.shape[2] <= 1:
            raise RuntimeError("The selected hyperspectral source is not a valid multi-band cube.")

        class_masks, mask_source = self._sensor_class_masks_for_item(item)
        analyses = derive_plant_region_analyses(
            class_masks["main_root"],
            class_masks["lateral_root"],
            class_masks["shoot"],
        )
        if not analyses:
            raise RuntimeError("The selected mask source did not yield any plant regions to analyze.")

        cfg = self._sensor_current_optical_config()
        corrected_cube = apply_optical_correction_array(raw_data, item.image.shape[:2], cfg)
        wavelengths = load_envi_wavelengths(path) if path.suffix.lower() in {".hdr", ".bil"} else []
        band_index = int(self.sensor_band_spin.value()) if hasattr(self, "sensor_band_spin") else 0
        sensor_preview = hyperspectral_to_rgb(
            corrected_cube,
            band_index=band_index,
            pmin=float(cfg.clip_min_percentile),
            pmax=float(cfg.clip_max_percentile),
        )
        overlay = render_region_overlay(sensor_preview, analyses, alpha=float(self.sensor_alpha_spin.value()))
        summary_rows = summarize_hyperspectral_regions(
            corrected_cube,
            analyses,
            path.name,
            wavelengths=wavelengths,
            mask_source_label=self._sensor_analysis_provenance_label(item, mask_source),
        )

        return {
            "mode": "hyperspectral",
            "item": item,
            "mask_source": mask_source,
            "mask_source_label": self._sensor_analysis_provenance_label(item, mask_source),
            "analyses": analyses,
            "base_rgb": self._current_item_rgb(item),
            "sensor_preview_rgb": sensor_preview,
            "overlay_rgb": overlay,
            "summary_rows": summary_rows,
            "pixel_rows": [],
            "source_name": path.name,
            "source_path": path,
            "wavelengths": wavelengths,
            "band_count": int(corrected_cube.shape[2]),
        }

    def _analyze_sensor_item(self, item: DatasetImageItem, sensor_path: Path | None = None) -> dict[str, object]:
        mode = str(self.sensor_mode_combo.currentData() or "fluorescence")
        if mode == "hyperspectral":
            return self._analyze_hyperspectral_item(item, sensor_path=sensor_path)
        return self._analyze_fluorescence_item(item)

    def _apply_sensor_analysis_preview(self, result: dict[str, object]) -> None:
        self.sensor_base_image = np.asarray(result["base_rgb"], dtype=np.uint8)
        self.sensor_corrected_rgb = np.asarray(result["sensor_preview_rgb"], dtype=np.uint8)
        self.sensor_overlay_rgb = np.asarray(result["overlay_rgb"], dtype=np.uint8)
        self._refresh_sensors_view()

        analyses = list(result.get("analyses", []))
        lines = [
            f"Mode: {result.get('mode')}",
            f"Source: {result.get('source_name')}",
            f"Mask source: {result.get('mask_source')}",
            f"Detected plant regions: {len(analyses)}",
        ]
        if result.get("mode") == "fluorescence":
            lines.extend(
                [
                    f"Filter: {result.get('filter_name')}",
                    f"Alignment source: {result.get('alignment_source')}",
                    f"Mirror horizontal: {'yes' if bool(result.get('mirror_horizontal')) else 'no'}",
                    f"Summary rows: {len(result.get('summary_rows', []))}",
                    f"Pixel rows: {len(result.get('pixel_rows', []))}",
                ]
            )
        else:
            wavelengths = result.get("wavelengths", [])
            lines.extend(
                [
                    f"Bands: {int(result.get('band_count', 0))}",
                    (
                        f"Wavelength range: {float(wavelengths[0]):.1f}–{float(wavelengths[-1]):.1f} nm"
                        if isinstance(wavelengths, list) and wavelengths
                        else "Wavelength range: unavailable"
                    ),
                    f"Summary rows: {len(result.get('summary_rows', []))}",
                ]
            )
        self.sensor_info.setPlainText("\n".join(lines))

    def _write_sensor_current_exports(self, result: dict[str, object], output_dir: Path) -> dict[str, Path]:
        item = result["item"]
        stem = Path(str(item.name)).stem or str(item.uid)
        files: dict[str, Path] = {}
        if result.get("mode") == "fluorescence":
            summary_path = output_dir / f"{stem}_fc_summary.csv"
            pixels_path = output_dir / f"{stem}_fc_pixels.csv"
            overlay_path = output_dir / f"{stem}_fc_overlay.png"
            write_csv_rows(summary_path, list(result.get("summary_rows", [])), ["fc_file", "plant_id", "parameter", "value"])
            write_csv_rows(
                pixels_path,
                list(result.get("pixel_rows", [])),
                ["fc_file", "plant_id", "region", "y", "x", "fluorescence"],
            )
            save_overlay_image(overlay_path, np.asarray(result["overlay_rgb"], dtype=np.uint8))
            files = {"summary": summary_path, "pixels": pixels_path, "overlay": overlay_path}
        else:
            summary_path = output_dir / f"{stem}_hpx_summary_wide.csv"
            overlay_path = output_dir / f"{stem}_hpx_overlay.png"
            write_csv_rows(
                summary_path,
                list(result.get("summary_rows", [])),
                None,
            )
            save_overlay_image(overlay_path, np.asarray(result["overlay_rgb"], dtype=np.uint8))
            files = {"summary": summary_path, "overlay": overlay_path}
        return files

    def _analyze_sensor_current(self, _checked: bool = False) -> None:
        item = self._current_item()
        if item is None:
            QMessageBox.warning(self, "No image", "Load dataset images first.")
            return
        try:
            result = self._analyze_sensor_item(item)
        except Exception as exc:
            QMessageBox.warning(self, "Sensor analysis failed", str(exc))
            return
        self.sensor_base_path_edit.setText(str(item.path))
        self.sensor_data_path_edit.setText(str(result.get("source_path", self.sensor_data_path_edit.text())))
        self._apply_sensor_analysis_preview(result)
        QMessageBox.information(
            self,
            "Sensor analysis ready",
            (
                f"Image: {item.name}\n"
                f"Mode: {result.get('mode')}\n"
                f"Detected plant regions: {len(result.get('analyses', []))}\n"
                "The center panel shows the registered sensor signal, and the right panel shows the mask-based analysis overlay."
            ),
        )

    def _export_sensor_current_analysis(self, _checked: bool = False) -> None:
        item = self._current_item()
        if item is None:
            QMessageBox.warning(self, "No image", "Load dataset images first.")
            return
        try:
            result = self._analyze_sensor_item(item)
        except Exception as exc:
            QMessageBox.warning(self, "Sensor export failed", str(exc))
            return
        output_dir = self._resolved_sensor_analysis_output_dir(create=True)
        files = self._write_sensor_current_exports(result, output_dir)
        self._apply_sensor_analysis_preview(result)
        lines = [f"{label.title()}: {path}" for label, path in files.items()]
        QMessageBox.information(self, "Sensor analysis exported", "\n".join(lines))

    def _export_sensor_batch_analysis(self, _checked: bool = False) -> None:
        if not self.dataset_items:
            QMessageBox.warning(self, "No dataset", "Load dataset images first.")
            return
        selected = self._selected_dataset_items()
        if 1 < len(selected) < len(self.dataset_items):
            targets = selected
            scope_label = "selected images"
        else:
            targets = list(self.dataset_items)
            scope_label = "loaded dataset"
        if not targets:
            QMessageBox.warning(self, "No targets", "No dataset images are available for export.")
            return

        mode = str(self.sensor_mode_combo.currentData() or "fluorescence")
        output_dir = self._resolved_sensor_analysis_output_dir(create=True)
        overlays_dir = output_dir / "overlays"
        overlays_dir.mkdir(parents=True, exist_ok=True)

        progress = QProgressDialog("Exporting sensor analysis...", "Cancel", 0, len(targets), self)
        progress.setWindowModality(Qt.WindowModal)
        self._prime_progress_dialog(progress, "Exporting sensor analysis...")

        summary_rows: list[dict[str, object]] = []
        pixel_rows: list[dict[str, object]] = []
        exported = 0
        missing_sensor = 0
        skipped_masks = 0
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            hyperspectral_pairs = self._sensor_hyperspectral_pairs_for_items(targets) if mode == "hyperspectral" else {}
            for index, item in enumerate(targets, start=1):
                if progress.wasCanceled():
                    break
                progress.setValue(index - 1)
                progress.setLabelText(f"Analyzing {index}/{len(targets)}: {item.name}")
                QApplication.processEvents()

                try:
                    if mode == "hyperspectral":
                        sensor_path = hyperspectral_pairs.get(str(item.uid))
                        if sensor_path is None:
                            missing_sensor += 1
                            continue
                        result = self._analyze_sensor_item(item, sensor_path=sensor_path)
                    else:
                        result = self._analyze_sensor_item(item)
                except RuntimeError as exc:
                    if "No compatible predictions or labels" in str(exc) or "No root-like classes" in str(exc):
                        skipped_masks += 1
                        continue
                    if "No matching FluorCam frame" in str(exc):
                        missing_sensor += 1
                        continue
                    continue
                except Exception:
                    continue

                summary_rows.extend(list(result.get("summary_rows", [])))
                pixel_rows.extend(list(result.get("pixel_rows", [])))
                overlay_path = overlays_dir / f"{Path(str(item.name)).stem}_{mode}_overlay.png"
                save_overlay_image(overlay_path, np.asarray(result["overlay_rgb"], dtype=np.uint8))
                exported += 1
        finally:
            progress.setValue(len(targets))
            progress.close()
            QApplication.restoreOverrideCursor()

        if mode == "fluorescence":
            summary_path = output_dir / "fluorcam_summary_template.csv"
            pixels_path = output_dir / "fluorcam_pixels_template.csv"
            write_csv_rows(summary_path, summary_rows, ["fc_file", "plant_id", "parameter", "value"])
            write_csv_rows(pixels_path, pixel_rows, ["fc_file", "plant_id", "region", "y", "x", "fluorescence"])
            message = (
                f"Scope: {scope_label}\n"
                f"Exported images: {exported}\n"
                f"Missing sensor pairs: {missing_sensor}\n"
                f"Skipped for missing masks: {skipped_masks}\n"
                f"Summary: {summary_path}\n"
                f"Pixels: {pixels_path}\n"
                f"Overlays: {overlays_dir}"
            )
        else:
            summary_path = output_dir / "hyperspectral_summary_template.csv"
            write_csv_rows(summary_path, summary_rows, None)
            message = (
                f"Scope: {scope_label}\n"
                f"Exported images: {exported}\n"
                f"Missing sensor pairs: {missing_sensor}\n"
                f"Skipped for missing masks: {skipped_masks}\n"
                f"Summary: {summary_path}\n"
                f"Overlays: {overlays_dir}"
            )
        QMessageBox.information(self, "Sensor batch export finished", message)

    def _sensor_optical_search_roots(self) -> list[Path]:
        extra_roots: list[Path] = []
        for text in (
            self.sensor_data_path_edit.text().strip() if hasattr(self, "sensor_data_path_edit") else "",
            self.sensor_base_path_edit.text().strip() if hasattr(self, "sensor_base_path_edit") else "",
        ):
            if not text:
                continue
            try:
                source = Path(text).expanduser().resolve()
            except Exception:
                source = Path(text).expanduser()
            parent = source.parent
            candidates = [parent, parent / "Pipelines"]
            if parent.parent != parent:
                candidates.append(parent.parent / "Pipelines")
            for candidate in candidates:
                if candidate.exists() and candidate.is_dir():
                    extra_roots.append(candidate)
        return discover_optical_profile_roots(extra_roots=extra_roots)

    def _refresh_sensor_optical_profiles(self, _checked: bool = False, auto_create_template: bool = False) -> None:
        if not hasattr(self, "sensor_optical_profile_combo"):
            return
        current_path = str(self.sensor_optical_config_path) if self.sensor_optical_config_path is not None else ""
        roots = self._sensor_optical_search_roots()
        profiles = discover_optical_correction_profiles(roots)

        created_path: Path | None = None
        if not profiles and auto_create_template and roots:
            try:
                created_path = create_optical_correction_template(roots[0])
                profiles = [created_path]
            except Exception:
                created_path = None

        self.sensor_optical_profiles = profiles
        combo = self.sensor_optical_profile_combo
        combo.blockSignals(True)
        combo.clear()
        combo.addItem("Default (no JSON)", "")
        for profile in profiles:
            combo.addItem(f"{profile.name}  ({profile.parent.name})", str(profile))

        target_path = current_path
        if not target_path and created_path is not None:
            target_path = str(created_path)
        if target_path and combo.findData(target_path) < 0:
            combo.addItem(f"Custom: {Path(target_path).name}", target_path)

        idx = combo.findData(target_path) if target_path else 0
        if idx < 0:
            idx = 0
        combo.setCurrentIndex(idx)
        combo.blockSignals(False)

        self._on_sensor_optical_profile_changed(combo.currentIndex())

    def _on_sensor_optical_profile_changed(self, _index: int) -> None:
        if not hasattr(self, "sensor_optical_profile_combo"):
            return
        data = self.sensor_optical_profile_combo.currentData()
        path_text = str(data).strip() if data is not None else ""
        if path_text:
            self.sensor_optical_config_path = Path(path_text)
            self.sensor_optical_path_edit.setText(path_text)
        else:
            self.sensor_optical_config_path = None
            self.sensor_optical_path_edit.clear()
        self._apply_sensor_processing(silent=True)

    def _create_sensor_optical_template(self, _checked: bool = False) -> None:
        roots = self._sensor_optical_search_roots()
        target_dir = roots[0] if roots else (Path.home() / "Documents" / "Apps" / "NPEC Labels" / "HVIR-FC" / "Pipelines")
        out_path = target_dir / "optical_correction_template.json"
        existed = out_path.exists()
        try:
            written = create_optical_correction_template(target_dir)
        except Exception as exc:
            QMessageBox.critical(self, "Template creation failed", str(exc))
            return
        self.sensor_optical_config_path = written
        self.sensor_optical_path_edit.setText(str(written))
        self._refresh_sensor_optical_profiles(auto_create_template=False)
        QMessageBox.information(
            self,
            "Profile template ready",
            (
                f"Using existing profile:\n{written}"
                if existed
                else f"Created profile template:\n{written}"
            ),
        )

    def _browse_sensor_data(self, _checked: bool = False) -> None:
        file_name, _ = QFileDialog.getOpenFileName(
            self,
            "Select fluorescence/hyperspectral data",
            "",
            "Sensor files (*.png *.jpg *.jpeg *.tif *.tiff *.bmp *.hdr *.bil *.tar *.npy *.npz);;All files (*)",
        )
        if not file_name:
            return
        path = Path(file_name)
        try:
            data = load_sensor_data(path)
        except Exception as exc:
            QMessageBox.warning(self, "Load failed", str(exc))
            return
        self.sensor_data_raw = data
        self.sensor_data_path_edit.setText(str(path))
        if isinstance(data, np.ndarray) and data.ndim == 3 and data.shape[2] > 3:
            self.sensor_band_spin.setRange(0, int(data.shape[2] - 1))
        else:
            self.sensor_band_spin.setRange(0, 0)
        self._refresh_sensor_optical_profiles(auto_create_template=False)
        self._apply_sensor_processing(silent=True)

    def _browse_sensor_optical_json(self, _checked: bool = False) -> None:
        start_dir = ""
        roots = self._sensor_optical_search_roots()
        if roots:
            start_dir = str(roots[0])
        elif self.sensor_optical_config_path is not None:
            start_dir = str(self.sensor_optical_config_path.parent)
        file_name, _ = QFileDialog.getOpenFileName(
            self,
            "Select optical correction JSON",
            start_dir,
            "JSON (*.json);;All files (*)",
        )
        if not file_name:
            return
        self.sensor_optical_config_path = Path(file_name)
        self.sensor_optical_path_edit.setText(str(self.sensor_optical_config_path))
        self._refresh_sensor_optical_profiles(auto_create_template=False)
        self._apply_sensor_processing(silent=True)

    def _apply_sensor_processing(self, _checked: bool = False, silent: bool = False) -> None:
        if self.sensor_base_image is None or self.sensor_data_raw is None:
            if not silent:
                QMessageBox.warning(self, "Missing input", "Load both base image and sensor data first.")
            self._refresh_sensors_view()
            return

        try:
            cfg = load_optical_correction_config(self.sensor_optical_config_path)
        except Exception as exc:
            if not silent:
                QMessageBox.warning(self, "Invalid optical config", str(exc))
            cfg = load_optical_correction_config(None)

        mode = str(self.sensor_mode_combo.currentData())
        data = np.asarray(self.sensor_data_raw)
        try:
            if mode == "hyperspectral":
                sensor_rgb = hyperspectral_to_rgb(
                    data,
                    band_index=int(self.sensor_band_spin.value()),
                    pmin=float(cfg.clip_min_percentile),
                    pmax=float(cfg.clip_max_percentile),
                )
            else:
                if data.ndim == 2:
                    gray = cv2.normalize(data.astype(np.float32), None, 0, 255, cv2.NORM_MINMAX).astype(np.uint8)
                    sensor_rgb = cv2.applyColorMap(gray, cv2.COLORMAP_HOT)[:, :, ::-1]
                elif data.ndim == 3 and data.shape[2] == 3:
                    sensor_rgb = np.asarray(data[:, :, :3], dtype=np.uint8)
                elif data.ndim == 3 and data.shape[2] > 3:
                    sensor_rgb = hyperspectral_to_rgb(
                        data,
                        band_index=int(self.sensor_band_spin.value()),
                        pmin=float(cfg.clip_min_percentile),
                        pmax=float(cfg.clip_max_percentile),
                    )
                else:
                    raise ValueError(f"Unsupported sensor data shape: {data.shape}")

            corrected = apply_optical_correction(sensor_rgb, self.sensor_base_image.shape[:2], cfg)
            overlay = overlay_modalities(self.sensor_base_image, corrected, float(self.sensor_alpha_spin.value()))
            self.sensor_corrected_rgb = corrected
            self.sensor_overlay_rgb = overlay
            self._refresh_sensors_view()

            lines = [
                f"Mode: {mode}",
                f"Sensor shape: {tuple(int(v) for v in data.shape)}",
                f"Optical JSON: {self.sensor_optical_config_path if self.sensor_optical_config_path is not None else 'default'}",
                f"Transform: scale=({cfg.scale_x:.4f},{cfg.scale_y:.4f}) shift=({cfg.shift_x:.2f},{cfg.shift_y:.2f}) rot={cfg.rotation_deg:.2f}deg",
                f"Radial: k1={cfg.radial_k1:.6f}, k2={cfg.radial_k2:.6f}",
                f"Overlay alpha: {float(self.sensor_alpha_spin.value()):.2f}",
            ]
            self.sensor_info.setPlainText("\n".join(lines))
        except Exception as exc:
            if not silent:
                QMessageBox.critical(self, "Sensor processing failed", str(exc))

    def _save_sensor_overlay(self, _checked: bool = False) -> None:
        if self.sensor_overlay_rgb is None:
            QMessageBox.warning(self, "No overlay", "Run sensor correction first.")
            return
        save_path, _ = QFileDialog.getSaveFileName(
            self,
            "Save corrected overlay",
            "sensor_overlay.png",
            "PNG (*.png);;JPEG (*.jpg *.jpeg)",
        )
        if not save_path:
            return
        out = Path(save_path)
        if out.suffix.lower() not in {".png", ".jpg", ".jpeg"}:
            out = out.with_suffix(".png")
        try:
            Image.fromarray(np.asarray(self.sensor_overlay_rgb, dtype=np.uint8)).save(out)
        except Exception as exc:
            QMessageBox.critical(self, "Save failed", str(exc))
            return
        QMessageBox.information(self, "Saved", f"Overlay saved:\n{out}")

    def _refresh_sensors_view(self) -> None:
        if not hasattr(self, "sensor_base_canvas"):
            return
        self.sensor_base_canvas.set_image(self.sensor_base_image if self.sensor_base_image is not None else None)
        self.sensor_corrected_canvas.set_image(self.sensor_corrected_rgb if self.sensor_corrected_rgb is not None else None)
        self.sensor_overlay_canvas.set_image(self.sensor_overlay_rgb if self.sensor_overlay_rgb is not None else None)
        if self.sensor_base_image is None or self.sensor_data_raw is None:
            self.sensor_info.setPlainText(
                "Additional Sensors tab supports fluorescence and hyperspectral overlay.\n"
                "Load a base B/W image, load sensor data, then apply optical correction from JSON."
            )

    def _browse_consolidation_root(self, _checked: bool = False) -> None:
        directory = QFileDialog.getExistingDirectory(self, "Select measurements root folder")
        if not directory:
            return
        self.cons_root_edit.setText(str(Path(directory)))

    def _browse_consolidation_output(self, _checked: bool = False) -> None:
        directory = QFileDialog.getExistingDirectory(self, "Select output folder")
        if not directory:
            return
        self.cons_output_edit.setText(str(Path(directory)))

    def _browse_consolidation_source_images(self, _checked: bool = False) -> None:
        directory = QFileDialog.getExistingDirectory(self, "Select original images folder")
        if not directory:
            return
        source_dir = Path(directory)
        self.cons_source_images_edit.setText(str(source_dir))
        if not self.cons_output_edit.text().strip():
            self.cons_output_edit.setText(str(source_dir / "segmentation_masks"))

    def _populate_consolidation_preset_choices(self) -> None:
        if not hasattr(self, "cons_preset_combo"):
            return
        combo = self.cons_preset_combo
        current_data = combo.currentData()
        combo.blockSignals(True)
        combo.clear()
        if hasattr(self, "pyphenotyper_preset_combo"):
            for idx in range(self.pyphenotyper_preset_combo.count()):
                combo.addItem(
                    self.pyphenotyper_preset_combo.itemText(idx),
                    self.pyphenotyper_preset_combo.itemData(idx),
                )
            preferred_data = self.pyphenotyper_preset_combo.currentData()
        else:
            preferred_data = current_data
        if preferred_data is None:
            preferred_data = current_data
        target_idx = combo.findData(preferred_data)
        if target_idx < 0 and combo.count() > 0:
            target_idx = 0
        if target_idx >= 0:
            combo.setCurrentIndex(target_idx)
        combo.blockSignals(False)

    def _on_consolidation_preset_changed(self, _index: int = 0) -> None:
        if not hasattr(self, "cons_preset_combo") or not hasattr(self, "pyphenotyper_preset_combo"):
            return
        preset_key = self.cons_preset_combo.currentData()
        if preset_key is None:
            return
        seg_idx = self.pyphenotyper_preset_combo.findData(preset_key)
        if seg_idx < 0:
            return
        if int(self.pyphenotyper_preset_combo.currentIndex()) == int(seg_idx):
            return
        self.pyphenotyper_preset_combo.blockSignals(True)
        self.pyphenotyper_preset_combo.setCurrentIndex(seg_idx)
        self.pyphenotyper_preset_combo.blockSignals(False)
        self._apply_pyphenotyper_preset(str(preset_key), mark_dirty=False)
        self._refresh_model_view()

    def _consolidation_preview_search_roots(self) -> list[Path]:
        roots: list[Path] = []
        source_text = self.cons_source_images_edit.text().strip() if hasattr(self, "cons_source_images_edit") else ""
        if source_text:
            source_dir = Path(source_text).expanduser()
            if source_dir.exists():
                roots.append(source_dir.resolve())
        return roots

    def _run_consolidation_with_segmentation(self, _checked: bool = False) -> None:
        source_text = self.cons_source_images_edit.text().strip() if hasattr(self, "cons_source_images_edit") else ""
        if not source_text:
            QMessageBox.warning(self, "Missing original images", "Select the original images folder first.")
            return
        source_dir = Path(source_text).expanduser()
        if not source_dir.exists() or not source_dir.is_dir():
            QMessageBox.warning(self, "Missing original images", f"Folder not found:\n{source_dir}")
            return

        output_text = self.cons_output_edit.text().strip() if hasattr(self, "cons_output_edit") else ""
        output_dir = Path(output_text).expanduser() if output_text else (source_dir / "segmentation_masks")
        output_dir.mkdir(parents=True, exist_ok=True)
        self.cons_output_edit.setText(str(output_dir))
        self.cons_root_edit.setText(str(output_dir))

        if hasattr(self, "inference_backend_combo"):
            backend_idx = self.inference_backend_combo.findData("pyphenotyper")
            if backend_idx >= 0 and str(self.inference_backend_combo.currentData() or "") != "pyphenotyper":
                self.inference_backend_combo.setCurrentIndex(backend_idx)

        if hasattr(self, "cons_preset_combo") and self.cons_preset_combo.count() > 0:
            self._on_consolidation_preset_changed()

        self.pipeline_lazy_input_dir = source_dir
        self.pipeline_lazy_output_dir = output_dir
        if hasattr(self, "pipeline_input_folder_edit"):
            self.pipeline_input_folder_edit.setText(str(source_dir))
        if hasattr(self, "pipeline_output_folder_edit"):
            self.pipeline_output_folder_edit.setText(str(output_dir))
        self._set_pipeline_lazy_latest_outputs(**self._discover_pipeline_lazy_outputs(output_dir))

        self._run_inference_external_folder_lazy(False)
        self.cons_root_edit.setText(str(output_dir))
        self._run_consolidation_scan(False)

    def _run_consolidation_scan(self, _checked: bool = False) -> None:
        root_text = self.cons_root_edit.text().strip()
        if not root_text:
            QMessageBox.warning(self, "Missing folder", "Select a measurements root folder first.")
            return
        root = Path(root_text)
        preview_roots = self._consolidation_preview_search_roots()
        progress = QProgressDialog("Consolidating measurements...", None, 0, 0, self)
        progress.setWindowModality(Qt.WindowModal)
        progress.setCancelButton(None)
        self._prime_progress_dialog(progress, "Consolidating measurements...")
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            df, warnings = consolidate_measurements(root, preview_search_roots=preview_roots)
        except Exception as exc:
            QMessageBox.critical(self, "Consolidation failed", str(exc))
            return
        finally:
            progress.close()
            QApplication.restoreOverrideCursor()

        self.consolidation_preview_search_roots = preview_roots
        self.consolidated_measurements_df = df
        self.consolidated_metric_columns = find_metric_columns(df)
        self.cons_metric_combo.blockSignals(True)
        self.cons_metric_combo.clear()
        for col in self.consolidated_metric_columns:
            self.cons_metric_combo.addItem(str(col), str(col))
        preferred_metric_order = (
            "total_root_length_mm_clean",
            "total_root_length_mm_raw",
            "root_length_mm_clean",
            "combined_root_length_mm",
            "primary_root_length_mm_clean",
            "primary_root_length_mm_raw",
            "root_length_mm_raw",
            "total_root_length_px_clean",
            "total_root_length_px",
            "root_length_px_clean",
            "root_length_px",
            "primary_root_length_px_clean",
            "primary_root_length_px",
            "combined_root_length_px",
            "total_root_area_mm2",
            "total_root_area_px",
            "primary_root_area_mm2",
            "primary_root_area_px",
            "root_area_mm2",
            "root_area_px",
            "shoot_area_mm2",
            "shoot_area_px",
            "pixel_size_mm",
        )
        preferred_metric = None
        for candidate in preferred_metric_order:
            idx = self.cons_metric_combo.findData(candidate)
            if idx >= 0:
                preferred_metric = idx
                break
        if preferred_metric is not None:
            self.cons_metric_combo.setCurrentIndex(int(preferred_metric))
        self.cons_metric_combo.blockSignals(False)

        self._populate_consolidation_table(df)
        has_rows = getattr(df, "empty", True) is False
        self.cons_export_btn.setEnabled(bool(has_rows))
        self.cons_video_btn.setEnabled(bool(has_rows) and bool(self.consolidated_metric_columns))

        info_lines = [f"Rows consolidated: {0 if getattr(df, 'empty', True) else int(len(df))}"]
        if has_rows:
            if "Series" in df.columns:
                info_lines.append(f"Series detected: {int(df['Series'].nunique(dropna=True))}")
            if "PetriDish" in df.columns:
                info_lines.append(f"Petri dishes: {int(df['PetriDish'].nunique(dropna=True))}")
            if "Timestamp" in df.columns:
                parsed_ts = pd.to_datetime(df["Timestamp"], errors="coerce")
                info_lines.append(f"Timeline points: {int(parsed_ts.nunique(dropna=True))}")
        if warnings:
            info_lines.append(f"Warnings: {len(warnings)}")
            info_lines.extend(warnings[:6])
            if len(warnings) > 6:
                info_lines.append(f"... and {len(warnings) - 6} more")
        if self.consolidated_metric_columns:
            info_lines.append("Metrics: " + ", ".join(self.consolidated_metric_columns[:10]))
            if len(self.consolidated_metric_columns) > 10:
                info_lines.append(f"... and {len(self.consolidated_metric_columns) - 10} more")
        self.cons_info.setPlainText("\n".join(info_lines))
        self._refresh_consolidation_preview()

    def _populate_consolidation_table(self, df) -> None:
        if not hasattr(self, "cons_table"):
            return
        self.cons_table.setSortingEnabled(False)
        self.cons_table.clear()
        if df is None or getattr(df, "empty", True):
            self.cons_table.setRowCount(0)
            self.cons_table.setColumnCount(0)
            self.cons_table.setSortingEnabled(True)
            return
        preview_rows = min(600, int(len(df)))
        columns = [str(c) for c in df.columns]
        self.cons_table.setColumnCount(len(columns))
        self.cons_table.setHorizontalHeaderLabels(columns)
        self.cons_table.setRowCount(preview_rows)
        for r in range(preview_rows):
            row = df.iloc[r]
            for c, col in enumerate(columns):
                val = row[col]
                item = QTableWidgetItem("" if val is None else str(val))
                self.cons_table.setItem(r, c, item)
        self.cons_table.resizeColumnsToContents()
        self.cons_table.setSortingEnabled(True)

    def _refresh_consolidation_preview(self, _index: int = 0) -> None:
        if not hasattr(self, "cons_preview_canvas"):
            return
        df = self.consolidated_measurements_df
        metric = self.cons_metric_combo.currentData() if hasattr(self, "cons_metric_combo") else None
        if df is None or getattr(df, "empty", True) or not metric:
            self.cons_preview_canvas.set_image(None)
            return
        try:
            frame = build_metric_plot_preview(df, metric_col=str(metric), width=1600, height=900)
        except Exception:
            frame = None
        self.cons_preview_canvas.set_image(frame)

    def _export_consolidated_table(self, _checked: bool = False) -> None:
        df = self.consolidated_measurements_df
        if df is None or getattr(df, "empty", True):
            QMessageBox.warning(self, "No data", "Run consolidation first.")
            return
        base_dir = self.cons_output_edit.text().strip() or str(Path.home())
        save_path, _ = QFileDialog.getSaveFileName(
            self,
            "Export consolidated measurements",
            str(Path(base_dir) / "consolidated_measurements.csv"),
            "CSV (*.csv);;Excel (*.xlsx)",
        )
        if not save_path:
            return
        out = Path(save_path)
        try:
            path = export_consolidated_measurements(df, out)
        except Exception as exc:
            QMessageBox.critical(self, "Export failed", str(exc))
            return
        QMessageBox.information(self, "Export complete", f"Saved consolidated table:\n{path}")

    def _generate_consolidated_metric_video(self, _checked: bool = False) -> None:
        df = self.consolidated_measurements_df
        metric = self.cons_metric_combo.currentData() if hasattr(self, "cons_metric_combo") else None
        if df is None or getattr(df, "empty", True) or not metric:
            QMessageBox.warning(self, "No data", "Run consolidation and select a metric first.")
            return

        base_dir = self.cons_output_edit.text().strip() or str(Path.home())
        save_path, _ = QFileDialog.getSaveFileName(
            self,
            "Export consolidated metric timelapse",
            str(Path(base_dir) / f"consolidated_{metric}_timelapse.mp4"),
            "MP4 (*.mp4)",
        )
        if not save_path:
            return
        out = Path(save_path)
        if out.suffix.lower() != ".mp4":
            out = out.with_suffix(".mp4")
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            generate_metric_timelapse(
                consolidated_df=df,
                metric_col=str(metric),
                output_path=out,
                config=ConsolidationConfig(fps=max(1, int(self.cons_fps_spin.value())), width=1920, height=1080),
            )
        except Exception as exc:
            QMessageBox.critical(self, "Timelapse generation failed", str(exc))
            return
        finally:
            QApplication.restoreOverrideCursor()
        QMessageBox.information(self, "Timelapse ready", f"Saved metric timelapse MP4:\n{out}")

    def _numeric_table_item(self, value: float | int | None, decimals: int = 4) -> QTableWidgetItem:
        if value is None:
            return QTableWidgetItem("-")
        item = QTableWidgetItem()
        if decimals <= 0:
            item.setData(Qt.EditRole, int(round(float(value))))
        else:
            item.setData(Qt.EditRole, float(round(float(value), decimals)))
        item.setFlags(Qt.ItemIsSelectable | Qt.ItemIsEnabled)
        return item

    def _plant_track_rank_key(self, row: dict[str, object]) -> tuple[int, float, float, str]:
        frames = int(row.get("frames", 0) or 0)
        end_mm = float(row.get("end_mm", 0.0) or 0.0)
        delta_mm = float(row.get("delta_mm", 0.0) or 0.0)
        plant_id = str(row.get("plant_id", ""))
        return (frames, end_mm, delta_mm, plant_id)

    def _default_selected_plant_ids(self, rows: list[dict[str, object]]) -> set[str]:
        expected = int(self.plant_tracks_expected_spin.value()) if hasattr(self, "plant_tracks_expected_spin") else int(self.plant_track_expected_count)
        expected = max(1, expected)
        ranked = sorted(rows, key=self._plant_track_rank_key, reverse=True)
        return {str(row.get("plant_id", "")).strip() for row in ranked[:expected] if str(row.get("plant_id", "")).strip()}

    def _plant_track_selection_map(self, rows: list[dict[str, object]]) -> tuple[dict[str, bool], set[str]]:
        ids_present = {str(row.get("plant_id", "")).strip() for row in rows if str(row.get("plant_id", "")).strip()}
        stale = [plant_id for plant_id in self.plant_track_include_overrides.keys() if plant_id not in ids_present]
        for plant_id in stale:
            self.plant_track_include_overrides.pop(plant_id, None)

        defaults = self._default_selected_plant_ids(rows)
        selection: dict[str, bool] = {}
        for plant_id in ids_present:
            selection[plant_id] = bool(self.plant_track_include_overrides.get(plant_id, plant_id in defaults))
        return selection, defaults

    def _selected_plant_ids_for_export(self) -> set[str] | None:
        rows, _source = self._collect_plant_track_rows()
        if not rows:
            return None
        selection, _defaults = self._plant_track_selection_map(rows)
        return {plant_id for plant_id, include in selection.items() if include}

    def _set_shared_expected_plant_count(
        self,
        value: int,
        *,
        remember_standard: bool = True,
    ) -> int:
        expected = max(1, int(value))
        self.plant_track_expected_count = expected
        self.analytics_track_expected_count = expected
        if remember_standard:
            self.pipeline_lazy_standard_expected_plants = expected

        for widget_name in ("plant_tracks_expected_spin", "analytics_expected_tracks_spin"):
            if not hasattr(self, widget_name):
                continue
            widget = getattr(self, widget_name)
            widget.blockSignals(True)
            widget.setValue(expected)
            widget.blockSignals(False)

        if hasattr(self, "pipeline_lazy_expected_plants_spin"):
            lazy_value = (
                1
                if self._current_pipeline_lazy_analysis_mode() == POTATO_ENDPOINT_ANALYSIS_MODE
                else expected
            )
            self.pipeline_lazy_expected_plants_spin.blockSignals(True)
            self.pipeline_lazy_expected_plants_spin.setValue(lazy_value)
            self.pipeline_lazy_expected_plants_spin.blockSignals(False)
        return expected

    def _on_plant_tracks_expected_changed(self, value: int) -> None:
        self._set_shared_expected_plant_count(value)
        self._refresh_plant_tracks_table()

    def _on_pipeline_lazy_expected_plants_changed(self, value: int) -> None:
        if self._current_pipeline_lazy_analysis_mode() == POTATO_ENDPOINT_ANALYSIS_MODE:
            if hasattr(self, "pipeline_lazy_expected_plants_spin"):
                self.pipeline_lazy_expected_plants_spin.blockSignals(True)
                self.pipeline_lazy_expected_plants_spin.setValue(1)
                self.pipeline_lazy_expected_plants_spin.blockSignals(False)
            return
        self._set_shared_expected_plant_count(value)

    @staticmethod
    def _refresh_pipeline_lazy_root_shoot_video_alias(video_path: object) -> Path | None:
        try:
            source = Path(video_path)
        except (TypeError, ValueError):
            return None
        if not source.exists():
            return None
        alias = source.with_name("npec_root_and_shoot_masks_analysis_video.mp4")
        try:
            if source.resolve() == alias.resolve():
                return source
        except Exception:
            if str(source) == str(alias):
                return source
        try:
            shutil.copy2(source, alias)
        except Exception:
            return source
        return alias if alias.exists() else source

    def _discover_pipeline_lazy_outputs(self, output_dir: object) -> dict[str, Path]:
        try:
            root = Path(output_dir).expanduser()
        except (TypeError, ValueError):
            return {}
        if not str(root):
            return {}

        outputs: dict[str, Path] = {"output_dir": root}
        candidates = {
            "workbook": (
                "npec_potato_endpoint_all_metrics.xlsx",
                "npec_occlusion_aware_all_assets.xlsx",
                "npec_per_plant_all_metrics.xlsx",
                "npec_total_root_and_shoot_all_metrics.xlsx",
                "npec_root_traits_pmi_style.xlsx",
            ),
            "timelapse_csv": (
                "npec_potato_endpoint_phenotypes.csv",
                "npec_occlusion_aware_whole_plate_timelapse.csv",
                "npec_total_root_and_shoot_timelapse.csv",
                "npec_total_root_length_timelapse.csv",
            ),
            "track_summary_csv": (
                "npec_potato_branch_traits.csv",
                "npec_per_plant_track_summary.csv",
                "npec_total_root_and_shoot_from_masks_summary.csv",
                "npec_total_root_length_from_masks_summary.csv",
            ),
            "review_csv": (
                "npec_potato_qc.csv",
                "npec_tracks_needing_review.csv",
            ),
            "frame_review_csv": (
                "npec_potato_plate_label_map.csv",
                "npec_dario_plate_label_map.csv",
                "npec_frames_needing_review.csv",
                MASK_TOTAL_FRAME_REVIEW_FILENAME,
            ),
            "identity_state_json": (
                "npec_potato_analysis_provenance.json",
                "npec_seedling_identity_state.json",
            ),
            "video": (
                "npec_potato_endpoint_overlay_reel.mp4",
                "npec_root_growth_analysis_video.mp4",
                "npec_root_and_shoot_masks_analysis_video.mp4",
            ),
            "video_summary": (
                "npec_potato_finalization_summary.json",
                "npec_root_growth_video_summary.csv",
            ),
        }
        for key, names in candidates.items():
            for name in names:
                candidate = root / name
                if candidate.exists():
                    outputs[key] = candidate
                    break
        return outputs

    def _set_pipeline_lazy_latest_outputs(self, **paths: object) -> None:
        outputs: dict[str, Path] = {}
        for key, value in paths.items():
            key_text = str(key).strip()
            if not key_text or value in (None, ""):
                continue
            try:
                outputs[key_text] = Path(value)
            except TypeError:
                continue
        self.pipeline_lazy_latest_outputs = outputs
        self._refresh_pipeline_lazy_output_actions()

    def _refresh_pipeline_lazy_output_actions(self) -> None:
        outputs = getattr(self, "pipeline_lazy_latest_outputs", {})
        outputs = outputs if isinstance(outputs, dict) else {}
        output_dir = outputs.get("output_dir")
        label_text = str(output_dir) if isinstance(output_dir, Path) else "No Lazy run yet"
        if hasattr(self, "pipeline_lazy_outputs_label"):
            self.pipeline_lazy_outputs_label.setText(label_text)
        button_map = {
            "output_dir": "pipeline_lazy_open_output_folder_btn",
            "workbook": "pipeline_lazy_open_workbook_btn",
            "timelapse_csv": "pipeline_lazy_open_timelapse_btn",
            "track_summary_csv": "pipeline_lazy_open_track_summary_btn",
            "review_csv": "pipeline_lazy_open_review_btn",
            "frame_review_csv": "pipeline_lazy_open_frame_review_btn",
            "identity_state_json": "pipeline_lazy_open_identity_state_btn",
            "video": "pipeline_lazy_open_video_btn",
            "video_summary": "pipeline_lazy_open_video_summary_btn",
        }
        for key, attr_name in button_map.items():
            if not hasattr(self, attr_name):
                continue
            button = getattr(self, attr_name)
            path = outputs.get(key)
            button.setEnabled(isinstance(path, Path) and path.exists())

    def _open_pipeline_lazy_output(self, key: str) -> None:
        outputs = getattr(self, "pipeline_lazy_latest_outputs", {})
        outputs = outputs if isinstance(outputs, dict) else {}
        path = outputs.get(str(key))
        if not isinstance(path, Path) or not path.exists():
            QMessageBox.warning(self, "Missing Lazy output", "That Lazy output is not available yet.")
            self._refresh_pipeline_lazy_output_actions()
            return
        if not QDesktopServices.openUrl(QUrl.fromLocalFile(str(path))):
            QMessageBox.warning(self, "Open Lazy output", f"Could not open:\n{path}")

    def _current_pipeline_lazy_analysis_mode(self) -> str:
        mode = str(
            getattr(self, "pipeline_lazy_analysis_mode", LAZY_COMBINED_ANALYSIS_MODE)
            or LAZY_COMBINED_ANALYSIS_MODE
        )
        if hasattr(self, "pipeline_lazy_analysis_mode_combo"):
            data = self.pipeline_lazy_analysis_mode_combo.currentData()
            if data is not None:
                mode = str(data)
        allowed_modes = set(LAZY_NON_ENDPOINT_ANALYSIS_MODES)
        allowed_modes.add(POTATO_ENDPOINT_ANALYSIS_MODE)
        return mode if mode in allowed_modes else LAZY_COMBINED_ANALYSIS_MODE

    def _current_pipeline_lazy_measure_class_ids(self) -> list[int]:
        text = str(getattr(self, "pipeline_lazy_measure_class_ids_text", "") or "")
        if hasattr(self, "pipeline_lazy_measure_class_ids_edit"):
            text = self.pipeline_lazy_measure_class_ids_edit.text().strip()
        ids = parse_class_id_text(text, fallback=DEFAULT_MASK_TOTAL_CLASS_IDS)
        return ids if ids else [int(v) for v in DEFAULT_MASK_TOTAL_CLASS_IDS]

    def _current_pipeline_lazy_shoot_class_ids(self) -> list[int]:
        text = str(getattr(self, "pipeline_lazy_shoot_class_ids_text", "") or "")
        if hasattr(self, "pipeline_lazy_shoot_class_ids_edit"):
            text = self.pipeline_lazy_shoot_class_ids_edit.text().strip()
        ids = parse_class_id_text(text, fallback=DEFAULT_MASK_TOTAL_SHOOT_CLASS_IDS)
        return ids if ids else [int(v) for v in DEFAULT_MASK_TOTAL_SHOOT_CLASS_IDS]

    def _current_pipeline_lazy_root_metric_mode(self) -> str:
        mode = str(getattr(self, "pipeline_lazy_root_metric_mode", "total") or "total")
        if hasattr(self, "pipeline_lazy_root_metric_combo"):
            data = self.pipeline_lazy_root_metric_combo.currentData()
            if data is not None:
                mode = str(data)
        return mode if mode in {"total", "weighted_total", "primary", "lateral"} else "total"

    def _current_pipeline_lazy_shoot_rgb_rescue_enabled(self) -> bool:
        if hasattr(self, "pipeline_lazy_shoot_rgb_rescue_cb"):
            return bool(self.pipeline_lazy_shoot_rgb_rescue_cb.isChecked())
        return bool(getattr(self, "pipeline_lazy_shoot_rgb_rescue_enabled", False))

    def _lazy_lucifer_context_suggests_green_shoots(
        self,
        *,
        input_dir: Path | None = None,
        output_dir: Path | None = None,
    ) -> bool:
        del input_dir, output_dir
        # Folder names are not modality evidence. Lazy analysis normally uses
        # the shoot mask already selected by the segmentation router; only an
        # explicit RGB mode or checkbox may request detector recomputation.
        return self._current_pyphenotyper_shoot_color_rescue_mode() == "lucifer_green"

    def _lazy_shoot_rgb_rescue_for_run(
        self,
        *,
        input_dir: Path | None = None,
        output_dir: Path | None = None,
    ) -> bool:
        return bool(
            self._current_pipeline_lazy_shoot_rgb_rescue_enabled()
            or self._lazy_lucifer_context_suggests_green_shoots(input_dir=input_dir, output_dir=output_dir)
        )

    def _on_pipeline_lazy_analysis_mode_changed(self, _index: int = 0) -> None:
        previous_mode = str(
            getattr(self, "pipeline_lazy_analysis_mode", LAZY_COMBINED_ANALYSIS_MODE)
            or LAZY_COMBINED_ANALYSIS_MODE
        )
        selected_mode = self._current_pipeline_lazy_analysis_mode()
        is_endpoint = selected_mode == POTATO_ENDPOINT_ANALYSIS_MODE
        if is_endpoint and previous_mode != POTATO_ENDPOINT_ANALYSIS_MODE:
            if hasattr(self, "pipeline_lazy_expected_plants_spin"):
                self.pipeline_lazy_standard_expected_plants = max(
                    1,
                    int(self.pipeline_lazy_expected_plants_spin.value()),
                )
            self.pipeline_lazy_non_endpoint_analysis_mode = (
                previous_mode
                if previous_mode in LAZY_NON_ENDPOINT_ANALYSIS_MODES
                else LAZY_COMBINED_ANALYSIS_MODE
            )
        elif not is_endpoint:
            self.pipeline_lazy_non_endpoint_analysis_mode = selected_mode
        self.pipeline_lazy_analysis_mode = selected_mode
        if hasattr(self, "pipeline_lazy_measure_class_ids_edit"):
            self.pipeline_lazy_measure_class_ids_edit.setEnabled(not is_endpoint)
        if hasattr(self, "pipeline_lazy_shoot_class_ids_edit"):
            self.pipeline_lazy_shoot_class_ids_edit.setEnabled(not is_endpoint)
        if hasattr(self, "pipeline_lazy_root_metric_combo"):
            self.pipeline_lazy_root_metric_combo.setEnabled(not is_endpoint)
        if hasattr(self, "pipeline_lazy_shoot_rgb_rescue_cb"):
            self.pipeline_lazy_shoot_rgb_rescue_cb.setEnabled(not is_endpoint)
        if hasattr(self, "pipeline_lazy_mask_only_video_cb"):
            self.pipeline_lazy_mask_only_video_cb.setEnabled(not is_endpoint)
        if hasattr(self, "pipeline_lazy_analyze_masks_btn"):
            self.pipeline_lazy_analyze_masks_btn.setEnabled(not is_endpoint)
        if hasattr(self, "pipeline_lazy_expected_plants_spin"):
            expected_value = (
                1
                if is_endpoint
                else max(1, int(getattr(self, "pipeline_lazy_standard_expected_plants", 5)))
            )
            self.pipeline_lazy_expected_plants_spin.blockSignals(True)
            self.pipeline_lazy_expected_plants_spin.setValue(expected_value)
            self.pipeline_lazy_expected_plants_spin.blockSignals(False)
            self.pipeline_lazy_expected_plants_spin.setEnabled(not is_endpoint)
        if not is_endpoint:
            self._set_shared_expected_plant_count(
                max(1, int(getattr(self, "pipeline_lazy_standard_expected_plants", 5)))
            )
        self._set_dirty(True)

    def _activate_arabidopsis_lazy_defaults(self, *, lucifer_rgb: bool | None = None) -> None:
        """Apply the validated five-seedling defaults from the Lucifer/Hades runs."""
        if lucifer_rgb is None:
            lucifer_rgb = str(getattr(self, "pyphenotyper_preset_key", "")) == "lucifer_builtin"
        self.pipeline_lazy_standard_expected_plants = 5
        self.pipeline_lazy_measure_class_ids_text = "1,3"
        self.pipeline_lazy_shoot_class_ids_text = "2"
        self.pipeline_lazy_root_metric_mode = "total"
        self.pipeline_lazy_plate_identity_enabled = True
        self.pipeline_lazy_shoot_rgb_rescue_enabled = bool(lucifer_rgb)
        self.pipeline_lazy_video_mask_only = False
        self.pipeline_lazy_analysis_mode = LAZY_COMBINED_ANALYSIS_MODE
        self.pipeline_lazy_non_endpoint_analysis_mode = LAZY_COMBINED_ANALYSIS_MODE
        # Five-seedling ownership assumes that crown lanes remain in a common
        # coordinate system. Make biological previous-frame registration the
        # preset default; users can still disable it for an already registered
        # series or select the dish-frame anchor from the stabilization row.
        self.pipeline_stabilization_enabled = True
        self.pipeline_stabilization_reference_mode = "previous"
        self.pipeline_stabilization_target_mode = "plant_top"

        if hasattr(self, "pipeline_lazy_measure_class_ids_edit"):
            self.pipeline_lazy_measure_class_ids_edit.blockSignals(True)
            self.pipeline_lazy_measure_class_ids_edit.setText(self.pipeline_lazy_measure_class_ids_text)
            self.pipeline_lazy_measure_class_ids_edit.blockSignals(False)
        if hasattr(self, "pipeline_lazy_shoot_class_ids_edit"):
            self.pipeline_lazy_shoot_class_ids_edit.blockSignals(True)
            self.pipeline_lazy_shoot_class_ids_edit.setText(self.pipeline_lazy_shoot_class_ids_text)
            self.pipeline_lazy_shoot_class_ids_edit.blockSignals(False)
        if hasattr(self, "pipeline_lazy_root_metric_combo"):
            metric_index = self.pipeline_lazy_root_metric_combo.findData(self.pipeline_lazy_root_metric_mode)
            if metric_index >= 0:
                self.pipeline_lazy_root_metric_combo.blockSignals(True)
                self.pipeline_lazy_root_metric_combo.setCurrentIndex(metric_index)
                self.pipeline_lazy_root_metric_combo.blockSignals(False)
        if hasattr(self, "pipeline_lazy_shoot_rgb_rescue_cb"):
            self.pipeline_lazy_shoot_rgb_rescue_cb.blockSignals(True)
            self.pipeline_lazy_shoot_rgb_rescue_cb.setChecked(bool(lucifer_rgb))
            self.pipeline_lazy_shoot_rgb_rescue_cb.blockSignals(False)
        if hasattr(self, "pipeline_lazy_mask_only_video_cb"):
            self.pipeline_lazy_mask_only_video_cb.blockSignals(True)
            self.pipeline_lazy_mask_only_video_cb.setChecked(False)
            self.pipeline_lazy_mask_only_video_cb.blockSignals(False)
        if hasattr(self, "pipeline_lazy_analysis_mode_combo"):
            mode_index = self.pipeline_lazy_analysis_mode_combo.findData(LAZY_COMBINED_ANALYSIS_MODE)
            if mode_index >= 0:
                self.pipeline_lazy_analysis_mode_combo.setCurrentIndex(mode_index)
        if hasattr(self, "pipeline_stabilize_before_run_cb"):
            self.pipeline_stabilize_before_run_cb.blockSignals(True)
            self.pipeline_stabilize_before_run_cb.setChecked(True)
            self.pipeline_stabilize_before_run_cb.blockSignals(False)
        if hasattr(self, "pipeline_stabilization_reference_combo"):
            reference_index = self.pipeline_stabilization_reference_combo.findData("previous")
            if reference_index >= 0:
                self.pipeline_stabilization_reference_combo.blockSignals(True)
                self.pipeline_stabilization_reference_combo.setCurrentIndex(reference_index)
                self.pipeline_stabilization_reference_combo.blockSignals(False)
        if hasattr(self, "pipeline_stabilization_target_combo"):
            target_index = self.pipeline_stabilization_target_combo.findData("plant_top")
            if target_index >= 0:
                self.pipeline_stabilization_target_combo.blockSignals(True)
                self.pipeline_stabilization_target_combo.setCurrentIndex(target_index)
                self.pipeline_stabilization_target_combo.blockSignals(False)
        if hasattr(self, "_refresh_pipeline_stabilization_status"):
            self._refresh_pipeline_stabilization_status()
        if hasattr(self, "pyphenotyper_shoot_color_rescue_combo"):
            rescue_mode = "lucifer_green" if lucifer_rgb else "auto"
            rescue_index = self.pyphenotyper_shoot_color_rescue_combo.findData(rescue_mode)
            if rescue_index >= 0:
                self.pyphenotyper_shoot_color_rescue_combo.blockSignals(True)
                self.pyphenotyper_shoot_color_rescue_combo.setCurrentIndex(rescue_index)
                self.pyphenotyper_shoot_color_rescue_combo.blockSignals(False)
            self.pyphenotyper_shoot_color_rescue_mode = rescue_mode
        if hasattr(self, "analytics_tracking_mode_combo"):
            tracking_index = self.analytics_tracking_mode_combo.findData("arabidopsis_crown_lanes")
            if tracking_index >= 0:
                self.analytics_tracking_mode_combo.blockSignals(True)
                self.analytics_tracking_mode_combo.setCurrentIndex(tracking_index)
                self.analytics_tracking_mode_combo.blockSignals(False)

        self._set_shared_expected_plant_count(5)

    def _on_pipeline_lazy_measure_class_ids_changed(self, text: str) -> None:
        self.pipeline_lazy_measure_class_ids_text = str(text or "").strip()
        self._set_dirty(True)

    def _on_pipeline_lazy_shoot_class_ids_changed(self, text: str) -> None:
        self.pipeline_lazy_shoot_class_ids_text = str(text or "").strip()
        self._set_dirty(True)

    def _on_pipeline_lazy_root_metric_changed(self, _index: int = 0) -> None:
        self.pipeline_lazy_root_metric_mode = self._current_pipeline_lazy_root_metric_mode()
        self._set_dirty(True)

    def _on_pipeline_lazy_mask_only_video_changed(self, state: int) -> None:
        self.pipeline_lazy_video_mask_only = bool(state == Qt.Checked)
        self._set_dirty(True)

    def _on_pipeline_lazy_shoot_rgb_rescue_changed(self, state: int) -> None:
        self.pipeline_lazy_shoot_rgb_rescue_enabled = bool(state == Qt.Checked)
